const versePool: PoolEntry[] = [{"theme":"peace","text":{"tr":"“Sakin olun, bilin ki, Tanrı benim! Uluslar arasında yüceleceğim. Yeryüzünde yüceleceğim.”","en":"“Be still, and know that I am God. I will be exalted among the nations. I will be exalted in the earth.”","es":"Estad quietos, y conoced que yo soy Dios: ensalzado he de ser entre las gentes, ensalzado seré en la tierra.","pt":"Aquietai-vos, e sabei que eu sou Deus; sou exaltado entre as nações, sou exaltado na terra.","fr":"Il fait cesser les combats jusqu'au bout de la terre; il rompt les arcs et brise les lances; il brûle les chars au feu.","de":"der den Kriegen steuert in aller Welt, den Bogen zerbricht, Spieße zerschlägt und Wagen mit Feuer verbrennt."},"reference":{"tr":"Mezmur 46:10","en":"Psalm 46:10","es":"Salmo 46:10","pt":"Salmo 46:10","fr":"Psaume 46:10","de":"Psalm 46:10"}},{"theme":"strength","text":{"tr":"Beni güçlendiren Mesih aracılığıyla her şeyi yapabilirim.","en":"I can do all things through Christ, who strengthens me.","es":"Todo lo puedo en Cristo que me fortalece.","pt":"Posso todas as coisas naquele que me fortalece.","fr":"Je puis tout par Christ, qui me fortifie.","de":"Ich vermag alles durch den, der mich mächtig macht, Christus."},"reference":{"tr":"Filipililer 4:13","en":"Philippians 4:13","es":"Filipenses 4:13","pt":"Filipenses 4:13","fr":"Philippiens 4:13","de":"Philipper 4:13"}},{"theme":"trust","text":{"tr":"Bütün yüreğinle Yahve'ye güven, kendi anlayışına dayanma. Bütün yollarında O'nu tanı, O senin yollarını düz edecektir.","en":"Trust in Yahweh with all your heart, and don’t lean on your own understanding. In all your ways acknowledge him, and he will make your paths straight.","es":"Fíate de Jehová de todo tu corazón, y no estribes en tu prudencia. Reconócelo en todos tus caminos, y él enderezará tus veredas.","pt":"Confia no Senhor de todo o teu coração, e não te estribes no teu próprio entendimento. Reconhece-o em todos os teus caminhos, e ele endireitará as tuas veredas.","fr":"Confie-toi en l'Éternel de tout ton cœur, et ne t'appuie point sur ta prudence. Considère-le dans toutes tes voies, et il dirigera tes sentiers.","de":"Verlaß dich auf den HERRN von ganzem Herzen und verlaß dich nicht auf deinen Verstand; sondern gedenke an ihn in allen deinen Wegen, so wird er dich recht führen."},"reference":{"tr":"Süleyman’ın Özdeyişleri 3:5-6","en":"Proverbs 3:5-6","es":"Proverbios 3:5-6","pt":"Provérbios 3:5-6","fr":"Proverbes 3:5-6","de":"Sprüche 3:5-6"}},{"theme":"rest","text":{"tr":"“Ey bütün yorgunlar ve yükü ağır olanlar! Bana gelin, ben size dinlenme veririm.","en":"“Come to me, all you who labor and are heavily burdened, and I will give you rest.","es":"Venid á mí todos los que estáis trabajados y cargados, que yo os haré descansar.","pt":"Vinde a mim, todos os que estai cansados e oprimidos, e eu vos aliviarei.","fr":"Venez à moi, vous tous qui êtes fatigués et chargés, et je vous soulagerai.","de":"Kommet her zu mir alle, die ihr mühselig und beladen seid; ich will euch erquicken."},"reference":{"tr":"Matta 11:28","en":"Matthew 11:28","es":"San Mateo 11:28","pt":"Mateus 11:28","fr":"Matthieu 11:28","de":"Matthäus 11:28"}},{"theme":"hope","text":{"tr":"Çünkü sizin için düşündüğüm düşünceleri biliyorum,” diyor Yahve, “kötü düşünceler değil, size umut ve gelecek vermek için esenlik düşünceleri.","en":"For I know the thoughts that I think toward you,” says Yahweh, “thoughts of peace, and not of evil, to give you hope and a future.","es":"Porque yo sé los pensamientos que tengo acerca de vosotros, dice Jehová, pensamientos de paz, y no de mal, para daros el fin que esperáis.","pt":"Pois eu bem sei os planos que estou projetando para vós, diz o Senhor; planos de paz, e não de mal, para vos dar um futuro e uma esperança.","fr":"Car je sais les pensées que je forme pour vous, dit l'Éternel, pensées de paix et non d'adversité, pour vous donner un avenir et une espérance.","de":"Denn ich weiß wohl, was ich für Gedanken über euch habe, spricht der HERR: Gedanken des Friedens und nicht des Leidens, daß ich euch gebe das Ende, des ihr wartet."},"reference":{"tr":"Yeremya 29:11","en":"Jeremiah 29:11","es":"Jeremías 29:11","pt":"Jeremias 29:11","fr":"Jérémie 29:11","de":"Jeremia 29:11"}},{"theme":"anxiety","text":{"tr":"Hiçbir şeyde kaygılanmayın. Ama her şeyde dua ve dilekle, şükran dolu bir yürekle isteklerinizi Tanrı’ya bildirin.","en":"In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God.","es":"Por nada estéis afanosos; sino sean notorias vuestras peticiones delante de Dios en toda oración y ruego, con hacimiento de gracias.","pt":"Não andeis ansiosos por coisa alguma; antes em tudo sejam os vossos pedidos conhecidos diante de Deus pela oração e súplica com ações de graças;","fr":"Ne vous inquiétez de rien, mais en toute occasion exposez vos demandes devant Dieu, par des prières et des supplications, avec des actions de grâces,","de":"Sorget nichts! sondern in allen Dingen lasset eure Bitten im Gebet und Flehen mit Danksagung vor Gott kund werden."},"reference":{"tr":"Filipililer 4:6","en":"Philippians 4:6","es":"Filipenses 4:6","pt":"Filipenses 4:6","fr":"Philippiens 4:6","de":"Philipper 4:6"}},{"theme":"guidance","text":{"tr":"Sözün ayaklarım için bir fener, yolum için bir ışıktır.","en":"Your word is a lamp to my feet, and a light for my path.","es":"NUN. Lámpara es á mis pies tu palabra, y lumbrera á mi camino.","pt":"Lâmpada para os meus pés é a tua palavra, e luz para o meu caminho.","fr":"Ta parole est une lampe à mon pied, et une lumière sur mon sentier.","de":"Dein Wort ist meine Fußes Leuchte und ein Licht auf meinem Wege."},"reference":{"tr":"Mezmur 119:105","en":"Psalm 119:105","es":"Salmo 119:105","pt":"Salmo 119:105","fr":"Psaume 119:105","de":"Psalm 119:105"}},{"theme":"joy","text":{"tr":"Yahve’nin yarattığı gün bu gündür. İçinde sevinip coşalım!","en":"This is the day that Yahweh has made. We will rejoice and be glad in it!","es":"Este es el día que hizo Jehová: nos gozaremos y alegraremos en él.","pt":"Este é o dia que o Senhor fez; regozijemo-nos, e alegremo-nos nele.","fr":"C'est ici la journée que l'Éternel a faite; égayons-nous et nous réjouissons en elle!","de":"Dies ist der Tag, den der HERR macht; lasset uns freuen und fröhlich darinnen sein."},"reference":{"tr":"Mezmur 118:24","en":"Psalm 118:24","es":"Salmo 118:24","pt":"Salmo 118:24","fr":"Psaume 118:24","de":"Psalm 118:24"}},{"theme":"love","text":{"tr":"Sevgi sabırlıdır ve iyilikseverdir. Sevgi kıskanmaz, övünmez, kibirlenmez. Kaba davranmaz, kendi yolunu aramaz, öfkelenmez, kötülüğün hesabını tutmaz.","en":"Love is patient and is kind; love doesn’t envy. Love doesn’t brag, is not proud, doesn’t behave itself inappropriately, doesn’t seek its own way, is not provoked, takes no account of evil;","es":"La caridad es sufrida, es benigna; la caridad no tiene envidia, la caridad no hace sinrazón, no se ensancha; No es injuriosa, no busca lo suyo, no se irrita, no piensa el mal;","pt":"O amor é sofredor, é benigno; o amor não é invejoso; o amor não se vangloria, não se ensoberbece, não se porta inconvenientemente, não busca os seus próprios interesses, não se irrita, não suspeita mal;","fr":"La charité est patiente, elle est pleine de bonté; la charité n'est point envieuse; la charité ne se vante pas, elle ne s'enfle point d'orgueil; Elle n'est point malhonnête; elle ne cherche point son intérêt; elle ne s'aigrit point; elle ne pense point à mal;","de":"Die Liebe ist langmütig und freundlich, die Liebe eifert nicht, die Liebe treibt nicht Mutwillen, sie blähet sich nicht, sie stellet sich nicht ungebärdig, sie suchet nicht das Ihre, sie läßt sich nicht erbittern, sie rechnet das Böse nicht zu,"},"reference":{"tr":"1. Korintliler 13:4-5","en":"1 Corinthians 13:4-5","es":"1 Corintios 13:4-5","pt":"1 Coríntios 13:4-5","fr":"1 Corinthiens 13:4-5","de":"1. Korinther 13:4-5"}},{"theme":"gratitude","text":{"tr":"Her şeyde şükredin. Çünkü Tanrı’nın Mesih Yeşua’da sizin için olan isteği budur.","en":"In everything give thanks, for this is the will of God in Christ Jesus toward you.","es":"Dad gracias en todo; porque esta es la voluntad de Dios para con vosotros en Cristo Jesús.","pt":"Em tudo dai graças; porque esta é a vontade de Deus em Cristo Jesus para convosco.","fr":"Rendez grâces en toutes choses; car telle est la volonté de Dieu en Jésus-Christ à votre égard.","de":"seid dankbar in allen Dingen; denn das ist der Wille Gottes in Christo Jesu an euch."},"reference":{"tr":"1. Selanikliler 5:18","en":"1 Thessalonians 5:18","es":"1 Tesalonicenses 5:18","pt":"1 Tessalonicenses 5:18","fr":"1 Thessaloniciens 5:18","de":"1. Thessalonicher 5:18"}},{"theme":"comfort","text":{"tr":"Her türlü tesellinin Tanrısı'na, merhametler Babası’na, Efendimiz Yeşua Mesih’in Tanrısı ve Babası’na övgüler olsun! Tanrı’dan aldığımız teselliyle her türlü sıkıntıda olanları teselli edebilmemiz için bizi tüm sıkıntılarımızda teselli eden O’dur.","en":"Blessed be the God and Father of our Lord Jesus Christ, the Father of mercies and God of all comfort; who comforts us in all our affliction, that we may be able to comfort those who are in any affliction, through the comfort with which we ourselves are comforted by God.","es":"Bendito sea el Dios y Padre del Señor Jesucristo, el Padre de misericordias, y el Dios de toda consolación, El cual nos consuela en todas nuestras tribulaciones, para que podamos también nosotros consolar á los que están en cualquiera angustia, con la consolación con que nosotros somos consolados de Dios.","pt":"Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, o Pai das misericórdias e Deus de toda a consolação, que nos consola em toda a nossa tribulação, para que também possamos consolar os que estiverem em alguma tribulação, pela consolação com que nós mesmos somos consolados por Deus.","fr":"Béni soit Dieu, le Père de notre Seigneur Jésus-Christ, le Père des miséricordes, et le Dieu de toute consolation, Qui nous console dans toutes nos afflictions, afin que, par la consolation dont nous sommes nous-mêmes consolés de Dieu, nous puissions consoler tous ceux qui sont dans quelque affliction.","de":"Gelobet sei Gott und der Vater unsers HERRN Jesu Christi, der Vater der Barmherzigkeit und Gott alles Trostes, der uns tröstet in aller unsrer Trübsal, daß auch wir trösten können, die da sind in allerlei Trübsal, mit dem Trost, damit wir getröstet werden von Gott."},"reference":{"tr":"2. Korintliler 1:3-4","en":"2 Corinthians 1:3-4","es":"2 Corintios 1:3-4","pt":"2 Coríntios 1:3-4","fr":"2 Corinthiens 1:3-4","de":"2. Korinther 1:3-4"}},{"theme":"faith","text":{"tr":"Bu nedenle size diyorum ki, duayla dilediğiniz her şeyi almış olduğunuza inanın. Onlara sahip olacaksınız.","en":"Therefore I tell you, all things whatever you pray and ask for, believe that you have received them, and you shall have them.","es":"Por tanto, os digo que todo lo que orando pidiereis, creed que lo recibiréis, y os vendrá.","pt":"Por isso vos digo que tudo o que pedirdes em oração, crede que o recebereis, e tê-lo-eis.","fr":"C'est pourquoi je vous dis: Tout ce que vous demanderez en priant, croyez que vous le recevrez; et cela vous sera accordé.","de":"Darum sage ich euch: Alles, was ihr bittet in eurem Gebet, glaubet nur, daß ihr's empfangen werdet, so wird's euch werden."},"reference":{"tr":"Markos 11:24","en":"Mark 11:24","es":"Marcos 11:24","pt":"Marcos 11:24","fr":"Marc 11:24","de":"Markus 11:24"}},{"theme":"forgiveness","text":{"tr":"Eğer günahlarımızı itiraf edersek, bize günahlarımızı bağışlayıp bizi her haksızlıktan arındırmak için O sadık ve adildir.","en":"If we confess our sins, he is faithful and righteous to forgive us the sins, and to cleanse us from all unrighteousness.","es":"Si confesamos nuestros pecados, él es fiel y justo para que nos perdone nuestros pecados, y nos limpie de toda maldad.","pt":"Se confessarmos os nossos pecados, ele é fiel e justo para nos perdoar os pecados e nos purificar de toda injustiça.","fr":"Si nous confessons nos péchés, il est fidèle et juste pour nous les pardonner, et pour nous purifier de toute iniquité.","de":"So wir aber unsre Sünden bekennen, so ist er treu und gerecht, daß er uns die Sünden vergibt und reinigt uns von aller Untugend."},"reference":{"tr":"1. Yuhanna 1:9","en":"1 John 1:9","es":"1 Juan 1:9","pt":"1 João 1:9","fr":"1 Jean 1:9","de":"1. Johannes 1:9"}},{"theme":"peace","text":{"tr":"Size esenlik bırakıyorum. Size kendi esenliğimi veriyorum. Ben size dünyanın verdiği gibi vermiyorum. Yüreğiniz sıkılmasın ve korkmasın.","en":"Peace I leave with you. My peace I give to you; not as the world gives, give I to you. Don’t let your heart be troubled, neither let it be fearful.","es":"La paz os dejo, mi paz os doy: no como el mundo la da, yo os la doy. No se turbe vuestro corazón, ni tenga miedo.","pt":"Deixo-vos a paz, a minha paz vos dou; eu não vo-la dou como o mundo a dá. Não se turbe o vosso coração, nem se atemorize.","fr":"Je vous laisse la paix; je vous donne ma paix; je ne vous la donne pas comme le monde la donne. Que votre cœur ne se trouble point, et ne craigne point.","de":"Den Frieden lasse ich euch, meinen Frieden gebe ich euch. Nicht gebe ich euch, wie die Welt gibt. Euer Herz erschrecke nicht und fürchte sich nicht."},"reference":{"tr":"Yuhanna 14:27","en":"John 14:27","es":"Juan 14:27","pt":"João 14:27","fr":"Jean 14:27","de":"Johannes 14:27"}},{"theme":"strength","text":{"tr":"ama Yahve'yi bekleyenler güçlerini tazeleyecekler. Kartal gibi kanatlarla yükselecekler. Koşacaklar ve yorulmayacaklar. Yürüyecekler ve zayıflamayacaklar.","en":"But those who wait for Yahweh will renew their strength. They will mount up with wings like eagles. They will run, and not be weary. They will walk, and not faint.","es":"Mas los que esperan á Jehová tendrán nuevas fuerzas; levantarán las alas como águilas; correrán, y no se cansarán; caminarán, y no se fatigarán.","pt":"mas os que esperam no Senhor renovarão as suas forças; subirão com asas como águias; correrão, e não se cansarão; andarão, e não se fatigarão.","fr":"Mais ceux qui s'attendent à l'Éternel reprennent de nouvelles forces. Les ailes leur reviennent comme aux aigles. Ils courront, et ne se fatigueront point; ils marcheront, et ne se lasseront point.","de":"aber die auf den HERRN harren, kriegen neue Kraft, daß sie auffahren mit Flügeln wie Adler, daß sie laufen und nicht matt werden, daß sie wandeln und nicht müde werden."},"reference":{"tr":"Yeşaya 40:31","en":"Isaiah 40:31","es":"Isaías 40:31","pt":"Isaías 40:31","fr":"Ésaïe 40:31","de":"Jesaja 40:31"}},{"theme":"trust","text":{"tr":"David’in mezmuru Yahve benim çobanımdır, hiç eksiğim olmaz.","en":"Yahweh is my shepherd: I shall lack nothing.","es":"Salmo de David. JEHOVÁ es mi pastor; nada me faltará.","pt":"O Senhor é o meu pastor; nada me faltará.","fr":"Psaume de David. L'Éternel est mon berger; je n'aurai point de disette.","de":"Ein Psalm Davids. Der HERR ist mein Hirte; mir wird nichts mangeln."},"reference":{"tr":"Mezmur 23:1","en":"Psalm 23:1","es":"Salmo 23:1","pt":"Salmo 23:1","fr":"Psaume 23:1","de":"Psalm 23:1"}},{"theme":"rest","text":{"tr":"Beni yeşil çayırlarda yatırır. Sakin suların yanına götürür. Canımı onarır. Adı uğruna doğruluk yollarında bana rehberlik eder.","en":"He makes me lie down in green pastures. He leads me beside still waters. He restores my soul. He guides me in the paths of righteousness for his name’s sake.","es":"En lugares de delicados pastos me hará yacer: junto á aguas de reposo me pastoreará. Confortará mi alma; guiaráme por sendas de justicia por amor de su nombre.","pt":"Deitar-me faz em pastos verdejantes; guia-me mansamente a águas tranqüilas. Refrigera a minha alma; guia-me nas veredas da justiça por amor do seu nome.","fr":"Il me fait reposer dans des pâturages herbeux; il me mène le long des eaux tranquilles. Il restaure mon âme, il me conduit dans les sentiers de la justice, à cause de son nom.","de":"Er weidet mich auf grüner Aue und führet mich zum frischen Wasser. Er erquicket meine Seele; er führet mich auf rechter Straße um seines Namens willen."},"reference":{"tr":"Mezmur 23:2-3","en":"Psalm 23:2-3","es":"Salmo 23:2-3","pt":"Salmo 23:2-3","fr":"Psaume 23:2-3","de":"Psalm 23:2-3"}},{"theme":"hope","text":{"tr":"Neden umutsuzsun, ey canım? Neden içim huzursuz? Tanrı’ya umut bağla! Çünkü yine de O’nu öveceğim, yüzümün kurtuluşu ve Tanrım O’dur.","en":"Why are you in despair, my soul? Why are you disturbed within me? Hope in God! For I shall still praise him, the saving help of my countenance, and my God.","es":"¿Por qué te abates, oh alma mía, y por qué te conturbas en mí? Espera á Dios; porque aun le tengo de alabar; es él salvamento delante de mí, y el Dios mío.","pt":"Por que estás abatida, ó minha alma, e por que te perturbas dentro de mim? Espera em Deus, pois ainda o louvarei, a ele que é o meu socorro, e o meu Deus.","fr":"Mes os se brisent, quand mes ennemis m'outragent, disant chaque jour: Où est ton Dieu?","de":"Es ist als ein Mord in meinen Gebeinen, daß mich meine Feinde schmähen, wenn sie täglich zu mir sagen: Wo ist nun dein Gott?"},"reference":{"tr":"Mezmur 42:11","en":"Psalm 42:11","es":"Salmo 42:11","pt":"Salmo 42:11","fr":"Psaume 42:11","de":"Psalm 42:11"}},{"theme":"anxiety","text":{"tr":"Bütün kaygılarınızı O’na bırakın, çünkü O sizi kayırır.","en":"casting all your worries on him, because he cares for you.","es":"Echando toda vuestra solicitud en él, porque él tiene cuidado de vosotros.","pt":"lançando sobre ele toda a vossa ansiedade, porque ele tem cuidado de vós.","fr":"Vous déchargeant sur lui de tous vos soucis, parce qu'il a soin de vous.","de":"Alle Sorge werfet auf ihn; denn er sorgt für euch."},"reference":{"tr":"1. Petrus 5:7","en":"1 Peter 5:7","es":"1 Pedro 5:7","pt":"1 Pedro 5:7","fr":"1 Pierre 5:7","de":"1. Petrus 5:7"}},{"theme":"guidance","text":{"tr":"Bütün yollarında O'nu tanı, O senin yollarını düz edecektir.","en":"In all your ways acknowledge him, and he will make your paths straight.","es":"Reconócelo en todos tus caminos, y él enderezará tus veredas.","pt":"Reconhece-o em todos os teus caminhos, e ele endireitará as tuas veredas.","fr":"Considère-le dans toutes tes voies, et il dirigera tes sentiers.","de":"sondern gedenke an ihn in allen deinen Wegen, so wird er dich recht führen."},"reference":{"tr":"Süleyman’ın Özdeyişleri 3:6","en":"Proverbs 3:6","es":"Proverbios 3:6","pt":"Provérbios 3:6","fr":"Proverbes 3:6","de":"Sprüche 3:6"}},{"theme":"joy","text":{"tr":"Bu şeyleri size, sevincim sizde kalsın ve sevinciniz tamamlansın diye söyledim.”","en":"I have spoken these things to you, that my joy may remain in you, and that your joy may be made full.","es":"Estas cosas os he hablado, para que mi gozo esté en vosotros, y vuestro gozo sea cumplido.","pt":"Estas coisas vos tenho dito, para que o meu gozo permaneça em vós, e o vosso gozo seja completo.","fr":"Je vous ai dit ces choses, afin que ma joie demeure en vous, et que votre joie soit accomplie.","de":"Solches rede ich zu euch, auf daß meine Freude in euch bleibe und eure Freude vollkommen werde."},"reference":{"tr":"Yuhanna 15:11","en":"John 15:11","es":"Juan 15:11","pt":"João 15:11","fr":"Jean 15:11","de":"Johannes 15:11"}},{"theme":"love","text":{"tr":"Çünkü Tanrı dünyayı o kadar sevdi ki, biricik Oğlu’nu verdi. Öyle ki, O’na iman eden hiç kimse mahvolmasın, ancak sonsuz yaşama sahip olsun.","en":"For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life.","es":"Porque de tal manera amó Dios al mundo, que ha dado á su Hijo unigénito, para que todo aquel que en él cree, no se pierda, mas tenga vida eterna.","pt":"Porque Deus amou o mundo de tal maneira que deu o seu Filho unigênito, para que todo aquele que nele crê não pereça, mas tenha a vida eterna.","fr":"Car Dieu a tant aimé le monde, qu'il a donné son Fils unique, afin que quiconque croit en lui ne périsse point, mais qu'il ait la vie éternelle.","de":"Also hat Gott die Welt geliebt, daß er seinen eingeborenen Sohn gab, auf daß alle, die an ihn glauben, nicht verloren werden, sondern das ewige Leben haben."},"reference":{"tr":"Yuhanna 3:16","en":"John 3:16","es":"Juan 3:16","pt":"João 3:16","fr":"Jean 3:16","de":"Johannes 3:16"}},{"theme":"gratitude","text":{"tr":"Yahve’ye şükredin, çünkü O iyidir, çünkü sevgi dolu iyiliği sonsuza dek sürer.","en":"Give thanks to Yahweh, for he is good, for his loving kindness endures forever.","es":"ALABAD á Jehová, porque es bueno; porque para siempre es su misericordia.","pt":"Dai graças ao Senhor, porque ele é bom; porque a sua benignidade dura para sempre;","fr":"Célébrez l'Éternel, car il est bon, car sa miséricorde demeure à toujours!","de":"Danket dem HERRN; denn er ist freundlich, und seine Güte währet ewiglich."},"reference":{"tr":"Mezmur 107:1","en":"Psalm 107:1","es":"Salmo 107:1","pt":"Salmo 107:1","fr":"Psaume 107:1","de":"Psalm 107:1"}},{"theme":"comfort","text":{"tr":"Ne mutlu yas tutanlara, çünkü onlar teselli edilecekler.","en":"Blessed are those who mourn, for they shall be comforted.","es":"Bienaventurados los que lloran: porque ellos recibirán consolación.","pt":"Bem-aventurados os que choram, porque eles serão consolados.","fr":"Heureux ceux qui sont dans l'affliction; car ils seront consolés.","de":"Selig sind, die da Leid tragen; denn sie sollen getröstet werden."},"reference":{"tr":"Matta 5:4","en":"Matthew 5:4","es":"San Mateo 5:4","pt":"Mateus 5:4","fr":"Matthieu 5:4","de":"Matthäus 5:4"}},{"theme":"faith","text":{"tr":"Çünkü imanla yürüyoruz, gözle değil.","en":"for we walk by faith, not by sight.","es":"(Porque por fe andamos, no por vista;)","pt":"(porque andamos por fé, e não por vista);","fr":"(Car nous marchons par la foi, et non par la vue. )","de":"denn wir wandeln im Glauben, und nicht im Schauen."},"reference":{"tr":"2. Korintliler 5:7","en":"2 Corinthians 5:7","es":"2 Corintios 5:7","pt":"2 Coríntios 5:7","fr":"2 Corinthiens 5:7","de":"2. Korinther 5:7"}},{"theme":"forgiveness","text":{"tr":"Birbirinize karşı iyi yürekli, şefkatli olun. Tıpkı Tanrı’nın sizi Mesih’te bağışladığı gibi, siz de birbirinizi bağışlayın.","en":"And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.","es":"Antes sed los unos con los otros benignos, misericordiosos, perdonándoos los unos á los otros, como también Dios os perdonó en Cristo.","pt":"Antes sede bondosos uns para com os outros, compassivos, perdoando-vos uns aos outros, como também Deus vos perdoou em Cristo.","fr":"Mais soyez, les uns envers les autres, bons, miséricordieux, vous pardonnant les uns aux autres, comme Dieu vous a aussi pardonné en Christ.","de":"Seid aber untereinander freundlich, herzlich und vergebet einer dem andern, gleichwie Gott euch auch vergeben hat in Christo."},"reference":{"tr":"Efesliler 4:32","en":"Ephesians 4:32","es":"Efesios 4:32","pt":"Efésios 4:32","fr":"Éphésiens 4:32","de":"Epheser 4:32"}},{"theme":"peace","text":{"tr":"Hiçbir şeyde kaygılanmayın. Ama her şeyde dua ve dilekle, şükran dolu bir yürekle isteklerinizi Tanrı’ya bildirin. Ve Tanrı’nın her anlayışı aşan esenliği Mesih Yeşua aracılığıyla yüreklerinizi ve düşüncelerinizi koruyacaktır.","en":"In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God. And the peace of God, which surpasses all understanding, will guard your hearts and your thoughts in Christ Jesus.","es":"Por nada estéis afanosos; sino sean notorias vuestras peticiones delante de Dios en toda oración y ruego, con hacimiento de gracias. Y la paz de Dios, que sobrepuja todo entendimiento, guardará vuestros corazones y vuestros entendimientos en Cristo Jesús.","pt":"Não andeis ansiosos por coisa alguma; antes em tudo sejam os vossos pedidos conhecidos diante de Deus pela oração e súplica com ações de graças; e a paz de Deus, que excede todo o entendimento, guardará os vossos corações e os vossos pensamentos em Cristo Jesus.","fr":"Ne vous inquiétez de rien, mais en toute occasion exposez vos demandes devant Dieu, par des prières et des supplications, avec des actions de grâces, Et la paix de Dieu qui surpasse toute intelligence, gardera vos cœurs et vos pensées en Jésus-Christ.","de":"Sorget nichts! sondern in allen Dingen lasset eure Bitten im Gebet und Flehen mit Danksagung vor Gott kund werden. Und der Friede Gottes, welcher höher ist denn alle Vernunft, bewahre eure Herzen und Sinne in Christo Jesu!"},"reference":{"tr":"Filipililer 4:6-7","en":"Philippians 4:6-7","es":"Filipenses 4:6-7","pt":"Filipenses 4:6-7","fr":"Philippiens 4:6-7","de":"Philipper 4:6-7"}},{"theme":"strength","text":{"tr":"Müzik şefi için - Alamot - Korahoğulları ezgisi Tanrı sığınağımız ve gücümüzdür, sıkıntıda hemen yardıma hazırdır.","en":"God is our refuge and strength, a very present help in trouble.","es":"Al Músico principal: de los hijos de Coré: Salmo sobre Alamoth. DIOS es nuestro amparo y fortaleza, nuestro pronto auxilio en las tribulaciones.","pt":"Deus é o nosso refúgio e fortaleza, socorro bem presente na angústia.","fr":"Au maître-chantre. Cantique des enfants de Coré, sur Alamoth (jeunes filles).","de":"Ein Lied der Kinder Korah, von der Jugend, vorzusingen."},"reference":{"tr":"Mezmur 46:1","en":"Psalm 46:1","es":"Salmo 46:1","pt":"Salmo 46:1","fr":"Psaume 46:1","de":"Psalm 46:1"}},{"theme":"trust","text":{"tr":"“Ne mutlu, Yahve'ye güvenen, ve güveni Yahve'de olan insana.","en":"“Blessed is the man who trusts in Yahweh, and whose confidence is in Yahweh.","es":"Bendito el varón que se fía en Jehová, y cuya confianza es Jehová.","pt":"Bendito o varão que confia no Senhor, e cuja esperança é o Senhor.","fr":"Béni soit l'homme qui se confie en l'Éternel, dont l'Éternel est la confiance!","de":"Gesegnet aber ist der Mann, der sich auf den HERRN verläßt und des Zuversicht der HERR ist."},"reference":{"tr":"Yeremya 17:7","en":"Jeremiah 17:7","es":"Jeremías 17:7","pt":"Jeremias 17:7","fr":"Jérémie 17:7","de":"Jeremia 17:7"}},{"theme":"rest","text":{"tr":"Ve dedi, “Varlığım seninle birlikte gidecek, sana rahat vereceğim.”","en":"He said, “My presence will go with you, and I will give you rest.”","es":"Y él dijo: Mi rostro irá contigo, y te haré descansar.","pt":"Respondeu-lhe o Senhor: Eu mesmo irei contigo, e eu te darei descanso.","fr":"Et l'Éternel dit: Ma face ira, et je te donnerai du repos.","de":"Er sprach: Mein Angesicht soll vorangehen; damit will ich dich leiten."},"reference":{"tr":"Mısır’dan Çıkış 33:14","en":"Exodus 33:14","es":"Éxodo 33:14","pt":"Êxodo 33:14","fr":"Exode 33:14","de":"2. Mose 33:14"}},{"theme":"hope","text":{"tr":"Yahve'nin sevgi dolu iyiliklerinden ötürü tükenmedik, çünkü merhametleri son bulmaz. Onlar her sabah yenilenir. Senin sadakatin büyüktür.","en":"It is because of Yahweh’s loving kindnesses that we are not consumed, because his compassion doesn’t fail. They are new every morning. Great is your faithfulness.","es":"Es por la misericordia de Jehová que no somos consumidos, porque nunca decayeron sus misericordias. Nuevas son cada mañana; grande es tu fidelidad.","pt":"A benignidade do Senhor jamais acaba, as suas misericórdias não têm fim; renovam-se cada manhã. Grande é a tua fidelidade.","fr":"Ce sont les bontés de l'Éternel, que nous n'ayons pas été consumés; ses compassions n'ont point défailli. Elles se renouvellent chaque matin; ta fidélité est grande!","de":"Die Güte des HERRN ist's, daß wir nicht gar aus sind; seine Barmherzigkeit hat noch kein Ende, sondern sie ist alle Morgen neu, und deine Treue ist groß."},"reference":{"tr":"Ağıtlar 3:22-23","en":"Lamentations 3:22-23","es":"Lamentaciones 3:22-23","pt":"Lamentações 3:22-23","fr":"Lamentations 3:22-23","de":"Klagelieder 3:22-23"}},{"theme":"anxiety","text":{"tr":"Bu nedenle yarın için kaygılanmayın, çünkü yarın kendisi için kaygı çekecektir. Her günün derdi kendine yeter.”","en":"Therefore don’t be anxious for tomorrow, for tomorrow will be anxious for itself. Each day’s own evil is sufficient.","es":"Así que, no os congojéis por el día de mañana; que el día de mañana traerá su fatiga: basta al día su afán.","pt":"Não vos inquieteis, pois, pelo dia de amanhã; porque o dia de amanhã cuidará de si mesmo. Basta a cada dia o seu mal.","fr":"Ne soyez donc point en souci pour le lendemain; car le lendemain aura souci de ce qui le regarde. A chaque jour suffit sa peine.","de":"Darum sorgt nicht für den andern Morgen; denn der morgende Tag wird für das Seine sorgen. Es ist genug, daß ein jeglicher Tag seine eigene Plage habe."},"reference":{"tr":"Matta 6:34","en":"Matthew 6:34","es":"San Mateo 6:34","pt":"Mateus 6:34","fr":"Matthieu 6:34","de":"Matthäus 6:34"}},{"theme":"guidance","text":{"tr":"Eğiteceğim seni, gideceğin yolu sana öğreteceğim. Gözüm üzerinde, sana öğüt vereceğim.","en":"I will instruct you and teach you in the way which you shall go. I will counsel you with my eye on you.","es":"Te haré entender, y te enseñaré el camino en que debes andar: sobre ti fijaré mis ojos.","pt":"Instruir-te-ei, e ensinar-te-ei o caminho que deves seguir; aconselhar-te-ei, tendo-te sob a minha vista.","fr":"Je te rendrai intelligent, m'a dit l'Éternel, je t'enseignerai le chemin où tu dois marcher; je te conduirai; mon œil sera sur toi.","de":"\"Ich will dich unterweisen und dir den Weg zeigen, den du wandeln sollst; ich will dich mit meinen Augen leiten.\""},"reference":{"tr":"Mezmur 32:8","en":"Psalm 32:8","es":"Salmo 32:8","pt":"Salmo 32:8","fr":"Psaume 32:8","de":"Psalm 32:8"}},{"theme":"joy","text":{"tr":"Çünkü öfkesi bir an içindir. Lütfu ise bir ömür. Ağlayış bir gece kalabilir, ama sabahleyin sevinç gelir.","en":"For his anger is but for a moment. His favor is for a lifetime. Weeping may stay for the night, but joy comes in the morning.","es":"Porque un momento será su furor; mas en su voluntad está la vida: por la tarde durará el lloro, y á la mañana vendrá la alegría.","pt":"Porque a sua ira dura só um momento; no seu favor está a vida. O choro pode durar uma noite; pela manhã, porém, vem o cântico de júbilo.","fr":"Chantez à l'Éternel, vous, ses bien-aimés, et célébrez la mémoire de sa sainteté!","de":"Ihr Heiligen, lobsinget dem HERRN; danket und preiset seine Heiligkeit!"},"reference":{"tr":"Mezmur 30:5","en":"Psalm 30:5","es":"Salmo 30:5","pt":"Salmo 30:5","fr":"Psaume 30:5","de":"Psalm 30:5"}},{"theme":"love","text":{"tr":"Bizse O’nu seviyoruz, çünkü önce O bizi sevdi.","en":"We love him, because he first loved us.","es":"Nosotros le amamos á él, porque él nos amó primero.","pt":"Nós amamos, porque ele nos amou primeiro.","fr":"Pour nous, nous l'aimons, parce qu'il nous a aimés le premier.","de":"Lasset uns ihn lieben; denn er hat uns zuerst geliebt."},"reference":{"tr":"1. Yuhanna 4:19","en":"1 John 4:19","es":"1 Juan 4:19","pt":"1 João 4:19","fr":"1 Jean 4:19","de":"1. Johannes 4:19"}},{"theme":"gratitude","text":{"tr":"Şükranla kapılarına, övgüyle avlularına girin. Şükredin O’na, adını yüceltin.","en":"Enter into his gates with thanksgiving, into his courts with praise. Give thanks to him, and bless his name.","es":"Entrad por sus puertas con reconocimiento, por sus atrios con alabanza: alabadle, bendecid su nombre.","pt":"Entrai pelas suas portas com ação de graças, e em seus átrios com louvor; dai-lhe graças e bendizei o seu nome.","fr":"Entrez dans ses portes avec des actions de grâces, dans ses parvis avec la louange; célébrez-le, bénissez son nom","de":"Geht zu seinen Toren ein mit Danken, zu seinen Vorhöfen mit Loben; danket ihm, lobet seinen Namen!"},"reference":{"tr":"Mezmur 100:4","en":"Psalm 100:4","es":"Salmo 100:4","pt":"Salmo 100:4","fr":"Psaume 100:4","de":"Psalm 100:4"}},{"theme":"comfort","text":{"tr":"Yahve yüreği kırık olanlara yakındır, ruhu ezilmiş olanları kurtarır.","en":"Yahweh is near to those who have a broken heart, and saves those who have a crushed spirit.","es":"Cercano está Jehová á los quebrantados de corazón; y salvará á los contritos de espíritu.","pt":"Perto está o Senhor dos que têm o coração quebrantado, e salva os contritos de espírito.","fr":"Quand les justes crient, l'Éternel les exauce, et il les délivre de toutes leurs détresses.","de":"Wenn die Gerechten schreien, so hört der HERR und errettet sie aus all ihrer Not."},"reference":{"tr":"Mezmur 34:18","en":"Psalm 34:18","es":"Salmo 34:18","pt":"Salmo 34:18","fr":"Psaume 34:18","de":"Psalm 34:18"}},{"theme":"faith","text":{"tr":"Onlara, “İnançsızlığınızdan ötürü” dedi. “Size doğrusunu söyleyeyim, hardal tanesi kadar imanınız olsa şu dağa, ‘Buradan şuraya taşın’ derseniz, taşınır; sizin için imkânsız hiçbir şey olmayacaktır.","en":"He said to them, “Because of your unbelief. For most certainly I tell you, if you have faith as a grain of mustard seed, you will tell this mountain, ‘Move from here to there,’ and it will move; and nothing will be impossible for you.","es":"Y Jesús les dijo: Por vuestra incredulidad; porque de cierto os digo, que si tuviereis fe como un grano de mostaza, diréis á este monte: Pásate de aquí allá: y se pasará: y nada os será imposible.","pt":"Disse-lhes ele: Por causa da vossa pouca fé; pois em verdade vos digo que, se tiverdes fé como um grão de mostarda direis a este monte: Passa daqui para acolá, e ele há de passar; e nada vos será impossível.","fr":"Et Jésus leur répondit: C'est à cause de votre incrédulité; car je vous dis en vérité que si vous aviez de la foi comme un grain de moutarde, vous diriez à cette montagne: Transporte-toi d'ici là, et elle s'y transporterait, et rien ne vous serait impossible.","de":"Jesus aber antwortete und sprach zu ihnen: Um eures Unglaubens willen. Denn wahrlich ich sage euch: So ihr Glauben habt wie ein Senfkorn, so mögt ihr sagen zu diesem Berge: Hebe dich von hinnen dorthin! so wird er sich heben; und euch wird nichts unmöglich sein."},"reference":{"tr":"Matta 17:20","en":"Matthew 17:20","es":"San Mateo 17:20","pt":"Mateus 17:20","fr":"Matthieu 17:20","de":"Matthäus 17:20"}},{"theme":"forgiveness","text":{"tr":"Doğu batıdan ne kadar uzaksa, isyanlarımızı bizden o kadar uzaklaştırdı.","en":"As far as the east is from the west, so far has he removed our transgressions from us.","es":"Cuanto está lejos el oriente del occidente, hizo alejar de nosotros nuestras rebeliones.","pt":"Quanto o oriente está longe do ocidente, tanto tem ele afastado de nós as nossas transgressões.","fr":"Il a éloigné de nous nos iniquités, autant que l'orient est éloigné de l'occident.","de":"So ferne der Morgen ist vom Abend, läßt er unsre Übertretungen von uns sein."},"reference":{"tr":"Mezmur 103:12","en":"Psalm 103:12","es":"Salmo 103:12","pt":"Salmo 103:12","fr":"Psaume 103:12","de":"Psalm 103:12"}},{"theme":"peace","text":{"tr":"Sana güvendiği için, aklı kararlı olan kişiyi tam bir esenlik içinde tutacaksın.","en":"You will keep whoever’s mind is steadfast in perfect peace, because he trusts in you.","es":"Tú le guardarás en completa paz, cuyo pensamiento en ti persevera; porque en ti se ha confiado.","pt":"Tu conservarás em paz aquele cuja mente está firme em ti; porque ele confia em ti.","fr":"Tu gardes au cœur ferme une paix assurée, parce qu'il se confie en toi.","de":"Du erhältst stets Frieden nach gewisser Zusage; denn man verläßt sich auf dich."},"reference":{"tr":"Yeşaya 26:3","en":"Isaiah 26:3","es":"Isaías 26:3","pt":"Isaías 26:3","fr":"Ésaïe 26:3","de":"Jesaja 26:3"}},{"theme":"strength","text":{"tr":"Korkma, çünkü ben seninleyim. Korkma, çünkü ben senin Tanrın'ım. Seni güçlendireceğim. Evet sana yardım edeceğim. Evet, doğruluğumun sağ eliyle sana destek olacağım.","en":"Don’t you be afraid, for I am with you. Don’t be dismayed, for I am your God. I will strengthen you. Yes, I will help you. Yes, I will uphold you with the right hand of my righteousness.","es":"No temas, que yo soy contigo; no desmayes, que yo soy tu Dios que te esfuerzo: siempre te ayudaré, siempre te sustentaré con la diestra de mi justicia.","pt":"não temas, porque eu sou contigo; não te assombres, porque eu sou teu Deus; eu te fortaleço, e te ajudo, e te sustento com a destra da minha justiça.","fr":"Ne crains point, car je suis avec toi; ne sois point éperdu, car je suis ton Dieu! Je te fortifie, je t'aide, et je te maintiens par la droite de ma justice.","de":"fürchte dich nicht, ich bin mit dir; weiche nicht, denn ich bin dein Gott; ich stärke dich, ich helfe dir auch, ich erhalte dich durch die rechte Hand meiner Gerechtigkeit."},"reference":{"tr":"Yeşaya 41:10","en":"Isaiah 41:10","es":"Isaías 41:10","pt":"Isaías 41:10","fr":"Ésaïe 41:10","de":"Jesaja 41:10"}},{"theme":"trust","text":{"tr":"Korktuğumda, sana güvenirim.","en":"When I am afraid, I will put my trust in you.","es":"En el día que temo, yo en ti confío.","pt":"No dia em que eu temer, hei de confiar em ti.","fr":"Tout le jour mes adversaires me poursuivent; car plusieurs font la guerre contre moi, ô Dieu Très-Haut!","de":"Meine Feinde schnauben täglich; denn viele streiten stolz wider mich."},"reference":{"tr":"Mezmur 56:3","en":"Psalm 56:3","es":"Salmo 56:3","pt":"Salmo 56:3","fr":"Psaume 56:3","de":"Psalm 56:3"}},{"theme":"rest","text":{"tr":"Müzik şefi Yedutun için - David’in mezmuru Canım yalnız Tanrı'da dinlenir. Kurtuluşum O’ndandır.","en":"My soul rests in God alone. My salvation is from him.","es":"Al Músico principal: á Jeduthún: Salmo de David. EN Dios solamente está acallada mi alma: de él viene mi salud.","pt":"Somente em Deus espera silenciosa a minha alma; dele vem a minha salvação.","fr":"Au maître-chantre. Selon Jéduthun. Psaume de David.","de":"Ein Psalm Davids für Jeduthun, vorzusingen."},"reference":{"tr":"Mezmur 62:1","en":"Psalm 62:1","es":"Salmo 62:1","pt":"Salmo 62:1","fr":"Psaume 62:1","de":"Psalm 62:1"}},{"theme":"hope","text":{"tr":"Umut bizi hayal kırıklığına uğratmaz. Çünkü bize verilen Kutsal Ruh aracılığıyla Tanrı’nın sevgisi yüreklerimize dökülmüştür.","en":"and hope doesn’t disappoint us, because God’s love has been poured out into our hearts through the Holy Spirit who was given to us.","es":"Y la esperanza no avergüenza; porque el amor de Dios está derramado en nuestros corazones por el Espíritu Santo que nos es dado.","pt":"e a esperança não desaponta, porquanto o amor de Deus está derramado em nossos corações pelo Espírito Santo que nos foi dado.","fr":"Or, l'espérance ne trompe point, parce que l'amour de Dieu est répandu dans nos cœurs, par l'Esprit-Saint qui nous a été donné.","de":"Hoffnung aber läßt nicht zu Schanden werden. Denn die Liebe Gottes ist ausgegossen in unser Herz durch den heiligen Geist, welcher uns gegeben ist."},"reference":{"tr":"Romalılar 5:5","en":"Romans 5:5","es":"Romanos 5:5","pt":"Romanos 5:5","fr":"Romains 5:5","de":"Römer 5:5"}},{"theme":"anxiety","text":{"tr":"Yükünü Yahve’ye bırak, O sana destek olur. Doğrunun sarsılmasına asla izin vermez.","en":"Cast your burden on Yahweh, and he will sustain you. He will never allow the righteous to be moved.","es":"Echa sobre Jehová tu carga, y él te sustentará; no dejará para siempre caído al justo.","pt":"Lança o teu fardo sobre o Senhor, e ele te susterá; nunca permitirá que o justo seja abalado.","fr":"Les paroles de sa bouche sont plus douces que le beurre, mais la guerre est dans son cœur; ses paroles sont plus onctueuses que l'huile, mais ce sont des épées nues.","de":"Ihr Mund ist glätter denn Butter, und sie haben Krieg im Sinn; ihre Worte sind gelinder denn Öl, und sind doch bloße Schwerter."},"reference":{"tr":"Mezmur 55:22","en":"Psalm 55:22","es":"Salmo 55:22","pt":"Salmo 55:22","fr":"Psaume 55:22","de":"Psalm 55:22"}},{"theme":"guidance","text":{"tr":"siz sağa ve sola sapınca, arkandan kulakların şöyle bir ses duyacak: “Yol budur. İçinde yürüyün.”","en":"and when you turn to the right hand, and when you turn to the left, your ears will hear a voice behind you, saying, “This is the way. Walk in it.”","es":"Entonces tus oídos oirán á tus espaldas palabra que diga: Este es el camino, andad por él; y no echéis á la mano derecha, ni tampoco torzáis á la mano izquierda.","pt":"e os teus ouvidos ouvirão a palavra do que está por detrás de ti, dizendo: Este é o caminho, andai nele; quando vos desviardes para a direita ou para a esquerda.","fr":"Et quand vous irez à droite, ou quand vous irez à gauche, vos oreilles entendront derrière vous la voix qui dira: C'est ici le chemin, marchez-y!","de":"und deine Ohren werden hören hinter dir her das Wort sagen also: dies ist der Weg; den gehet, sonst weder zur Rechten noch zur Linken!"},"reference":{"tr":"Yeşaya 30:21","en":"Isaiah 30:21","es":"Isaías 30:21","pt":"Isaías 30:21","fr":"Ésaïe 30:21","de":"Jesaja 30:21"}},{"theme":"joy","text":{"tr":"Ama Ruh’un ürünüyse sevgi, sevinç, esenlik, sabır, nezaket, iyilik, iman,","en":"But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faith,","es":"Mas el fruto del Espíritu es: caridad, gozo, paz, tolerancia, benignidad, bondad, fe,","pt":"Mas o fruto do Espírito é: o amor, o gozo, a paz, a longanimidade, a benignidade, a bondade, a fidelidade.","fr":"Mais le fruit de l'Esprit est la charité, la joie, la paix, la patience, la bonté, l'amour du bien, la fidélité, la douceur, la tempérance;","de":"Die Frucht aber des Geistes ist Liebe, Freude, Friede, Geduld, Freundlichkeit, Gütigkeit, Glaube, Sanftmut, Keuschheit."},"reference":{"tr":"Galatyalılar 5:22","en":"Galatians 5:22","es":"Gálatas 5:22","pt":"Gálatas 5:22","fr":"Galates 5:22","de":"Galater 5:22"}},{"theme":"love","text":{"tr":"“Benim buyruğum şudur: Sizi sevdiğim gibi siz de birbirinizi sevin.","en":"“This is my commandment, that you love one another, even as I have loved you.","es":"Este es mi mandamiento: Que os améis los unos á los otros, como yo os he amado.","pt":"O meu mandamento é este: Que vos ameis uns aos outros, assim como eu vos amei.","fr":"Mon commandement, c'est que vous vous aimiez les uns les autres, comme je vous ai aimés.","de":"Das ist mein Gebot, daß ihr euch untereinander liebet, gleichwie ich euch liebe."},"reference":{"tr":"Yuhanna 15:12","en":"John 15:12","es":"Juan 15:12","pt":"João 15:12","fr":"Jean 15:12","de":"Johannes 15:12"}},{"theme":"gratitude","text":{"tr":"Söylediğiniz ya da yaptığınız her şeyi Efendi Yeşua’nın adıyla, O’nun aracılığıyla Baba Tanrı’ya şükrederek yapın.","en":"Whatever you do, in word or in deed, do all in the name of the Lord Jesus, giving thanks to God the Father, through him.","es":"Y todo lo que hacéis, sea de palabra, ó de hecho, hacedlo todo en el nombre del Señor Jesús, dando gracias á Dios Padre por él.","pt":"E tudo quanto fizerdes por palavras ou por obras, fazei-o em nome do Senhor Jesus, dando por ele graças a Deus Pai.","fr":"Et quoi que vous fassiez, en paroles, ou en œuvres, faites tout au nom du Seigneur Jésus, rendant grâces par lui à Dieu le Père.","de":"Und alles, was ihr tut mit Worten oder mit Werken, das tut alles in dem Namen des HERRN Jesu, und danket Gott und dem Vater durch ihn."},"reference":{"tr":"Koloseliler 3:17","en":"Colossians 3:17","es":"Colosenses 3:17","pt":"Colossenses 3:17","fr":"Colossiens 3:17","de":"Kolosser 3:17"}},{"theme":"comfort","text":{"tr":"Ey gökler, ezgi söyleyin, ey yeryüzü sevinçle coş! Ey dağlar, ezgi söylemeye başlayın! Çünkü Yahve halkını avuttu, kederli olanlarına da acıyacak.","en":"Sing, heavens; and be joyful, earth; and break out into singing, mountains: for Yahweh has comforted his people, and will have compassion on his afflicted.","es":"Cantad alabanzas, oh cielos, y alégrate, tierra; y prorrumpid en alabanzas, oh montes: porque Jehová ha consolado su pueblo, y de sus pobres tendrá misericordia.","pt":"Cantai, ó céus, e exulta, ó terra, e vós, montes, estalai de júbilo, porque o Senhor consolou o seu povo, e se compadeceu dos seus aflitos.","fr":"Cieux, chantez de joie! Terre, réjouis-toi! Montagnes, éclatez en cris d'allégresse! Car l'Éternel a consolé son peuple; il a compassion de ses affligés.","de":"Jauchzet, ihr Himmel, freue dich, Erde, lobet, ihr Berge, mit Jauchzen; denn der HERR hat sein Volk getröstet und erbarmt sich seiner Elenden."},"reference":{"tr":"Yeşaya 49:13","en":"Isaiah 49:13","es":"Isaías 49:13","pt":"Isaías 49:13","fr":"Ésaïe 49:13","de":"Jesaja 49:13"}},{"theme":"faith","text":{"tr":"Demek ki iman, duymakla, duymak da Tanrı’nın sözü aracılığıyla olur.","en":"So faith comes by hearing, and hearing by the word of God.","es":"Luego la fe es por el oir; y el oir por la palabra de Dios.","pt":"Logo a fé é pelo ouvir, e o ouvir pela palavra de Cristo.","fr":"La foi vient donc de ce qu'on entend; et ce qu'on entend, vient de la parole de Dieu.","de":"So kommt der Glaube aus der Predigt, das Predigen aber aus dem Wort Gottes."},"reference":{"tr":"Romalılar 10:17","en":"Romans 10:17","es":"Romanos 10:17","pt":"Romanos 10:17","fr":"Romains 10:17","de":"Römer 10:17"}},{"theme":"forgiveness","text":{"tr":"Birbirinize katlanın, birinin öbüründen bir şikayeti varsa, Mesih’in sizi bağışladığı gibi, siz de birbirinizi öyle bağışlayın.","en":"bearing with one another, and forgiving each other, if any man has a complaint against any; even as Christ forgave you, so you also do.","es":"Sufriéndoos los unos á los otros, y perdonándoos los unos á los otros si alguno tuviere queja del otro: de la manera que Cristo os perdonó, así también hacedlo vosotros.","pt":"suportando-vos e perdoando-vos uns aos outros, se alguém tiver queixa contra outro; assim como o Senhor vos perdoou, assim fazei vós também.","fr":"Vous supportant les uns les autres, et vous pardonnant les uns aux autres, si l'un a quelque sujet de plainte contre l'autre. Comme Christ vous a pardonné, vous aussi, faites de même.","de":"und vertrage einer den andern und vergebet euch untereinander, so jemand Klage hat wider den andern; gleichwie Christus euch vergeben hat, also auch ihr."},"reference":{"tr":"Koloseliler 3:13","en":"Colossians 3:13","es":"Colosenses 3:13","pt":"Colossenses 3:13","fr":"Colossiens 3:13","de":"Kolosser 3:13"}},{"theme":"peace","text":{"tr":"Esenlik içinde hem yatar, hem uyurum. Çünkü yalnız sen, ey Yahve, güvenlik içinde yaşatırsın beni.","en":"In peace I will both lay myself down and sleep, for you, Yahweh alone, make me live in safety.","es":"En paz me acostaré, y asimismo dormiré; porque solo tú, Jehová, me harás estar confiado.","pt":"Em paz me deitarei e dormirei, porque só tu, Senhor, me fazes habitar em segurança.","fr":"Tu as mis dans mon cœur plus de joie, qu'ils n'en ont quand leur blé et leur vin sont abondants.","de":"Du erfreuest mein Herz, ob jene gleich viel Wein und Korn haben."},"reference":{"tr":"Mezmur 4:8","en":"Psalm 4:8","es":"Salmo 4:8","pt":"Salmo 4:8","fr":"Psaume 4:8","de":"Psalm 4:8"}},{"theme":"strength","text":{"tr":"O bana, “Lütfum sana yeter, çünkü gücüm zayıflıkta tamam olur” dedi. Bu nedenle, Mesih’in gücü üzerimde olsun diye, zayıflıklarımla sevinip daha çok övüneceğim.","en":"He has said to me, “My grace is sufficient for you, for my power is made perfect in weakness.” Most gladly therefore I will rather glory in my weaknesses, that the power of Christ may rest on me.","es":"Y me ha dicho: Bástate mi gracia; porque mi potencia en la flaqueza se perfecciona. Por tanto, de buena gana me gloriaré más bien en mis flaquezas, porque habite en mí la potencia de Cristo.","pt":"e ele me disse: A minha graça te basta, porque o meu poder se aperfeiçoa na fraqueza. Por isso, de boa vontade antes me gloriarei nas minhas fraquezas, a fim de que repouse sobre mim o poder de Cristo.","fr":"Mais il m'a dit: Ma grâce te suffit; car ma force s'accomplit dans la faiblesse. Je me glorifierai donc plus volontiers dans mes infirmités, afin que la force de Christ habite en moi.","de":"Und er hat zu mir gesagt: Laß dir an meiner Gnade genügen; denn meine Kraft ist in den Schwachen mächtig. Darum will ich mich am allerliebsten rühmen meiner Schwachheit, auf daß die Kraft Christi bei mir wohne."},"reference":{"tr":"2. Korintliler 12:9","en":"2 Corinthians 12:9","es":"2 Corintios 12:9","pt":"2 Coríntios 12:9","fr":"2 Corinthiens 12:9","de":"2. Korinther 12:9"}},{"theme":"trust","text":{"tr":"Yahve'ye daima güvenin; çünkü Yah'da, Yahve sonsuz bir Kaya'dır.","en":"Trust in Yahweh forever; for in Yah, Yahweh, is an everlasting Rock.","es":"Confiad en Jehová perpetuamente: porque en el Señor Jehová está la fortaleza de los siglos.","pt":"Confiai sempre no Senhor; porque o Senhor Deus é uma rocha eterna.","fr":"Confiez-vous en l'Éternel, à perpétuité; car l'Éternel, l'Éternel est le rocher des siècles!","de":"Verlasset euch auf den HERRN ewiglich; denn Gott der HERR ist ein Fels ewiglich."},"reference":{"tr":"Yeşaya 26:4","en":"Isaiah 26:4","es":"Isaías 26:4","pt":"Isaías 26:4","fr":"Ésaïe 26:4","de":"Jesaja 26:4"}},{"theme":"rest","text":{"tr":"Yeşua onlara, “Gelin yalnız olarak sakin bir yere çekilin de biraz dinlenin” dedi. Çünkü gelip giden o kadar çoktu ki yemek yemeye bile vakitleri yoktu.","en":"He said to them, “You come apart into a deserted place, and rest awhile.” For there were many coming and going, and they had no leisure so much as to eat.","es":"Y él les dijo: Venid vosotros aparte al lugar desierto, y reposad un poco. Porque eran muchos los que iban y venían, que ni aun tenían lugar de comer.","pt":"Ao que ele lhes disse: Vinde vós, à parte, para um lugar deserto, e descansai um pouco. Porque eram muitos os que vinham e iam, e não tinham tempo nem para comer.","fr":"Et il leur dit: Venez à l'écart, dans un lieu retiré, et prenez un peu de repos; car il allait et venait tant de monde qu'ils n'avaient pas même le temps de manger.","de":"Und er sprach zu ihnen: Lasset uns besonders an eine wüste Stätte gehen und ruht ein wenig. Denn ihr waren viele, die ab und zu gingen; und sie hatten nicht Zeit genug, zu essen."},"reference":{"tr":"Markos 6:31","en":"Mark 6:31","es":"Marcos 6:31","pt":"Marcos 6:31","fr":"Marc 6:31","de":"Markus 6:31"}},{"theme":"hope","text":{"tr":"Şimdi iman, umut edilen şeylerin güvencesi, görünmeyen şeylerin kanıtıdır.","en":"Now faith is assurance of things hoped for, proof of things not seen.","es":"ES pues la fe la sustancia de las cosas que se esperan, la demostración de las cosas que no se ven.","pt":"Ora, a fé é o firme fundamento das coisas que se esperam, e a prova das coisas que não se vêem.","fr":"Or, la foi est une ferme attente des choses qu'on espère, une démonstration de celles qu'on ne voit point.","de":"Es ist aber der Glaube eine gewisse Zuversicht des, das man hofft, und ein Nichtzweifeln an dem, das man nicht sieht."},"reference":{"tr":"İbraniler 11:1","en":"Hebrews 11:1","es":"Hebreos 11:1","pt":"Hebreus 11:1","fr":"Hébreux 11:1","de":"Hebräer 11:1"}},{"theme":"anxiety","text":{"tr":"Bu nedenle size derim ki: ‘Ne yiyip ne içeceğiz?’ diye yaşamınız için, ‘Ne giyeceğiz?’ diye bedeniniz için kaygılanmayın. Yaşam yemekten daha fazlası, beden de giyinmekten daha fazlası değil mi? Bakın gökyüzünde uçan kuşlar ne ekerler ne biçerler ne de ambarda yiyecek biriktirirler. Göksel Babanız onları besler. Siz onlardan çok daha değerli değil misiniz?”","en":"Therefore I tell you, don’t be anxious for your life: what you will eat, or what you will drink; nor yet for your body, what you will wear. Isn’t life more than food, and the body more than clothing? See the birds of the sky, that they don’t sow, neither do they reap, nor gather into barns. Your heavenly Father feeds them. Aren’t you of much more value than they?","es":"Por tanto os digo: No os congojéis por vuestra vida, qué habéis de comer, ó qué habéis de beber; ni por vuestro cuerpo, qué habéis de vestir: ¿no es la vida más que el alimento, y el cuerpo que el vestido? Mirad las aves del cielo, que no siembran, ni siegan, ni allegan en alfolíes; y vuestro Padre celestial las alimenta. ¿No sois vosotros mucho mejores que ellas?","pt":"Por isso vos digo: Não estejais ansiosos quanto à vossa vida, pelo que haveis de comer, ou pelo que haveis de beber; nem, quanto ao vosso corpo, pelo que haveis de vestir. Não é a vida mais do que o alimento, e o corpo mais do que o vestuário? Olhai para as aves do céu, que não semeiam, nem ceifam, nem ajuntam em celeiros; e vosso Pai celestial as alimenta. Não valeis vós muito mais do que elas?","fr":"C'est pourquoi je vous dis: Ne soyez point en souci pour votre vie, de ce que vous mangerez, et de ce que vous boirez; ni pour votre corps, de quoi vous serez vêtus. La vie n'est-elle pas plus que la nourriture, et le corps plus que le vêtement? Regardez les oiseaux de l'air; car ils ne sèment, ni ne moissonnent, ni n'amassent dans des greniers, et votre Père céleste les nourrit. N'êtes-vous pas beaucoup plus qu'eux?","de":"Darum sage ich euch: Sorget nicht für euer Leben, was ihr essen und trinken werdet, auch nicht für euren Leib, was ihr anziehen werdet. Ist nicht das Leben mehr denn Speise? und der Leib mehr denn die Kleidung? Sehet die Vögel unter dem Himmel an: sie säen nicht, sie ernten nicht, sie sammeln nicht in die Scheunen; und euer himmlischer Vater nährt sie doch. Seid ihr denn nicht viel mehr denn sie?"},"reference":{"tr":"Matta 6:25-26","en":"Matthew 6:25-26","es":"San Mateo 6:25-26","pt":"Mateus 6:25-26","fr":"Matthieu 6:25-26","de":"Matthäus 6:25-26"}},{"theme":"guidance","text":{"tr":"Bana yollarını göster, ey Yahve. Bana yönlerini bildir. Bana kendi gerçeğinde yol göster ve öğret, çünkü sen kurtuluşumun Tanrısı’sın, bütün gün seni bekliyorum.","en":"Show me your ways, Yahweh. Teach me your paths. Guide me in your truth, and teach me, For you are the God of my salvation, I wait for you all day long.","es":"Muéstrame, oh Jehová, tus caminos; enséñame tus sendas. Encamíname en tu verdad, y enséñame; porque tú eres el Dios de mi salud: en ti he esperado todo el día.","pt":"Faze-me saber os teus caminhos, Senhor; ensina-me as tuas veredas. Guia-me na tua verdade, e ensina-me; pois tu és o Deus da minha salvação; por ti espero o dia todo.","fr":"Éternel, fais-moi connaître tes voies, enseigne-moi tes sentiers! Fais-moi marcher dans ta vérité et m'enseigne; car tu es le Dieu de ma délivrance, je m'attends à toi tout le jour.","de":"HERR, zeige mir deine Wege und lehre mich deine Steige; leite mich in deiner Wahrheit und lehre mich! Denn du bist der Gott, der mir hilft; täglich harre ich dein."},"reference":{"tr":"Mezmur 25:4-5","en":"Psalm 25:4-5","es":"Salmo 25:4-5","pt":"Salmo 25:4-5","fr":"Psaume 25:4-5","de":"Psalm 25:4-5"}},{"theme":"joy","text":{"tr":"Gözyaşları içinde ekenler, sevinçle biçecekler.","en":"Those who sow in tears will reap in joy.","es":"Los que sembraron con lágrimas, con regocijo segarán.","pt":"Os que semeiam em lágrimas, com cânticos de júbilo segarão.","fr":"Ceux qui sèment avec larmes, moissonneront avec chants de triomphe.","de":"Die mit Tränen säen, werden mit Freuden ernten."},"reference":{"tr":"Mezmur 126:5","en":"Psalm 126:5","es":"Salmo 126:5","pt":"Salmo 126:5","fr":"Psaume 126:5","de":"Psalm 126:5"}},{"theme":"love","text":{"tr":"Ey sevgililer, birbirimizi sevelim. Çünkü sevgi Tanrı’dandır. Seven herkes Tanrı’dan doğmuştur ve Tanrı’yı bilir.","en":"Beloved, let us love one another, for love is of God; and everyone who loves has been born of God, and knows God.","es":"Carísimos, amémonos unos á otros; porque el amor es de Dios. Cualquiera que ama, es nacido de Dios, y conoce á Dios.","pt":"Amados, amemo-nos uns aos outros, porque o amor é de Deus; e todo o que ama é nascido de Deus e conhece a Deus.","fr":"Bien-aimés, aimons-nous les uns les autres; car la charité vient de Dieu, et quiconque aime, est né de Dieu, et connaît Dieu.","de":"Ihr Lieben, lasset uns untereinander liebhaben; denn die Liebe ist von Gott, und wer liebhat, der ist von Gott geboren und kennt Gott."},"reference":{"tr":"1. Yuhanna 4:7","en":"1 John 4:7","es":"1 Juan 4:7","pt":"1 João 4:7","fr":"1 Jean 4:7","de":"1. Johannes 4:7"}},{"theme":"gratitude","text":{"tr":"Yahve’ye şükredin, çünkü O iyidir, sevgi dolu iyiliği sonsuza dek sürer.","en":"Give thanks to Yahweh, for he is good, for his loving kindness endures forever.","es":"ALABAD á Jehová, porque es bueno; porque para siempre es su misericordia.","pt":"Dai graças ao Senhor, porque ele é bom; porque a sua benignidade dura para sempre.","fr":"Célébrez l'Éternel, car il est bon, car sa miséricorde dure éternellement!","de":"Danket dem HERRN; denn er ist freundlich, und seine Güte währet ewiglich."},"reference":{"tr":"Mezmur 118:1","en":"Psalm 118:1","es":"Salmo 118:1","pt":"Salmo 118:1","fr":"Psaume 118:1","de":"Psalm 118:1"}},{"theme":"comfort","text":{"tr":"O, kırık yürekleri iyileştirir, yaralarını sarar.","en":"He heals the broken in heart, and binds up their wounds.","es":"El sana á los quebrantados de corazón, y liga sus heridas.","pt":"sara os quebrantados de coração, e cura-lhes as feridas;","fr":"Qui guérit ceux qui ont le cœur brisé, et qui bande leurs plaies.","de":"Er heilt, die zerbrochnes Herzens sind, und verbindet ihre Schmerzen."},"reference":{"tr":"Mezmur 147:3","en":"Psalm 147:3","es":"Salmo 147:3","pt":"Salmo 147:3","fr":"Psaume 147:3","de":"Psalm 147:3"}},{"theme":"faith","text":{"tr":"Yalnız hiç şüphe duymadan imanla istesin. Çünkü şüphe duyan kişi, rüzgârın sürükleyip savurduğu deniz dalgasına benzer.","en":"But let him ask in faith, without any doubting, for he who doubts is like a wave of the sea, driven by the wind and tossed.","es":"Pero pida en fe, no dudando nada: porque el que duda es semejante á la onda de la mar, que es movida del viento, y echada de una parte á otra.","pt":"Peça-a, porém, com fé, não duvidando; pois aquele que duvida é semelhante à onda do mar, que é sublevada e agitada pelo vento.","fr":"Mais qu'il demande avec foi, sans douter; car celui qui doute, est semblable au flot de la mer qui est agité par le vent et ballotté çà et là.","de":"Er bitte aber im Glauben und zweifle nicht; denn wer da zweifelt, der ist wie die Meereswoge, die vom Winde getrieben und gewebt wird."},"reference":{"tr":"Yakup 1:6","en":"James 1:6","es":"Santiago 1:6","pt":"Tiago 1:6","fr":"Jacques 1:6","de":"Jakobus 1:6"}},{"theme":"forgiveness","text":{"tr":"“Çünkü insanlara suçlarını bağışlarsanız, göksel Babanız da sizin suçlarınızı bağışlar.","en":"“For if you forgive men their trespasses, your heavenly Father will also forgive you.","es":"Porque si perdonareis á los hombres sus ofensas, os perdonará también á vosotros vuestro Padre celestial.","pt":"Porque, se perdoardes aos homens as suas ofensas, também vosso Pai celestial vos perdoará a vós;","fr":"Car si vous pardonnez aux hommes leurs offenses, votre Père céleste vous pardonnera aussi.","de":"Denn so ihr den Menschen ihre Fehler vergebet, so wird euch euer himmlischer Vater auch vergeben,"},"reference":{"tr":"Matta 6:14","en":"Matthew 6:14","es":"San Mateo 6:14","pt":"Mateus 6:14","fr":"Matthieu 6:14","de":"Matthäus 6:14"}},{"theme":"peace","text":{"tr":"Ne mutlu barış yapıcılarına, çünkü onlara Tanrı’nın çocukları denilecek.","en":"Blessed are the peacemakers, for they shall be called children of God.","es":"Bienaventurados los pacificadores: porque ellos serán llamados hijos de Dios.","pt":"Bem-aventurados os pacificadores, porque eles serão chamados filhos de Deus.","fr":"Heureux les pacifiques; car ils seront appelés enfants de Dieu.","de":"Selig sind die Friedfertigen; denn sie werden Gottes Kinder heißen."},"reference":{"tr":"Matta 5:9","en":"Matthew 5:9","es":"San Mateo 5:9","pt":"Mateus 5:9","fr":"Matthieu 5:9","de":"Matthäus 5:9"}},{"theme":"strength","text":{"tr":"Yahve benim gücüm ve kalkanımdır. Yüreğim O’na güvendi ve yardım buldum. Bu nedenle yüreğim coşuyor. Ezgimle O’na şükredeceğim.","en":"Yahweh is my strength and my shield. My heart has trusted in him, and I am helped. Therefore my heart greatly rejoices. With my song I will thank him.","es":"Jehová es mi fortaleza y mi escudo: en él esperó mi corazón, y fuí ayudado; por lo que se gozó mi corazón, y con mi canción le alabaré.","pt":"O Senhor é a minha força e o meu escudo; nele confiou o meu coração, e fui socorrido; pelo que o meu coração salta de prazer, e com o meu cântico o louvarei.","fr":"L'Éternel est ma force et mon bouclier; mon cœur s'est confié en lui, et j'ai été secouru; aussi mon cœur s'est réjoui, et je le loue par mon cantique.","de":"Der HERR ist meine Stärke und mein Schild; auf ihn hofft mein Herz, und mir ist geholfen. Und mein Herz ist fröhlich, und ich will ihm danken mit meinem Lied."},"reference":{"tr":"Mezmur 28:7","en":"Psalm 28:7","es":"Salmo 28:7","pt":"Salmo 28:7","fr":"Psaume 28:7","de":"Psalm 28:7"}},{"theme":"trust","text":{"tr":"Yolunu Yahve'ye teslim et. O’na güven, O da şunu yapacaktır:","en":"Commit your way to Yahweh. Trust also in him, and he will do this:","es":"Encomienda á Jehová tu camino, y espera en él; y él hará.","pt":"Entrega o teu caminho ao Senhor; confia nele, e ele tudo fará.","fr":"Remets ta voie à l'Éternel et te confie en lui, et il agira.","de":"Befiehl dem HERRN deine Wege und hoffe auf ihn; er wird's wohl machen"},"reference":{"tr":"Mezmur 37:5","en":"Psalm 37:5","es":"Salmo 37:5","pt":"Salmo 37:5","fr":"Psaume 37:5","de":"Psalm 37:5"}},{"theme":"rest","text":{"tr":"Bu nedenle, Tanrı’nın halkı için bir Şabat dinlenmesi kalıyor. Tanrı işlerinden nasıl dinlendiyse, O’nun Şabat dinlenmesine girenler de kendi işlerinden öyle dinlenir.","en":"There remains therefore a Sabbath rest for the people of God. For he who has entered into his rest has himself also rested from his works, as God did from his.","es":"Por tanto, queda un reposo para el pueblo de Dios. Porque el que ha entrado en su reposo, también él ha reposado de sus obras, como Dios de las suyas.","pt":"Portanto resta ainda um repouso sabático para o povo de Deus. Pois aquele que entrou no descanso de Deus, esse também descansou de suas obras, assim como Deus das suas.","fr":"Il reste donc au peuple de Dieu un repos de sabbat. Car celui qui est entré dans son repos, se repose aussi de ses œuvres, comme Dieu des siennes.","de":"Darum ist noch eine Ruhe vorhanden dem Volke Gottes. Denn wer zu seiner Ruhe gekommen ist, der ruht auch von seinen Werken gleichwie Gott von seinen."},"reference":{"tr":"İbraniler 4:9-10","en":"Hebrews 4:9-10","es":"Hebreos 4:9-10","pt":"Hebreus 4:9-10","fr":"Hébreux 4:9-10","de":"Hebräer 4:9-10"}},{"theme":"hope","text":{"tr":"Ama ben hep umut ederim, övgülerine övgü eklerim.","en":"But I will always hope, and will add to all of your praise.","es":"Mas yo siempre esperaré, y añadiré sobre toda tu alabanza.","pt":"Mas eu esperarei continuamente, e te louvarei cada vez mais.","fr":"Mais moi, j'espérerai toujours, et je te louerai de plus en plus.","de":"Ich aber will immer harren und will immer deines Ruhmes mehr machen."},"reference":{"tr":"Mezmur 71:14","en":"Psalm 71:14","es":"Salmo 71:14","pt":"Salmo 71:14","fr":"Psaume 71:14","de":"Psalm 71:14"}},{"theme":"anxiety","text":{"tr":"Çünkü ben, Tanrın Yahve, sağ elinden tutup sana, 'Korkma' diyeceğim. 'Ben sana yardım edeceğim.’","en":"For I, Yahweh your God, will hold your right hand, saying to you, ‘Don’t be afraid. I will help you.’","es":"Porque yo Jehová soy tu Dios, que te ase de tu mano derecha, y te dice: No temas, yo te ayudé.","pt":"Porque eu, o Senhor teu Deus, te seguro pela tua mão direita, e te digo: Não temas; eu te ajudarei.","fr":"Car c'est moi, l'Éternel ton Dieu, qui te prends par la main et qui te dis: Ne crains point, je suis ton aide!","de":"Denn ich bin der HERR, dein Gott, der deine rechte Hand stärkt und zu dir spricht: Fürchte dich nicht, ich helfe dir!"},"reference":{"tr":"Yeşaya 41:13","en":"Isaiah 41:13","es":"Isaías 41:13","pt":"Isaías 41:13","fr":"Ésaïe 41:13","de":"Jesaja 41:13"}},{"theme":"guidance","text":{"tr":"Ama içinizden birinin bilgelikte eksiği varsa, herkese cömertçe ve azarlamadan veren Tanrı’dan istesin, kendisine verilecektir.","en":"But if any of you lacks wisdom, let him ask of God, who gives to all liberally and without reproach; and it will be given to him.","es":"Y si alguno de vosotros tiene falta de sabiduría, demándela á Dios, el cual da á todos abundantemente, y no zahiere; y le será dada.","pt":"Ora, se algum de vós tem falta de sabedoria, peça-a a Deus, que a todos dá liberalmente e não censura, e ser-lhe-á dada.","fr":"Et si quelqu'un de vous manque de sagesse, qu'il la demande à Dieu, qui donne à tous libéralement, sans reproche, et elle lui sera donnée.","de":"So aber jemand unter euch Weisheit mangelt, der bitte Gott, der da gibt einfältig jedermann und rücket's niemand auf, so wird sie ihm gegeben werden."},"reference":{"tr":"Yakup 1:5","en":"James 1:5","es":"Santiago 1:5","pt":"Tiago 1:5","fr":"Jacques 1:5","de":"Jakobus 1:5"}},{"theme":"joy","text":{"tr":"Kardeşlerim, çeşitli ayartılara düştüğünüzde bunu tam bir sevinç sayın. Biliyorsunuz ki, imanınızın sınanması dayanıklılık üretir.","en":"Count it all joy, my brothers, when you fall into various temptations, knowing that the testing of your faith produces endurance.","es":"Hermanos míos, tened por sumo gozo cuando cayereis en diversas tentaciones; Sabiendo que la prueba de vuestra fe obra paciencia.","pt":"Meus irmãos, tende por motivo de grande gozo o passardes por várias provações, sabendo que a aprovação da vossa fé produz a perseverança;","fr":"Frères, regardez comme le sujet d'une parfaite joie les diverses tentations qui vous arrivent, Sachant que l'épreuve de votre foi produit la patience.","de":"Meine lieben Brüder, achtet es für eitel Freude, wenn ihr in mancherlei Anfechtungen fallet, und wisset, daß euer Glaube, wenn er rechtschaffen ist, Geduld wirkt."},"reference":{"tr":"Yakup 1:2-3","en":"James 1:2-3","es":"Santiago 1:2-3","pt":"Tiago 1:2-3","fr":"Jacques 1:2-3","de":"Jakobus 1:2-3"}},{"theme":"love","text":{"tr":"Ama Tanrı bize olan sevgisini şununla kanıtlıyor: Biz daha günahkârken, Mesih bizim için öldü.","en":"But God commends his own love toward us, in that while we were yet sinners, Christ died for us.","es":"Mas Dios encarece su caridad para con nosotros, porque siendo aún pecadores, Cristo murió por nosotros.","pt":"Mas Deus dá prova do seu amor para conosco, em que, quando éramos ainda pecadores, Cristo morreu por nós.","fr":"Mais Dieu fait éclater son amour envers nous, en ce que, lorsque nous étions encore des pécheurs, Christ est mort pour nous.","de":"Darum preiset Gott seine Liebe gegen uns, daß Christus für uns gestorben ist, da wir noch Sünder waren."},"reference":{"tr":"Romalılar 5:8","en":"Romans 5:8","es":"Romanos 5:8","pt":"Romanos 5:8","fr":"Romains 5:8","de":"Römer 5:8"}},{"theme":"gratitude","text":{"tr":"Müzik şefi için - “Oğulun Ölümü” makamında - David’in mezmuru Bütün yüreğimle Yahve’ye şükredeceğim. Şaşkınlık verici işlerinin hepsini anlatacağım.","en":"I will give thanks to Yahweh with my whole heart. I will tell of all your marvelous works.","es":"Al Músico principal: sobre Muth-labben: Salmo de David. TE alabaré, oh Jehová, con todo mi corazón; contaré todas tus maravillas.","pt":"Eu te louvarei, Senhor, de todo o meu coração; contarei todas as tuas maravilhas.","fr":"Au maître-chantre. Psaume de David. Sur Muth-Labben (la mort du fils).","de":"Ein Psalm Davids, von der schönen Jugend, vorzusingen."},"reference":{"tr":"Mezmur 9:1","en":"Psalm 9:1","es":"Salmo 9:1","pt":"Salmo 9:1","fr":"Psaume 9:1","de":"Psalm 9:1"}},{"theme":"comfort","text":{"tr":"Annesinin avuttuğu biri gibi, ben de sizi avutacağım. Yeruşalem'de avutulacaksınız.”","en":"As one whom his mother comforts, so will I comfort you. You will be comforted in Jerusalem.”","es":"Como aquel á quien consuela su madre, así os consolaré yo á vosotros, y en Jerusalem tomaréis consuelo.","pt":"Como alguém a quem consola sua mãe, assim eu vos consolarei; e em Jerusalém vós sereis consolados.","fr":"Je vous consolerai comme une mère console son fils, et vous serez consolés dans Jérusalem.","de":"Ich will euch trösten, wie einen seine Mutter tröstet; ja, ihr sollt an Jerusalem ergötzt werden."},"reference":{"tr":"Yeşaya 66:13","en":"Isaiah 66:13","es":"Isaías 66:13","pt":"Isaías 66:13","fr":"Ésaïe 66:13","de":"Jesaja 66:13"}},{"theme":"faith","text":{"tr":"Çünkü iman yoluyla, lütufla kurtuldunuz. Bu sizden değil, Tanrı’nın armağanıdır. Kimse övünmesin diye, işlerden değildir.","en":"for by grace you have been saved through faith, and that not of yourselves; it is the gift of God, not of works, that no one would boast.","es":"Porque por gracia sois salvos por la fe; y esto no de vosotros, pues es don de Dios: No por obras, para que nadie se gloríe.","pt":"Porque pela graça sois salvos, por meio da fé; e isto não vem de vós, é dom de Deus; não vem das obras, para que ninguém se glorie.","fr":"Car vous êtes sauvés par la grâce, par le moyen de la foi; et cela ne vient pas de vous, c'est le don de Dieu; Ce n'est point par les œuvres, afin que personne ne se glorifie.","de":"Denn aus Gnade seid ihr selig geworden durch den Glauben, und das nicht aus euch: Gottes Gabe ist es, nicht aus den Werken, auf daß sich nicht jemand rühme."},"reference":{"tr":"Efesliler 2:8-9","en":"Ephesians 2:8-9","es":"Efesios 2:8-9","pt":"Efésios 2:8-9","fr":"Éphésiens 2:8-9","de":"Epheser 2:8-9"}},{"theme":"forgiveness","text":{"tr":"“Gelin şimdi, birlikte çözelim” diyor Yahve: “Günahlarınız kıpkırmızı olsa da, kar gibi beyaz olacak. Koyu kırmızı gibi kızıl olsalar da yapağı gibi olacaklar.","en":"“Come now, and let us reason together,” says Yahweh: “Though your sins be as scarlet, they shall be as white as snow. Though they be red like crimson, they shall be as wool.","es":"Venid luego, dirá Jehová, y estemos á cuenta: si vuestros pecados fueren como la grana, como la nieve serán emblanquecidos: si fueren rojos como el carmesí, vendrán á ser como blanca lana.","pt":"Vinde, pois, e arrazoemos, diz o Senhor: ainda que os vossos pecados são como a escarlata, eles se tornarão brancos como a neve; ainda que são vermelhos como o carmesim, tornar-se-ão como a lã.","fr":"Venez maintenant et débattons nos droits, dit l'Éternel. Quand vos péchés seraient comme le cramoisi, ils seront blanchis comme la neige; quand ils seraient rouges comme le vermillon, ils deviendront comme la laine.","de":"So kommt denn und laßt uns miteinander rechten, spricht der HERR. Wenn eure Sünde gleich blutrot ist, soll sie doch schneeweiß werden; und wenn sie gleich ist wie Scharlach, soll sie doch wie Wolle werden."},"reference":{"tr":"Yeşaya 1:18","en":"Isaiah 1:18","es":"Isaías 1:18","pt":"Isaías 1:18","fr":"Ésaïe 1:18","de":"Jesaja 1:18"}},{"theme":"peace","text":{"tr":"Tek beden olmak üzere çağrıldınız. Tanrı’nın esenliği yüreklerinizde hüküm sürsün. Şükredici olun!","en":"And let the peace of God rule in your hearts, to which also you were called in one body; and be thankful.","es":"Y la paz de Dios gobierne en vuestros corazones, á la cual asimismo sois llamados en un cuerpo; y sed agradecidos.","pt":"E a paz de Cristo, para a qual também fostes chamados em um corpo, domine em vossos corações; e sede agradecidos.","fr":"Et que la paix de Christ, à laquelle vous avez été appelés en un seul corps, règne dans vos cœurs; et soyez reconnaissants.","de":"Und der Friede Gottes regiere in euren Herzen, zu welchem ihr auch berufen seid in einem Leibe; und seid dankbar!"},"reference":{"tr":"Koloseliler 3:15","en":"Colossians 3:15","es":"Colosenses 3:15","pt":"Colossenses 3:15","fr":"Colossiens 3:15","de":"Kolosser 3:15"}},{"theme":"strength","text":{"tr":"O zaman onlara, “Gidin, yağlı olanı yiyin, tatlı olanı için ve hazırlığı olmayana pay gönderin. Çünkü bugün Efendimiz için kutsaldır. Kederlenmeyin, çünkü Yahve'nin sevinci sizin gücünüzdür.” dedi.","en":"Then he said to them, “Go your way. Eat the fat, drink the sweet, and send portions to him for whom nothing is prepared, for today is holy to our Lord. Don’t be grieved, for the joy of Yahweh is your strength.”","es":"Díjoles luego: Id, comed grosuras, y bebed vino dulce, y enviad porciones á los que no tienen prevenido; porque día santo es á nuestro Señor: y no os entristezcáis, porque el gozo de Jehová es vuestra fortaleza.","pt":"Disse-lhes mais: Ide, comei as gorduras, e bebei as doçuras, e enviai porções aos que não têm nada preparado para si; porque este dia é consagrado ao nosso Senhor. Portanto não vos entristeçais, pois a alegria do Senhor é a vossa força.","fr":"Et ils leur dirent: Allez, mangez des viandes grasses, et buvez du vin doux, et envoyez des portions à ceux qui n'ont rien d'apprêté, car ce jour est consacré à notre Seigneur; ne soyez donc point affligés, car la joie de l'Éternel est votre force.","de":"Darum sprach er zu ihnen: Geht hin und eßt das Fette und trinkt das Süße und sendet denen auch Teile, die nichts für sich bereitet haben; denn dieser Tag ist heilig unserm HERRN. Und bekümmert euch nicht; denn die Freude am HERRN ist eure Stärke."},"reference":{"tr":"Nehemya 8:10","en":"Nehemiah 8:10","es":"Nehemías 8:10","pt":"Neemias 8:10","fr":"Néhémie 8:10","de":"Nehemia 8:10"}},{"theme":"trust","text":{"tr":"Adını bilenler sana güvenecekler, çünkü sen, ey Yahve, seni arayanları terk etmezsin.","en":"Those who know your name will put their trust in you, for you, Yahweh, have not forsaken those who seek you.","es":"Y en ti confiarán los que conocen tu nombre; por cuanto tú, oh Jehová, no desamparaste á los que te buscaron.","pt":"Em ti confiam os que conhecem o teu nome; porque tu, Senhor, não abandonas aqueles que te buscam.","fr":"L'Éternel sera le refuge de l'opprimé, son refuge au temps de la détresse.","de":"Und der HERR ist des Armen Schutz, ein Schutz in der Not."},"reference":{"tr":"Mezmur 9:10","en":"Psalm 9:10","es":"Salmo 9:10","pt":"Salmo 9:10","fr":"Psaume 9:10","de":"Psalm 9:10"}},{"theme":"rest","text":{"tr":"Boşunadır sizin için erken kalkıp geç yatmanız, ey zahmet ekmeği yiyenler. Çünkü O sevdiklerine uyku verir.","en":"It is vain for you to rise up early, to stay up late, eating the bread of toil; for he gives sleep to his loved ones.","es":"Por demás os es el madrugar á levantaros, el veniros tarde á reposar, el comer pan de dolores: pues que á su amado dará Dios el sueño.","pt":"Inútil vos será levantar de madrugada, repousar tarde, comer o pão de dores, pois ele supre aos seus amados enquanto dormem.","fr":"En vain vous vous levez matin, vous vous couchez tard, et vous mangez le pain de douleur; il en donne autant à son bien-aimé pendant son sommeil.","de":"Es ist umsonst, daß ihr früh aufstehet und hernach lange sitzet und esset euer Brot mit Sorgen; denn seinen Freunden gibt er's schlafend."},"reference":{"tr":"Mezmur 127:2","en":"Psalm 127:2","es":"Salmo 127:2","pt":"Salmo 127:2","fr":"Psaume 127:2","de":"Psalm 127:2"}},{"theme":"hope","text":{"tr":"Çünkü umutla kurtulduk, ama görülen umut umut değildir. Kim gördüğü şeyi umut eder? Ama görmediğimizi umarsak, onu sabırla bekleriz.","en":"For we were saved in hope, but hope that is seen is not hope. For who hopes for that which he sees? But if we hope for that which we don’t see, we wait for it with patience.","es":"Porque en esperanza somos salvos; mas la esperanza que se ve, no es esperanza; porque lo que alguno ve, ¿á qué esperarlo? Empero si lo que no vemos esperamos, por paciencia esperamos.","pt":"Porque na esperança fomos salvos. Ora, a esperança que se vê não é esperança; pois o que alguém vê, como o espera? Mas, se esperamos o que não vemos, com paciência o aguardamos.","fr":"Car nous sommes sauvés en espérance. Or, l'espérance que l'on voit n'est plus espérance; en effet, comment espérerait-on ce que l'on voit? Mais si nous espérons ce que nous ne voyons pas, c'est que nous l'attendons avec patience.","de":"Denn wir sind wohl selig, doch in der Hoffnung. Die Hoffnung aber, die man sieht, ist nicht Hoffnung; denn wie kann man des hoffen, das man sieht? So wir aber des hoffen, das wir nicht sehen, so warten wir sein durch Geduld."},"reference":{"tr":"Romalılar 8:24-25","en":"Romans 8:24-25","es":"Romanos 8:24-25","pt":"Romanos 8:24-25","fr":"Romains 8:24-25","de":"Römer 8:24-25"}},{"theme":"anxiety","text":{"tr":"İçimdeki düşüncelerin çokluğunda, senin avutmaların canımı sevindiriyor.","en":"In the multitude of my thoughts within me, your comforts delight my soul.","es":"En la multitud de mis pensamientos dentro de mí, tus consolaciones alegraban mi alma.","pt":"Quando os cuidados do meu coração se multiplicam, as tuas consolações recreiam a minha alma.","fr":"Quand j'avais beaucoup de pensées au-dedans de moi, tes consolations ont réjoui mon âme.","de":"Ich hatte viel Bekümmernisse in meinem Herzen; aber deine Tröstungen ergötzten meine Seele."},"reference":{"tr":"Mezmur 94:19","en":"Psalm 94:19","es":"Salmo 94:19","pt":"Salmo 94:19","fr":"Psaume 94:19","de":"Psalm 94:19"}},{"theme":"guidance","text":{"tr":"Çünkü bu Tanrı sonsuza dek bizim Tanrımız’dır. Ölüme dek O bize yol gösterecektir.","en":"For this God is our God forever and ever. He will be our guide even to death.","es":"Porque este Dios es Dios nuestro eternalmente y para siempre: él nos capitaneará hasta la muerte.","pt":"Porque este Deus é o nosso Deus para todo o sempre; ele será nosso guia até a morte.","fr":"Considérez son rempart, examinez ses palais, pour le raconter à la génération future.","de":"achtet mit Fleiß auf ihre Mauern, durchwandelt ihre Paläste, auf daß ihr davon verkündiget den Nachkommen,"},"reference":{"tr":"Mezmur 48:14","en":"Psalm 48:14","es":"Salmo 48:14","pt":"Salmo 48:14","fr":"Psaume 48:14","de":"Psalm 48:14"}},{"theme":"joy","text":{"tr":"Şükran Mezmuru Ey bütün diyarlar, Yahve’ye sevinçle haykırın! Yahve’ye sevinçle hizmet edin. O’nun huzuruna ezgilerle gelin.","en":"Shout for joy to Yahweh, all you lands! Serve Yahweh with gladness. Come before his presence with singing.","es":"Salmo de alabanza. CANTAD alegres á Dios, habitantes de toda la tierra. Servid á Jehová con alegría: venid ante su acatamiento con regocijo.","pt":"Celebrai com júbilo ao Senhor, todos os habitantes da terra. Servi ao Senhor com alegria, e apresentai-vos a ele com cântico.","fr":"Psaume de louange. Vous, toute la terre, jetez des cris de réjouissance à l'Éternel! Servez l'Éternel avec joie; venez devant sa face avec des cris d'allégresse.","de":"Ein Dankpsalm. Jauchzet dem HERRN, alle Welt! Dient dem HERRN mit Freuden; kommt vor sein Angesicht mit Frohlocken!"},"reference":{"tr":"Mezmur 100:1-2","en":"Psalm 100:1-2","es":"Salmo 100:1-2","pt":"Salmo 100:1-2","fr":"Psaume 100:1-2","de":"Psalm 100:1-2"}},{"theme":"love","text":{"tr":"Size yeni bir buyruk veriyorum: Birbirinizi sevin. Benim sizi sevdiğim gibi siz de birbirinizi sevin. Birbirinize sevginiz olursa, bununla herkes benim öğrencilerim olduğunuzu bilecektir.”","en":"A new commandment I give to you, that you love one another. Just as I have loved you, you also love one another. By this everyone will know that you are my disciples, if you have love for one another.”","es":"Un mandamiento nuevo os doy: Que os améis unos á otros: como os he amado, que también os améis los unos á los otros. En esto conocerán todos que sois mis discípulos, si tuviereis amor los unos con los otros.","pt":"Um novo mandamento vos dou: que vos ameis uns aos outros; assim como eu vos amei a vós, que também vós vos ameis uns aos outros. Nisto conhecerão todos que sois meus discípulos, se tiverdes amor uns aos outros.","fr":"Je vous donne un commandement nouveau; c'est que vous vous aimiez les uns les autres; que, comme je vous ai aimés, vous vous aimiez aussi les uns les autres. C'est à ceci que tous reconnaîtront que vous êtes mes disciples, si vous avez de l'amour les uns pour les autres.","de":"Ein neu Gebot gebe ich euch, daß ihr euch untereinander liebet, wie ich euch geliebt habe, auf daß auch ihr einander liebhabet. Dabei wird jedermann erkennen, daß ihr meine Jünger seid, so ihr Liebe untereinander habt."},"reference":{"tr":"Yuhanna 13:34-35","en":"John 13:34-35","es":"Juan 13:34-35","pt":"João 13:34-35","fr":"Jean 13:34-35","de":"Johannes 13:34-35"}},{"theme":"gratitude","text":{"tr":"Bu nedenle, Efendi Mesih Yeşua’yı kabul ettiğiniz gibi, O’nda yürüyün. O’nda köklenin ve gelişin. Size öğretildiği gibi imanda güçlenin ve şükranla dolup taşın.","en":"As therefore you received Christ Jesus, the Lord, walk in him, rooted and built up in him, and established in the faith, even as you were taught, abounding in it in thanksgiving.","es":"Por tanto, de la manera que habéis recibido al Señor Jesucristo, andad en él: Arraigados y sobreedificados en él, y confirmados en la fe, así como habéis aprendido, creciendo en ella con hacimiento de gracias.","pt":"Portanto, assim como recebestes a Cristo Jesus, o Senhor, assim também nele andai, arraigados e edificados nele, e confirmados na fé, assim como fostes ensinados, abundando em ação de graças.","fr":"Ainsi, comme vous avez reçu le Seigneur Jésus-Christ, marchez avec lui, Enracinés et fondés en lui, et affermis dans la foi, selon que vous avez été enseignés, abondant en elle, avec actions de grâces.","de":"Wie ihr nun angenommen habt den HERRN Christus Jesus, so wandelt in ihm und seid gewurzelt und erbaut in ihm und fest im Glauben, wie ihr gelehrt seid, und seid in demselben reichlich dankbar."},"reference":{"tr":"Koloseliler 2:6-7","en":"Colossians 2:6-7","es":"Colosenses 2:6-7","pt":"Colossenses 2:6-7","fr":"Colossiens 2:6-7","de":"Kolosser 2:6-7"}},{"theme":"comfort","text":{"tr":"Hizmetkârına olan sözün uyarınca, lütfen sevgi dolu iyiliğin bana teselli olsun.","en":"Please let your loving kindness be for my comfort, according to your word to your servant.","es":"Sea ahora tu misericordia para consolarme, conforme á lo que has dicho á tu siervo.","pt":"Sirva, pois, a tua benignidade para me consolar, segundo a palavra que deste ao teu servo.","fr":"Oh! que ta bonté me console, comme tu l'as promis à ton serviteur.","de":"Deine Gnade müsse mein Trost sein, wie du deinem Knecht zugesagt hast."},"reference":{"tr":"Mezmur 119:76","en":"Psalm 119:76","es":"Salmo 119:76","pt":"Salmo 119:76","fr":"Psaume 119:76","de":"Psalm 119:76"}},{"theme":"faith","text":{"tr":"Yeşua ona, “Eğer inanabilirsen, inanan biri için her şey mümkündür!” dedi.","en":"Jesus said to him, “If you can believe, all things are possible to him who believes.”","es":"Y Jesús le dijo: Si puedes creer, al que cree todo es posible.","pt":"Ao que lhe disse Jesus: Se podes! - tudo é possível ao que crê.","fr":"Jésus lui dit: Si tu peux croire, toutes choses sont possibles pour celui qui croit.","de":"Jesus aber sprach zu ihm: Wenn du könntest Glauben! Alle Dinge sind möglich dem, der da glaubt."},"reference":{"tr":"Markos 9:23","en":"Mark 9:23","es":"Marcos 9:23","pt":"Marcos 9:23","fr":"Marc 9:23","de":"Markus 9:23"}},{"theme":"forgiveness","text":{"tr":"Suçları bağışlayan, mirasının kalanının itaatsizliğinin üzerinden geçen senin gibi Tanrı kimdir? Sonsuza dek öfkesini tutmaz, çünkü sevgi dolu iyilikten hoşlanır. Yine bize acıyacak. Suçlarımızı ayaklar altına alacak. Onların bütün günahlarını denizin derinliklerine atacaksın.","en":"Who is a God like you, who pardons iniquity, and passes over the disobedience of the remnant of his heritage? He doesn’t retain his anger forever, because he delights in loving kindness. He will again have compassion on us. He will tread our iniquities under foot; and you will cast all their sins into the depths of the sea.","es":"¿Qué Dios como tú, que perdonas la maldad, y olvidas el pecado del resto de su heredad? No retuvo para siempre su enojo, porque es amador de misericordia. El tornará, él tendrá misericordia de nosotros; él sujetará nuestras iniquidades, y echará en los profundos de la mar todos nuestros pecados.","pt":"Quem é Deus semelhante a ti, que perdoas a iniqüidade, e que te esqueces da transgressão do resto da tua herança? O Senhor não retém a sua ira para sempre, porque ele se deleita na benignidade. Tornará a apiedar-se de nós; pisará aos pés as nossas iniqüidades. Tu lançarás todos os nossos pecados nas profundezas do mar.","fr":"Qui est le Dieu semblable à toi, qui pardonne l'iniquité, et qui passe par-dessus le péché du reste de son héritage? Il ne garde pas à toujours sa colère, car il se plaît à faire miséricorde. Il aura encore compassion de nous, il mettra sous ses pieds nos iniquités. Tu jetteras tous leurs péchés au fond de la mer.","de":"Wo ist solch ein Gott, wie du bist, der die Sünde vergibt und erläßt die Missetat den übrigen seines Erbteils, der seinen Zorn nicht ewiglich behält! denn er ist barmherzig. Er wird sich unser wieder erbarmen, unsere Missetaten dämpfen und alle unsre Sünden in die Tiefen des Meeres werfen."},"reference":{"tr":"Mika 7:18-19","en":"Micah 7:18-19","es":"Miqueas 7:18-19","pt":"Miquéias 7:18-19","fr":"Michée 7:18-19","de":"Micha 7:18-19"}},{"theme":"peace","text":{"tr":"Umut Tanrısı, Kutsal Ruh’un gücüyle umutla dolup taşmanız için imanda sizi tam bir sevinç ve esenlikle doldursun.","en":"Now may the God of hope fill you with all joy and peace in believing, that you may abound in hope, in the power of the Holy Spirit.","es":"Y el Dios de esperanza os llene de todo gozo y paz creyendo, para que abundéis en esperanza por la virtud del Espíritu Santo.","pt":"Ora, o Deus de esperança vos encha de todo o gozo e paz na vossa fé, para que abundeis na esperança pelo poder do Espírito Santo.","fr":"Que le Dieu d'espérance vous remplisse donc de toute sorte de joie et de paix, dans la foi, afin que vous abondiez en espérance, par la puissance du Saint-Esprit.","de":"Der Gott aber der Hoffnung erfülle euch mit aller Freude und Frieden im Glauben, daß ihr völlige Hoffnung habet durch die Kraft des heiligen Geistes."},"reference":{"tr":"Romalılar 15:13","en":"Romans 15:13","es":"Romanos 15:13","pt":"Romanos 15:13","fr":"Romains 15:13","de":"Römer 15:13"}},{"theme":"strength","text":{"tr":"Son olarak, Efendi’de ve O’nun kudretinin gücünde güçlenin.","en":"Finally, be strong in the Lord, and in the strength of his might.","es":"Por lo demás, hermanos míos, confortaos en el Señor, y en la potencia de su fortaleza.","pt":"Finalmente, fortalecei-vos no Senhor e na força do seu poder.","fr":"Au reste, mes frères, fortifiez-vous dans le Seigneur, et par sa force toute puissante.","de":"Zuletzt, meine Brüder, seid stark in dem HERRN und in der Macht seiner Stärke."},"reference":{"tr":"Efesliler 6:10","en":"Ephesians 6:10","es":"Efesios 6:10","pt":"Efésios 6:10","fr":"Éphésiens 6:10","de":"Epheser 6:10"}},{"theme":"trust","text":{"tr":"Yahve iyidir, sıkıntı gününde kaledir; kendisine sığınanları bilir.","en":"Yahweh is good, a stronghold in the day of trouble; and he knows those who take refuge in him.","es":"Bueno es Jehová para fortaleza en el día de la angustia; y conoce á los que en él confían.","pt":"O Senhor é bom, uma fortaleza no dia da angústia; e conhece os que nele confiam.","fr":"L'Éternel est bon; il est une forteresse au jour de la détresse, et il connaît ceux qui se confient en lui.","de":"Der HERR ist gütig und eine Feste zur Zeit der Not und kennt die, die auf ihn trauen."},"reference":{"tr":"Nahum 1:7","en":"Nahum 1:7","es":"Nahum 1:7","pt":"Naum 1:7","fr":"Nahum 1:7","de":"Nahum 1:7"}},{"theme":"rest","text":{"tr":"Çünkü yorgun canı doyurdum, her kederli canı doldurdum.”","en":"For I have satiated the weary soul, and I have replenished every sorrowful soul.”","es":"Porque habré embriagado el alma cansada, y henchido toda alma entristecida.","pt":"Pois saciarei a alma cansada, e fartarei toda alma desfalecida.","fr":"Car j'abreuverai l'âme altérée, et je rassasierai toute âme qui languit.","de":"denn ich will die müden Seelen erquicken und die bekümmerten Seelen sättigen."},"reference":{"tr":"Yeremya 31:25","en":"Jeremiah 31:25","es":"Jeremías 31:25","pt":"Jeremias 31:25","fr":"Jérémie 31:25","de":"Jeremia 31:25"}},{"theme":"hope","text":{"tr":"Efendimiz Yeşua Mesih’in Tanrısı ve Babası’na övgüler olsun! O büyük merhametiyle yeniden doğmamızı sağladı. Yeşua Mesih’i ölümden diriltmekle bizi yaşayan bir umuda, bozulmaz, lekesiz bir mirasa kavuşturdu. Bu miras göklerde sizin için ayrılmıştır.","en":"Blessed be the God and Father of our Lord Jesus Christ, who according to his great mercy caused us to be born again to a living hope through the resurrection of Jesus Christ from the dead,","es":"Bendito el Dios y Padre de nuestro Señor Jesucristo, que según su grande misericordia nos ha regenerado en esperanza viva, por la resurrección de Jesucristo de los muertos,","pt":"Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, que, segundo a sua grande misericórdia, nos regenerou para uma viva esperança, pela ressurreição de Jesus Cristo dentre os mortos,","fr":"Béni soit le Dieu et Père de notre Seigneur Jésus-Christ, qui, selon sa grande miséricorde, nous a fait renaître, pour une espérance vivante par la résurrection de Jésus-Christ d'entre les morts,","de":"Gelobet sei Gott und der Vater unsers HERRN Jesu Christi, der uns nach seiner Barmherzigkeit wiedergeboren hat zu einer lebendigen Hoffnung durch die Auferstehung Jesu Christi von den Toten,"},"reference":{"tr":"1. Petrus 1:3","en":"1 Peter 1:3","es":"1 Pedro 1:3","pt":"1 Pedro 1:3","fr":"1 Pierre 1:3","de":"1. Petrus 1:3"}},{"theme":"anxiety","text":{"tr":"Yahve’yi aradım ve bana yanıt verdi, ve beni tüm korkularımdan kurtardı.","en":"I sought Yahweh, and he answered me, and delivered me from all my fears.","es":"Busqué á Jehová, y él me oyó, y libróme de todos mis temores.","pt":"Busquei ao Senhor, e ele me respondeu, e de todos os meus temores me livrou.","fr":"Magnifiez l'Éternel avec moi; exaltons son nom tous ensemble!","de":"Preiset mit mir den HERRN und laßt uns miteinander seinen Namen erhöhen."},"reference":{"tr":"Mezmur 34:4","en":"Psalm 34:4","es":"Salmo 34:4","pt":"Salmo 34:4","fr":"Psaume 34:4","de":"Psalm 34:4"}},{"theme":"guidance","text":{"tr":"İnsanın yüreği gideceği yolu tasarlar, ama adımlarını Yahve yönlendirir.","en":"A man’s heart plans his course, but Yahweh directs his steps.","es":"El corazón del hombre piensa su camino: mas Jehová endereza sus pasos.","pt":"O coração do homem propõe o seu caminho; mas o Senhor lhe dirige os passos.","fr":"Le cœur de l'homme délibère sur sa conduite; mais l'Éternel dirige ses pas.","de":"Des Menschen Herz erdenkt sich seinen Weg; aber der HERR allein gibt, daß er fortgehe."},"reference":{"tr":"Süleyman’ın Özdeyişleri 16:9","en":"Proverbs 16:9","es":"Proverbios 16:9","pt":"Provérbios 16:9","fr":"Proverbes 16:9","de":"Sprüche 16:9"}},{"theme":"joy","text":{"tr":"Sizin de şimdi kederiniz var. Ama sizi yeniden göreceğim ve yüreğiniz sevinecektir. Sevincinizi kimse sizden alamaz” dedi.","en":"Therefore you now have sorrow, but I will see you again, and your heart will rejoice, and no one will take your joy away from you.","es":"También, pues, vosotros ahora ciertamente tenéis tristeza; mas otra vez os veré, y se gozará vuestro corazón, y nadie quitará de vosotros vuestro gozo.","pt":"Assim também vós agora, na verdade, tendes tristeza; mas eu vos tornarei a ver, e alegrar-se-á o vosso coração, e a vossa alegria ninguém vo-la tirará.","fr":"De même, vous êtes maintenant dans la tristesse; mais je vous verrai de nouveau, et votre cœur se réjouira, et personne ne vous ravira votre joie.","de":"Und ihr habt auch nun Traurigkeit; aber ich will euch wiedersehen, und euer Herz soll sich freuen, und eure Freude soll niemand von euch nehmen."},"reference":{"tr":"Yuhanna 16:22","en":"John 16:22","es":"Juan 16:22","pt":"João 16:22","fr":"Jean 16:22","de":"Johannes 16:22"}},{"theme":"love","text":{"tr":"Baba kendi yüceliğinin zenginliğine göre Ruhu’yla iç varlığınızı kudretle güçlendirmesini, iman aracılığıyla Mesih’in yüreklerinizde bulunmasını dilerim. Bütün kutsallarla birlikte sonuna dek sevgide köklenip temellenmiş olarak, Mesih’in sevgisinin ne kadar geniş ve uzun, yüksek ve derin olduğunu anlamaya, bilgiyi aşan bu sevgiyi bilmeye gücünüz yetsin. Öyle ki, Tanrı’nın bütün doluluğuyla dolasınız.","en":"that Christ may dwell in your hearts through faith; to the end that you, being rooted and grounded in love, may be strengthened to comprehend with all the saints what is the width and length and height and depth, and to know Christ’s love which surpasses knowledge, that you may be filled with all the fullness of God.","es":"Que habite Cristo por la fe en vuestros corazones; para que, arraigados y fundados en amor, Podáis bien comprender con todos los santos cuál sea la anchura y la longura y la profundidad y la altura, Y conocer el amor de Cristo, que excede á todo conocimiento, para que seáis llenos de toda la plenitud de Dios.","pt":"que Cristo habite pela fé nos vossos corações, a fim de que, estando arraigados e fundados em amor, possais compreender, com todos os santos, qual seja a largura, e o comprimento, e a altura, e a profundidade, e conhecer o amor de Cristo, que excede todo o entendimento, para que sejais cheios até a inteira plenitude de Deus.","fr":"Afin que Christ habite dans vos cœurs par la foi; Et que, enracinés et fondés dans la charité, vous puissiez comprendre, avec tous les saints, quelle en est la largeur, la longueur, la profondeur et la hauteur, Et connaître l'amour de Christ, qui surpasse toute connaissance, afin que vous soyez remplis de toute la plénitude de Dieu.","de":"daß Christus wohne durch den Glauben in euren Herzen und ihr durch die Liebe eingewurzelt und gegründet werdet, auf daß ihr begreifen möget mit allen Heiligen, welches da sei die Breite und die Länge und die Tiefe und die Höhe; auch erkennen die Liebe Christi, die doch alle Erkenntnis übertrifft, auf daß ihr erfüllt werdet mit allerlei Gottesfülle."},"reference":{"tr":"Efesliler 3:17-19","en":"Ephesians 3:17-19","es":"Efesios 3:17-19","pt":"Efésios 3:17-19","fr":"Éphésiens 3:17-19","de":"Epheser 3:17-19"}},{"theme":"gratitude","text":{"tr":"Yahve’ye şükredin, çünkü O iyidir, çünkü sevgi dolu iyiliği sonsuza dek sürer.","en":"Give thanks to Yahweh, for he is good; for his loving kindness endures forever.","es":"ALABAD á Jehová, porque es bueno; porque para siempre es su misericordia.","pt":"Dai graças ao Senhor, porque ele é bom; porque a sua benignidade dura para sempre.","fr":"Célébrez l'Éternel, car il est bon; car sa miséricorde dure éternellement!","de":"Danket dem HERRN; denn er ist freundlich, denn seine Güte währet ewiglich."},"reference":{"tr":"Mezmur 136:1","en":"Psalm 136:1","es":"Salmo 136:1","pt":"Salmo 136:1","fr":"Psaume 136:1","de":"Psalm 136:1"}},{"theme":"comfort","text":{"tr":"Onların gözlerinden bütün yaşları silecek. Artık ölüm olmayacak. Artık ne yas, ne ağlayış, ne de acı olacak. Çünkü önceki şeyler gelip geçti.’’","en":"He will wipe away every tear from their eyes. Death will be no more; neither will there be mourning, nor crying, nor pain, any more. The first things have passed away.”","es":"Y limpiará Dios toda lágrima de los ojos de ellos; y la muerte no será más; y no habrá más llanto, ni clamor, ni dolor: porque las primeras cosas son pasadas.","pt":"Ele enxugará de seus olhos toda lágrima; e não haverá mais morte, nem haverá mais pranto, nem lamento, nem dor; porque já as primeiras coisas são passadas.","fr":"Et Dieu essuiera toute larme de leurs yeux, et la mort ne sera plus. Il n'y aura plus ni deuil, ni cri, ni travail; car les premières choses sont passées.","de":"und Gott wird abwischen alle Tränen von ihren Augen, und der Tod wird nicht mehr sein, noch Leid noch Geschrei noch Schmerz wird mehr sein; denn das Erste ist vergangen."},"reference":{"tr":"Vahiy 21:4","en":"Revelation 21:4","es":"Apocalipsis 21:4","pt":"Apocalipse 21:4","fr":"Apocalypse 21:4","de":"Offenbarung 21:4"}},{"theme":"faith","text":{"tr":"İman olmadan Tanrı’yı hoşnut etmek imkânsızdır. Çünkü Tanrı’ya gelen kişi, O’nun var olduğuna ve kendisini arayanları ödüllendirdiğine inanmalıdır.","en":"Without faith it is impossible to be well pleasing to him, for he who comes to God must believe that he exists, and that he is a rewarder of those who seek him.","es":"Empero sin fe es imposible agradar á Dios; porque es menester que el que á Dios se allega, crea que le hay, y que es galardonador de los que le buscan.","pt":"Ora, sem fé é impossível agradar a Deus; porque é necessário que aquele que se aproxima de Deus creia que ele existe, e que é galardoador dos que o buscam.","fr":"Or, il est impossible de lui être agréable sans la foi, car il faut que celui qui s'approche de Dieu, croie que Dieu est, et qu'il est le rémunérateur de ceux qui le cherchent.","de":"Aber ohne Glauben ist's unmöglich, Gott zu gefallen; denn wer zu Gott kommen will, der muß glauben, daß er sei und denen, die ihn suchen, ein Vergelter sein werde."},"reference":{"tr":"İbraniler 11:6","en":"Hebrews 11:6","es":"Hebreos 11:6","pt":"Hebreus 11:6","fr":"Hébreux 11:6","de":"Hebräer 11:6"}},{"theme":"forgiveness","text":{"tr":"Günahımı sana itiraf ettim. Suçumu saklamadım. “Yahve'ye isyanlarımı itiraf edeceğim” dedim. Günahımın suçunu bağışladın. Selah.","en":"I acknowledged my sin to you. I didn’t hide my iniquity. I said, I will confess my transgressions to Yahweh, and you forgave the iniquity of my sin. Selah.","es":"Mi pecado te declaré, y no encubrí mi iniquidad. Confesaré, dije, contra mí mis rebeliones á Jehová; y tú perdonaste la maldad de mi pecado. (Selah.)","pt":"Confessei-te o meu pecado, e a minha iniqüidade não encobri. Disse eu: Confessarei ao Senhor as minhas transgressões; e tu perdoaste a culpa do meu pecado.","fr":"Je t'ai fait connaître mon péché, et je ne t'ai point caché mon iniquité. J'ai dit: Je confesserai mes transgressions à l'Éternel; et tu as ôté la peine de mon péché. (Sélah.)","de":"Darum bekannte ich dir meine Sünde und verhehlte meine Missetat nicht. Ich sprach: Ich will dem HERRN meine Übertretungen bekennen. Da vergabst du mir die Missetat meiner Sünde. (Sela.)"},"reference":{"tr":"Mezmur 32:5","en":"Psalm 32:5","es":"Salmo 32:5","pt":"Salmo 32:5","fr":"Psaume 32:5","de":"Psalm 32:5"}},{"theme":"peace","text":{"tr":"Yahve halkına güç verir. Yahve halkını esenlikle kutsar.","en":"Yahweh will give strength to his people. Yahweh will bless his people with peace.","es":"Jehová dará fortaleza á su pueblo: Jehová bendecirá á su pueblo en paz.","pt":"O Senhor dará força ao seu povo; o Senhor abençoará o seu povo com paz.","fr":"L'Éternel donnera force à son peuple; l'Éternel bénira son peuple par la paix.","de":"Der HERR wird seinem Volk Kraft geben; der HERR wird sein Volk segnen mit Frieden."},"reference":{"tr":"Mezmur 29:11","en":"Psalm 29:11","es":"Salmo 29:11","pt":"Salmo 29:11","fr":"Psaume 29:11","de":"Psalm 29:11"}},{"theme":"strength","text":{"tr":"O Tanrı ki, beni güçle donatır ve yolumu kusursuz kılar.","en":"the God who arms me with strength, and makes my way perfect?","es":"Dios es el que me ciñe de fuerza, é hizo perfecto mi camino;","pt":"Ele é o Deus que me cinge de força e torna perfeito o meu caminho;","fr":"Car qui est Dieu, sinon l'Éternel? Et qui est un rocher, sinon notre Dieu?","de":"Denn wo ist ein Gott außer dem HERRN, oder ein Hort außer unserm Gott?"},"reference":{"tr":"Mezmur 18:32","en":"Psalm 18:32","es":"Salmo 18:32","pt":"Salmo 18:32","fr":"Psaume 18:32","de":"Psalm 18:32"}},{"theme":"trust","text":{"tr":"Ey halkım, O'na her zaman güven. Yüreğini O’nun önünde dök. Tanrı bizim için bir sığınaktır. Selah.","en":"Trust in him at all times, you people. Pour out your heart before him. God is a refuge for us. Selah.","es":"Esperad en él en todo tiempo, oh pueblos; derramad delante de él vuestro corazón: Dios es nuestro amparo. (Selah.)","pt":"Confiai nele, ó povo, em todo o tempo; derramai perante ele o vosso coração; Deus é o nosso refúgio.","fr":"En Dieu est mon salut et ma gloire; mon fort rocher, mon refuge est en Dieu.","de":"Bei Gott ist mein Heil, meine Ehre, der Fels meiner Stärke; meine Zuversicht ist auf Gott."},"reference":{"tr":"Mezmur 62:8","en":"Psalm 62:8","es":"Salmo 62:8","pt":"Salmo 62:8","fr":"Psaume 62:8","de":"Psalm 62:8"}},{"theme":"rest","text":{"tr":"Ey canım, rahatına dön, çünkü Yahve sana cömertçe davrandı.","en":"Return to your rest, my soul, for Yahweh has dealt bountifully with you.","es":"Vuelve, oh alma mía, á tu reposo; porque Jehová te ha hecho bien.","pt":"Volta, minha alma, ao teu repouso, pois o Senhor te fez bem.","fr":"Mon âme, retourne à ton repos, car l'Éternel t'a fait du bien.","de":"Sei nun wieder zufrieden, meine Seele; denn der HERR tut dir Gutes."},"reference":{"tr":"Mezmur 116:7","en":"Psalm 116:7","es":"Salmo 116:7","pt":"Salmo 116:7","fr":"Psaume 116:7","de":"Psalm 116:7"}},{"theme":"hope","text":{"tr":"Yahve'yi bekliyorum. Canım bekliyor. O’nun sözüne umut bağlıyorum.","en":"I wait for Yahweh. My soul waits. I hope in his word.","es":"Esperé yo á Jehová, esperó mi alma; en su palabra he esperado.","pt":"Aguardo ao Senhor; a minha alma o aguarda, e espero na sua palavra.","fr":"J'ai attendu l'Éternel; mon âme l'a attendu, et j'ai eu mon espérance en sa parole.","de":"Ich harre des HERRN; meine Seele harret, und ich hoffe auf sein Wort."},"reference":{"tr":"Mezmur 130:5","en":"Psalm 130:5","es":"Salmo 130:5","pt":"Salmo 130:5","fr":"Psaume 130:5","de":"Psalm 130:5"}},{"theme":"anxiety","text":{"tr":"Yüreğindeki kaygı insanı çökertir, ama hoş söz onun yüreğini sevindirir.","en":"Anxiety in a man’s heart weighs it down, but a kind word makes it glad.","es":"El cuidado congojoso en el corazón del hombre, lo abate; mas la buena palabra lo alegra.","pt":"A ansiedade no coração do homem o abate; mas uma boa palavra o alegra.","fr":"Le chagrin qui est dans le cœur de l'homme, l'accable; mais une bonne parole le réjouit.","de":"Sorge im Herzen kränkt, aber ein freundliches Wort erfreut."},"reference":{"tr":"Süleyman’ın Özdeyişleri 12:25","en":"Proverbs 12:25","es":"Proverbios 12:25","pt":"Provérbios 12:25","fr":"Proverbes 12:25","de":"Sprüche 12:25"}},{"theme":"guidance","text":{"tr":"ve Yahve sana durmadan yol gösterecek, kurak yerlerde canını doyuracak ve kemiklerini güçlendirecek. Sulanmış bir bahçe gibi, suları hiç tükenmeyen bir su kaynağı gibi olacaksın.","en":"and Yahweh will guide you continually, and satisfy your soul in dry places, and make your bones strong; and you shall be like a watered garden, and like a spring of water, whose waters don’t fail.","es":"Y Jehová te pastoreará siempre, y en las sequías hartará tu alma, y engordará tus huesos; y serás como huerta de riego, y como manadero de aguas, cuyas aguas nunca faltan.","pt":"O Senhor te guiará continuamente, e te fartará até em lugares áridos, e fortificará os teus ossos; serás como um jardim regado, e como um manancial, cujas águas nunca falham.","fr":"L'Éternel te conduira continuellement; il te rassasiera dans les lieux arides; il donnera la vigueur à tes os, et tu seras comme un jardin arrosé, comme une source dont les eaux ne trompent jamais.","de":"und der HERR wird dich immerdar führen und deine Seele sättigen in der Dürre und deine Gebeine stärken; und du wirst sein wie ein gewässerter Garten und wie eine Wasserquelle, welcher es nimmer an Wasser fehlt;"},"reference":{"tr":"Yeşaya 58:11","en":"Isaiah 58:11","es":"Isaías 58:11","pt":"Isaías 58:11","fr":"Ésaïe 58:11","de":"Jesaja 58:11"}},{"theme":"joy","text":{"tr":"Müzik şefi için - Korahoğulları’nın mezmuru Ey bütün uluslar, el çırpın. Zafer sesiyle Tanrı'ya sesinizi yükseltin!","en":"Oh clap your hands, all you nations. Shout to God with the voice of triumph!","es":"Al Músico principal: de los hijos de Coré: Salmo. PUEBLOS todos, batid las manos; aclamad á Dios con voz de júbilo.","pt":"Batei palmas, todos os povos; aclamai a Deus com voz de júbilo.","fr":"Au maître-chantre. Psaume des enfants de Coré.","de":"Ein Psalm der Kinder Korah, vorzusingen."},"reference":{"tr":"Mezmur 47:1","en":"Psalm 47:1","es":"Salmo 47:1","pt":"Salmo 47:1","fr":"Psaume 47:1","de":"Psalm 47:1"}},{"theme":"love","text":{"tr":"Tanrı’nın bize olan sevgisini biliyoruz ve buna inandık. Tanrı sevgidir. Sevgide kalan Tanrı’da kalır ve Tanrı da onda kalır.","en":"We know and have believed the love which God has for us. God is love, and he who remains in love remains in God, and God remains in him.","es":"Y nosotros hemos conocido y creído el amor que Dios tiene para con nosotros. Dios es amor; y el que vive en amor, vive en Dios, y Dios en él.","pt":"E nós conhecemos, e cremos no amor que Deus nos tem. Deus é amor; e quem permanece em amor, permanece em Deus, e Deus nele.","fr":"Pour nous, nous avons connu et cru l'amour que Dieu a pour nous: Dieu est charité; et celui qui demeure dans la charité, demeure en Dieu et Dieu en lui.","de":"Und wir haben erkannt und geglaubt die Liebe, die Gott zu uns hat. Gott ist die Liebe; und wer in der Liebe bleibt, der bleibt in Gott und Gott in ihm."},"reference":{"tr":"1. Yuhanna 4:16","en":"1 John 4:16","es":"1 Juan 4:16","pt":"1 João 4:16","fr":"1 Jean 4:16","de":"1. Johannes 4:16"}},{"theme":"gratitude","text":{"tr":"Her zaman, her şey için Efendimiz Yeşua Mesih’in adıyla Tanrı’ya, Baba’ya şükredin.","en":"giving thanks always concerning all things in the name of our Lord Jesus Christ, to God, even the Father;","es":"Dando gracias siempre de todo al Dios y Padre en el nombre de nuestro Señor Jesucristo:","pt":"sempre dando graças por tudo a Deus, o Pai, em nome de nosso Senhor Jesus Cristo,","fr":"Rendez grâces toujours pour toutes choses à Dieu le Père, au nom de notre Seigneur Jésus-Christ.","de":"und saget Dank allezeit für alles Gott und dem Vater in dem Namen unsers HERRN Jesu Christi,"},"reference":{"tr":"Efesliler 5:20","en":"Ephesians 5:20","es":"Efesios 5:20","pt":"Efésios 5:20","fr":"Éphésiens 5:20","de":"Epheser 5:20"}},{"theme":"comfort","text":{"tr":"Saygınlığımı artır, beni yeniden rahatlat.","en":"Increase my honor, and comfort me again.","es":"Aumentarás mi grandeza, y volverás á consolarme.","pt":"Aumentarás a minha grandeza, e de novo me consolarás.","fr":"Tu accroîtras ma grandeur, et tu me consoleras encore.","de":"Du machst mich sehr groß und tröstest mich wieder."},"reference":{"tr":"Mezmur 71:21","en":"Psalm 71:21","es":"Salmo 71:21","pt":"Salmo 71:21","fr":"Psaume 71:21","de":"Psalm 71:21"}},{"theme":"faith","text":{"tr":"O’nu görmemiş olduğunuz halde seviyorsunuz. Şu anda O’nu görmediğiniz halde iman ediyorsunuz. Sözle anlatılamaz yücelik dolu bir sevinçle coşuyorsunuz. İmanınızın sonucu olarak canlarınızın kurtuluşunu alıyorsunuz.","en":"whom not having known you love; in whom, though now you don’t see him, yet believing, you rejoice greatly with joy unspeakable and full of glory— receiving the result of your faith, the salvation of your souls.","es":"Al cual, no habiendo visto, le amáis; en el cual creyendo, aunque al presente no lo veáis, os alegráis con gozo inefable y glorificado; Obteniendo el fin de vuestra fe, que es la salud de vuestras almas.","pt":"a quem, sem o terdes visto, amais; no qual, sem agora o verdes, mas crendo, exultais com gozo inefável e cheio de glória, alcançando o fim da vossa fé, a salvação das vossas almas.","fr":"Que vous aimez, sans l'avoir connu, en qui vous croyez, sans le voir encore, et vous vous réjouissez d'une joie ineffable et glorieuse, Remportant le prix de votre foi, le salut de vos âmes.","de":"welchen ihr nicht gesehen und doch liebhabt und nun an ihn glaubet, wie wohl ihr ihn nicht sehet, und werdet euch freuen mit herrlicher und unaussprechlicher Freude und das Ende eures Glaubens davonbringen, nämlich der Seelen Seligkeit."},"reference":{"tr":"1. Petrus 1:8-9","en":"1 Peter 1:8-9","es":"1 Pedro 1:8-9","pt":"1 Pedro 1:8-9","fr":"1 Pierre 1:8-9","de":"1. Petrus 1:8-9"}},{"theme":"forgiveness","text":{"tr":"“Yargılamayın ki, siz de yargılanmayasınız. Suçlamayın ki, siz de suçlanmayasınız. Serbest bırakın ki, siz de serbest bırakılasınız.","en":"Don’t judge, and you won’t be judged. Don’t condemn, and you won’t be condemned. Set free, and you will be set free.","es":"No juzguéis, y no seréis juzgados: no condenéis, y no seréis condenados: perdonad, y seréis perdonados.","pt":"Não julgueis, e não sereis julgados; não condeneis, e não sereis condenados; perdoai, e sereis perdoados.","fr":"Ne jugez point, et vous ne serez point jugés; ne condamnez point, et vous ne serez point condamnés; pardonnez et on vous pardonnera;","de":"Richtet nicht, so werdet ihr auch nicht gerichtet. Verdammet nicht, so werdet ihr nicht verdammt. Vergebet, so wird euch vergeben."},"reference":{"tr":"Luka 6:37","en":"Luke 6:37","es":"San Lucas 6:37","pt":"Lucas 6:37","fr":"Luc 6:37","de":"Lukas 6:37"}},{"theme":"peace","text":{"tr":"Çünkü dağlar yerinden kalkabilir, tepeler taşınabilir, ama sevgi dolu iyiliğim senden ayrılmayacak, esenlik antlaşmam ortadan kalkmayacak” diyor sana merhamet eden Yahve.","en":"For the mountains may depart, and the hills be removed; but my loving kindness will not depart from you, and my covenant of peace will not be removed,” says Yahweh who has mercy on you.","es":"Porque los montes se moverán, y los collados temblarán; mas no se apartará de ti mi misericordia, ni el pacto de mi paz vacilará, dijo Jehová, el que tiene misericordia de ti.","pt":"Pois as montanhas se retirarão, e os outeiros serão removidos; porém a minha benignidade não se apartará de ti, nem será removido ao pacto da minha paz, diz o Senhor, que se compadece de ti.","fr":"Quand les montagnes s'éloigneraient, quand les collines s'ébranleraient, ma bonté ne s'éloignera pas de toi, et mon alliance de paix ne sera point ébranlée, dit l'Éternel, qui a compassion de toi.","de":"Denn es sollen wohl Berge weichen und Hügel hinfallen; aber meine Gnade soll nicht von dir weichen, und der Bund meines Friedens soll nicht hinfallen, spricht der HERR, dein Erbarmer."},"reference":{"tr":"Yeşaya 54:10","en":"Isaiah 54:10","es":"Isaías 54:10","pt":"Isaías 54:10","fr":"Ésaïe 54:10","de":"Jesaja 54:10"}},{"theme":"strength","text":{"tr":"Zayıflara güç verir. Gücü olmayanın gücünü artırır.","en":"He gives power to the weak. He increases the strength of him who has no might.","es":"El da esfuerzo al cansado, y multiplica las fuerzas al que no tiene ningunas.","pt":"Ele dá força ao cansado, e aumenta as forças ao que não tem nenhum vigor.","fr":"Il donne de la force à celui qui est lassé; il accroît la vigueur de celui qui est affaibli.","de":"Er gibt den Müden Kraft, und Stärke genug dem Unvermögenden."},"reference":{"tr":"Yeşaya 40:29","en":"Isaiah 40:29","es":"Isaías 40:29","pt":"Isaías 40:29","fr":"Ésaïe 40:29","de":"Jesaja 40:29"}},{"theme":"trust","text":{"tr":"İnsan korkusu tuzaktır, ama güvenini Yahve'ye bağlayan emniyette olur.","en":"The fear of man proves to be a snare, but whoever puts his trust in Yahweh is kept safe.","es":"El temor del hombre pondrá lazo: mas el que confía en Jehová será levantado.","pt":"O receio do homem lhe arma laços; mas o que confia no Senhor está seguro.","fr":"La crainte qu'on a de l'homme, fait tomber dans le piège; mais celui qui s'assure en l'Éternel aura une haute retraite.","de":"Vor Menschen sich scheuen bringt zu Fall; wer sich aber auf den HERRN verläßt, wird beschützt."},"reference":{"tr":"Süleyman’ın Özdeyişleri 29:25","en":"Proverbs 29:25","es":"Proverbios 29:25","pt":"Provérbios 29:25","fr":"Proverbes 29:25","de":"Sprüche 29:25"}},{"theme":"rest","text":{"tr":"İsrael'in Kutsalı Efendi Yahve şöyle diyor: “Dönmekle ve rahat etmekle kurtulacaksınız. Gücünüz sessizlikte ve güvende olacaktır.” Reddettiniz,","en":"For thus said the Lord Yahweh, the Holy One of Israel, “You will be saved in returning and rest. Your strength will be in quietness and in confidence.” You refused,","es":"Porque así dijo el Señor Jehová, el Santo de Israel: En descanso y en reposo seréis salvos; en quietud y en confianza será vuestra fortaleza. Y no quisisteis,","pt":"Pois assim diz o Senhor Deus, o Santo de Israel: Voltando e descansando, sereis salvos; no sossego e na confiança estará a vossa força. Mas não quisestes;","fr":"Car ainsi a dit le Seigneur, l'Éternel, le Saint d'Israël: C'est en retournant à moi et en demeurant tranquilles que vous serez sauvés; c'est dans le repos et la confiance que sera votre force. Mais vous ne l'avez pas voulu.","de":"Denn so spricht der Herr, HERR, der Heilige in Israel: Wenn ihr umkehrtet und stillebliebet, so würde euch geholfen; durch Stillesein und Hoffen würdet ihr stark sein. Aber ihr wollt nicht"},"reference":{"tr":"Yeşaya 30:15","en":"Isaiah 30:15","es":"Isaías 30:15","pt":"Isaías 30:15","fr":"Ésaïe 30:15","de":"Jesaja 30:15"}},{"theme":"hope","text":{"tr":"Gerçekten de geleceğe dair bir umut vardır, umudun da yok edilemez.","en":"Indeed surely there is a future hope, and your hope will not be cut off.","es":"Porque ciertamente hay fin, y tu esperanza no será cortada.","pt":"Porque deveras terás uma recompensa; não será malograda a tua esperança.","fr":"Car il y aura certainement une bonne issue, et ton attente ne sera point trompée.","de":"Denn es wird dir hernach gut sein, und dein Warten wird nicht trügen."},"reference":{"tr":"Süleyman’ın Özdeyişleri 23:18","en":"Proverbs 23:18","es":"Proverbios 23:18","pt":"Provérbios 23:18","fr":"Proverbes 23:18","de":"Sprüche 23:18"}},{"theme":"anxiety","text":{"tr":"“Hanginiz kaygılanmakla ömrüne bir an ekleyebilir?","en":"“Which of you, by being anxious, can add one moment to his lifespan?","es":"Mas ¿quién de vosotros podrá, congojándose, añadir á su estatura un codo?","pt":"Ora, qual de vós, por mais ansioso que esteja, pode acrescentar um côvado à sua estatura?","fr":"Et qui est-ce d'entre vous qui par son souci puisse ajouter une coudée à sa taille?","de":"Wer ist aber unter euch, der seiner Länge eine Elle zusetzen möge, ob er gleich darum sorget?"},"reference":{"tr":"Matta 6:27","en":"Matthew 6:27","es":"San Mateo 6:27","pt":"Mateus 6:27","fr":"Matthieu 6:27","de":"Matthäus 6:27"}},{"theme":"guidance","text":{"tr":"İnsanın adımları Yahve tarafından pekiştirilir. Onun yolundan hoşnuttur.","en":"A man’s goings are established by Yahweh. He delights in his way.","es":"Por Jehová son ordenados los pasos del hombre, y aprueba su camino.","pt":"Confirmados pelo Senhor são os passos do homem em cujo caminho ele se deleita;","fr":"Les pas de l'homme de bien sont affermis par l'Éternel, et il prend plaisir à sa voie.","de":"Von dem HERRN wird solches Mannes Gang gefördert, und er hat Lust an seinem Wege."},"reference":{"tr":"Mezmur 37:23","en":"Psalm 37:23","es":"Salmo 37:23","pt":"Salmo 37:23","fr":"Psaume 37:23","de":"Psalm 37:23"}},{"theme":"joy","text":{"tr":"Ben yine Yahve'de sevineceğim. Kurtuluşumun Tanrısı'nda coşacağım!","en":"yet I will rejoice in Yahweh. I will be joyful in the God of my salvation!","es":"Con todo, yo me alegraré en Jehová, y me gozaré en el Dios de mi salud.","pt":"todavia eu me alegrarei no Senhor, exultarei no Deus da minha salvação.","fr":"Mais moi je me réjouirai en l'Éternel, je tressaillirai de joie dans le Dieu de ma délivrance.","de":"Aber ich will mich freuen des HERRN und fröhlich sein in Gott, meinem Heil."},"reference":{"tr":"Habakkuk 3:18","en":"Habakkuk 3:18","es":"Habacuc 3:18","pt":"Habacuque 3:18","fr":"Habacuc 3:18","de":"Habakuk 3:18"}},{"theme":"love","text":{"tr":"Ama sen, ey Efendim merhametli ve lütufkâr bir Tanrı’sın. Yavaş öfkelenirsin, sevgi dolu iyiliğin ve gerçeğin boldur.","en":"But you, Lord, are a merciful and gracious God, slow to anger, and abundant in loving kindness and truth.","es":"Mas tú, Señor, Dios misericordioso y clemente, lento para la ira, y grande en misericordia y verdad;","pt":"Mas tu, Senhor, és um Deus compassivo e benigno, longânimo, e abundante em graça e em fidelidade.","fr":"Mais toi, Seigneur, tu es un Dieu pitoyable et miséricordieux, lent à la colère, abondant en bonté et en fidélité.","de":"Du aber, HERR, Gott, bist barmherzig und gnädig, geduldig und von großer Güte und Treue."},"reference":{"tr":"Mezmur 86:15","en":"Psalm 86:15","es":"Salmo 86:15","pt":"Salmo 86:15","fr":"Psaume 86:15","de":"Psalm 86:15"}},{"theme":"gratitude","text":{"tr":"Şükranla huzuruna çıkalım. O’nu ezgilerle yüceltelim!","en":"Let’s come before his presence with thanksgiving. Let’s extol him with songs!","es":"Lleguemos ante su acatamiento con alabanza; aclamémosle con cánticos.","pt":"Apresentemo-nos diante dele com ações de graças, e celebremo-lo com salmos de louvor.","fr":"Présentons-nous à lui avec des louanges; offrons-lui nos joyeux cantiques.","de":"Lasset uns mit Danken vor sein Angesicht kommen und mit Psalmen ihm jauchzen!"},"reference":{"tr":"Mezmur 95:2","en":"Psalm 95:2","es":"Salmo 95:2","pt":"Salmo 95:2","fr":"Psaume 95:2","de":"Psalm 95:2"}},{"theme":"comfort","text":{"tr":"“Benim, seni avutan benim. Sen kimsin ki ölecek insandan, ot gibi olacak insanoğlundan korkuyorsun?","en":"“I, even I, am he who comforts you. Who are you, that you are afraid of man who shall die, and of the son of man who will be made as grass?","es":"Yo, yo soy vuestro consolador. ¿Quién eres tú para que tengas temor del hombre, que es mortal, del hijo del hombre, que por heno será contado?","pt":"Eu, eu sou aquele que vos consola; quem, pois, és tu, para teres medo dum homem, que é mortal, ou do filho do homem que se tornará como feno;","fr":"C'est moi, c'est moi qui vous console. Qui es-tu, pour avoir peur de l'homme mortel, du fils de l'homme qui deviendra comme l'herbe;","de":"Ich, ich bin euer Tröster. Wer bist du denn, daß du dich vor Menschen fürchtest, die doch sterben, und vor Menschenkindern, die wie Gras vergehen,"},"reference":{"tr":"Yeşaya 51:12","en":"Isaiah 51:12","es":"Isaías 51:12","pt":"Isaías 51:12","fr":"Ésaïe 51:12","de":"Jesaja 51:12"}},{"theme":"faith","text":{"tr":"Yeşua ona, “Beni gördüğün için mi iman ettin?” dedi. “Görmeden iman edenlere ne mutlu.”","en":"Jesus said to him, “Because you have seen me, you have believed. Blessed are those who have not seen, and have believed.”","es":"Dícele Jesús: Porque me has visto, Tomás, creiste: bienaventurados los que no vieron y creyeron.","pt":"Disse-lhe Jesus: Porque me viste, creste? Bem-aventurados os que não viram e creram.","fr":"Jésus lui dit: Parce que tu m'as vu, Thomas, tu as cru. Heureux ceux qui n'ont pas vu, et qui ont cru!","de":"Spricht Jesus zu ihm: Dieweil du mich gesehen hast, Thomas, glaubest du. Selig sind, die nicht sehen und doch glauben!"},"reference":{"tr":"Yuhanna 20:29","en":"John 20:29","es":"Juan 20:29","pt":"João 20:29","fr":"Jean 20:29","de":"Johannes 20:29"}},{"theme":"forgiveness","text":{"tr":"“Bu nedenle tövbe edin ve Tanrı’ya dönün ki, günahlarınız silinsin. Böylece Efendi‘nin önünden yenilenme zamanları gelebilsin.","en":"“Repent therefore, and turn again, that your sins may be blotted out, so that there may come times of refreshing from the presence of the Lord,","es":"Así que, arrepentíos y convertíos, para que sean borrados vuestros pecados; pues que vendrán los tiempos del refrigerio de la presencia del Señor,","pt":"Arrependei-vos, pois, e convertei-vos, para que sejam apagados os vossos pecados, de sorte que venham os tempos de refrigério, da presença do Senhor,","fr":"Repentez-vous donc et vous convertissez, afin que vos péchés soient effacés,","de":"So tut nun Buße und bekehrt euch, daß eure Sünden vertilgt werden;"},"reference":{"tr":"Elçilerin İşleri 3:19","en":"Acts 3:19","es":"Hechos 3:19","pt":"Atos 3:19","fr":"Actes 3:19","de":"Apostelgeschichte 3:19"}},{"theme":"peace","text":{"tr":"Bu şeyleri size, bende esenliğiniz olsun diye söyledim. Dünyada sıkıntınız olacak. Ama cesur olun, ben dünyaya galip geldim!”","en":"I have told you these things, that in me you may have peace. In the world you have oppression; but cheer up! I have overcome the world.”","es":"Estas cosas os he hablado, para que en mí tengáis paz. En el mundo tendréis aflicción: mas confiad, yo he vencido al mundo.","pt":"Tenho-vos dito estas coisas, para que em mim tenhais paz. No mundo tereis tribulações; mas tende bom ânimo, eu venci o mundo.","fr":"Je vous ai dit ces choses, afin que vous ayez la paix en moi; vous aurez des afflictions dans le monde; mais prenez courage, j'ai vaincu le monde.","de":"Solches habe ich mit euch geredet, daß ihr in mir Frieden habet. In der Welt habt ihr Angst; aber seid getrost, ich habe die Welt überwunden."},"reference":{"tr":"Yuhanna 16:33","en":"John 16:33","es":"Juan 16:33","pt":"João 16:33","fr":"Jean 16:33","de":"Johannes 16:33"}},{"theme":"strength","text":{"tr":"Yahve, Efendi benim gücümdür. O benim ayaklarımı geyik ayakları gibi yapar, yüksek yerlere çıkmamı sağlar. Telli çalgılarımda, müzik şefi için.","en":"Yahweh, the Lord, is my strength. He makes my feet like deer’s feet, and enables me to go in high places. For the music director, on my stringed instruments.","es":"Jehová el Señor es mi fortaleza, el cual pondrá mis pies como de ciervas, y me hará andar sobre mis alturas. Al jefe de los cantores sobre mis instrumentos de cuerdas.","pt":"O Senhor Deus é minha força, ele fará os meus pés como os da corça, e me fará andar sobre os meus lugares altos. (Ao regente de música. Para instrumentos de cordas.)","fr":"L'Éternel, le Seigneur, est ma force; il rend mes pieds semblables à ceux des biches, et me fait tenir sur mes hauteurs. Au maître-chantre, avec instruments à cordes.","de":"Denn der HERR ist meine Kraft und wird meine Füße machen wie Hirschfüße und wird mich auf meine Höhen führen. Vorzusingen auf meinem Saitenspiel."},"reference":{"tr":"Habakkuk 3:19","en":"Habakkuk 3:19","es":"Habacuc 3:19","pt":"Habacuque 3:19","fr":"Habacuc 3:19","de":"Habakuk 3:19"}},{"theme":"trust","text":{"tr":"Bazıları savaş arabalarına, bazıları atlara güvenir, ama biz Tanrımız Yahve’nin adına güveniriz.","en":"Some trust in chariots, and some in horses, but we trust the name of Yahweh our God.","es":"Estos confían en carros, y aquéllos en caballos: mas nosotros del nombre de Jehová nuestro Dios tendremos memoria.","pt":"Uns confiam em carros e outros em cavalos, mas nós faremos menção do nome do Senhor nosso Deus.","fr":"Déjà je sais que l'Éternel a délivré son Oint; il lui répondra des cieux de sa sainteté, par le secours puissant de sa droite.","de":"Nun merke ich, daß der HERR seinem Gesalbten hilft und erhöht ihn in seinen heiligen Himmel; seine rechte Hand hilft mit Macht."},"reference":{"tr":"Mezmur 20:7","en":"Psalm 20:7","es":"Salmo 20:7","pt":"Salmo 20:7","fr":"Psaume 20:7","de":"Psalm 20:7"}},{"theme":"rest","text":{"tr":"Yüceler Yücesi'nin gizli yerinde oturan Her Şeye Gücü Yeten’in gölgesinde dinlenir.","en":"He who dwells in the secret place of the Most High will rest in the shadow of the Almighty.","es":"EL que habita al abrigo del Altísimo, morará bajo la sombra del Omnipotente.","pt":"Aquele que habita no esconderijo do Altíssimo, à sombra do Todo-Poderoso descansará.","fr":"Celui qui habite dans la retraite secrète du Très-Haut repose à l'ombre du Tout-Puissant.","de":"Wer unter dem Schirm des Höchsten sitzt und unter dem Schatten des Allmächtigen bleibt,"},"reference":{"tr":"Mezmur 91:1","en":"Psalm 91:1","es":"Salmo 91:1","pt":"Salmo 91:1","fr":"Psaume 91:1","de":"Psalm 91:1"}},{"theme":"hope","text":{"tr":"Umutta sevinin. Sıkıntıya katlanın. Dualarınızı kararlılıkla sürdürün.","en":"rejoicing in hope; enduring in troubles; continuing steadfastly in prayer;","es":"Gozosos en la esperanza; sufridos en la tribulación; constantes en la oración;","pt":"alegrai-vos na esperança, sede pacientes na tribulação, perseverai na oração;","fr":"Soyez joyeux dans l'espérance, patients dans l'affliction, persévérants dans la prière.","de":"Seid fröhlich in Hoffnung, geduldig in Trübsal, haltet an am Gebet."},"reference":{"tr":"Romalılar 12:12","en":"Romans 12:12","es":"Romanos 12:12","pt":"Romanos 12:12","fr":"Romains 12:12","de":"Römer 12:12"}},{"theme":"anxiety","text":{"tr":"Müzik şefi için - Alamot - Korahoğulları ezgisi Tanrı sığınağımız ve gücümüzdür, sıkıntıda hemen yardıma hazırdır. Bu nedenle, dünya altüst olsa, dağlar denizlerin bağrına yıkılsa,","en":"God is our refuge and strength, a very present help in trouble. Therefore we won’t be afraid, though the earth changes, though the mountains are shaken into the heart of the seas;","es":"Al Músico principal: de los hijos de Coré: Salmo sobre Alamoth. DIOS es nuestro amparo y fortaleza, nuestro pronto auxilio en las tribulaciones. Por tanto no temeremos aunque la tierra sea removida; aunque se traspasen los montes al corazón de la mar.","pt":"Deus é o nosso refúgio e fortaleza, socorro bem presente na angústia. Pelo que não temeremos, ainda que a terra se mude, e ainda que os montes se projetem para o meio dos mares;","fr":"Au maître-chantre. Cantique des enfants de Coré, sur Alamoth (jeunes filles). Dieu est notre retraite, notre force, notre secours dans les détresses, et fort aisé à trouver.","de":"Ein Lied der Kinder Korah, von der Jugend, vorzusingen. Gott ist unsre Zuversicht und Stärke. Eine Hilfe in den großen Nöten, die uns getroffen haben."},"reference":{"tr":"Mezmur 46:1-2","en":"Psalm 46:1-2","es":"Salmo 46:1-2","pt":"Salmo 46:1-2","fr":"Psaume 46:1-2","de":"Psalm 46:1-2"}},{"theme":"guidance","text":{"tr":"Ancak O, Gerçeğin Ruhu gelince, sizi tüm gerçeğe yöneltecek. Çünkü kendiliğinden konuşmayacak, ama her ne duyarsa söyleyecek. Size gelecekte olacakları bildirecek.","en":"However when he, the Spirit of truth, has come, he will guide you into all truth, for he will not speak from himself; but whatever he hears, he will speak. He will declare to you things that are coming.","es":"Pero cuando viniere aquel Espíritu de verdad, él os guiará á toda verdad; porque no hablará de sí mismo, sino que hablará todo lo que oyere, y os hará saber las cosas que han de venir.","pt":"Quando vier, porém, aquele, o Espírito da verdade, ele vos guiará a toda a verdade; porque não falará por si mesmo, mas dirá o que tiver ouvido, e vos anunciará as coisas vindouras.","fr":"Mais quand celui-là, l'Esprit de vérité, sera venu, il vous conduira dans toute la vérité, car il ne parlera point par lui-même, mais il dira tout ce qu'il aura entendu, et vous annoncera les choses à venir.","de":"Wenn aber jener, der Geist der Wahrheit, kommen wird, der wird euch in alle Wahrheit leiten. Denn er wird nicht von sich selber reden; sondern was er hören wird, das wird er reden, und was zukünftig ist, wird er euch verkünden."},"reference":{"tr":"Yuhanna 16:13","en":"John 16:13","es":"Juan 16:13","pt":"João 16:13","fr":"Jean 16:13","de":"Johannes 16:13"}},{"theme":"joy","text":{"tr":"Yüreğime verdiğin sevinç, onların tahıllarının ve yeni şaraplarının çoğaldığı zamankinden fazladır.","en":"You have put gladness in my heart, more than when their grain and their new wine are increased.","es":"Tú diste alegría en mi corazón, más que tienen ellos en el tiempo que se multiplicó su grano y su mosto.","pt":"Puseste no meu coração mais alegria do que a deles no tempo em que se lhes multiplicam o trigo e o vinho.","fr":"Plusieurs disent: Qui nous fera voir du bien? Fais lever sur nous la lumière de ta face, ô Éternel!","de":"Viele sagen: \"Wer wird uns Gutes sehen lassen?\" Aber, HERR, erhebe über uns das Licht deines Antlitzes!"},"reference":{"tr":"Mezmur 4:7","en":"Psalm 4:7","es":"Salmo 4:7","pt":"Salmo 4:7","fr":"Psaume 4:7","de":"Psalm 4:7"}},{"theme":"love","text":{"tr":"Yahve eskiden bana görünüp dedi, “Evet, seni sonsuz bir sevgiyle sevdim, bu yüzden seni sevgi dolu iyiliğimle kendime çektim.","en":"Yahweh appeared of old to me, saying, “Yes, I have loved you with an everlasting love. Therefore I have drawn you with loving kindness.","es":"Jehová se manifestó á mí ya mucho tiempo há, diciendo: Con amor eterno te he amado; por tanto te soporté con misericordia.","pt":"De longe o Senhor me apareceu, dizendo: Pois que com amor eterno te amei, também com benignidade te atraí.","fr":"De loin l'Éternel m'est apparu, et m'a dit: Je t'ai aimée d'un amour éternel, c'est pourquoi j'ai prolongé envers toi ma bonté.","de":"Der HERR ist mir erschienen von ferne: Ich habe dich je und je geliebt; darum habe ich dich zu mir gezogen aus lauter Güte."},"reference":{"tr":"Yeremya 31:3","en":"Jeremiah 31:3","es":"Jeremías 31:3","pt":"Jeremias 31:3","fr":"Jérémie 31:3","de":"Jeremia 31:3"}},{"theme":"gratitude","text":{"tr":"Her iyi armağan ve her mükemmel armağan yücelerden, kendisinde değişkenlik ya da döneklik gölgesi olmayan Işıklar Babası’ndan gelir.","en":"Every good gift and every perfect gift is from above, coming down from the Father of lights, with whom can be no variation, nor turning shadow.","es":"Toda buena dádiva y todo don perfecto es de lo alto, que desciende del Padre de las luces, en el cual no hay mudanza, ni sombra de variación.","pt":"Toda boa dádiva e todo dom perfeito vêm do alto, descendo do Pai das luzes, em quem não há mudança nem sombra de variação.","fr":"Toute grâce excellente et tout don parfait viennent d'en haut, et descendent du Père des lumières, en qui il n'y a ni variation, ni ombre de changement.","de":"Alle gute Gabe und alle vollkommene Gabe kommt von obenherab, von dem Vater des Lichts, bei welchem ist keine Veränderung noch Wechsel des Lichtes und der Finsternis."},"reference":{"tr":"Yakup 1:17","en":"James 1:17","es":"Santiago 1:17","pt":"Tiago 1:17","fr":"Jacques 1:17","de":"Jakobus 1:17"}},{"theme":"comfort","text":{"tr":"Yahve'nin lütuf yılını, Tanrımız'ın öç gününü ilan etmek, yas tutanların tümünü avutmak için, Siyon'da yas tutanlara sağlamak üzere, küller yerine çelenk, yas yerine sevinç yağı, ağırlık ruhu yerine övgü giysisi vermek için beni gönderdi. Öyle ki, onlara doğruluk ağaçları, Yahve'nin kendisinin yücelmesi için diktiği denilsin.","en":"to proclaim the year of Yahweh’s favor, and the day of vengeance of our God; to comfort all who mourn; to provide for those who mourn in Zion, to give to them a garland for ashes, the oil of joy for mourning, the garment of praise for the spirit of heaviness; that they may be called trees of righteousness, the planting of Yahweh, that he may be glorified.","es":"A promulgar año de la buena voluntad de Jehová, y día de venganza del Dios nuestro; á consolar á todos los enlutados; A ordenar á Sión á los enlutados, para darles gloria en lugar de ceniza, óleo de gozo en lugar del luto, manto de alegría en lugar del espíritu angustiado; y serán llamados árboles de justicia, plantío de Jehová, para gloria suya.","pt":"a apregoar o ano aceitável do Senhor e o dia da vingança do nosso Deus; a consolar todos os tristes; a ordenar acerca dos que choram em Sião que se lhes dê uma grinalda em vez de cinzas, óleo de gozo em vez de pranto, vestidos de louvor em vez de espírito angustiado; a fim de que se chamem árvores de justiça, plantação do Senhor, para que ele seja glorificado.","fr":"Pour proclamer l'année de la bienveillance de l'Éternel et le jour de la vengeance de notre Dieu; pour consoler tous ceux qui sont dans le deuil; Pour présenter à ceux de Sion qui sont dans le deuil et pour leur donner le diadème au lieu de la cendre, l'huile de joie au lieu du deuil, le manteau de louange au lieu d'un esprit abattu; tellement qu'on les appellera les chênes de la justice, les arbres plantés par l'Éternel pour le glorifier.","de":"zu verkündigen ein gnädiges Jahr des HERRN und einen Tag der Rache unsers Gottes, zu trösten alle Traurigen, zu schaffen den Traurigen zu Zion, daß ihnen Schmuck für Asche und Freudenöl für Traurigkeit und schöne Kleider für einen betrübten Geist gegeben werden, daß sie genannt werden die Bäume der Gerechtigkeit, Pflanzen des HERRN zum Preise."},"reference":{"tr":"Yeşaya 61:2-3","en":"Isaiah 61:2-3","es":"Isaías 61:2-3","pt":"Isaías 61:2-3","fr":"Ésaïe 61:2-3","de":"Jesaja 61:2-3"}},{"theme":"faith","text":{"tr":"Duada inanarak her ne dilerseniz, alacaksınız.”","en":"All things, whatever you ask in prayer, believing, you will receive.”","es":"Y todo lo que pidiereis en oración, creyendo, lo recibiréis.","pt":"e tudo o que pedirdes na oração, crendo, recebereis.","fr":"Et tout ce que vous demanderez en priant, si vous croyez, vous le recevrez.","de":"Und alles, was ihr bittet im Gebet, so ihr glaubet, werdet ihr's empfangen."},"reference":{"tr":"Matta 21:22","en":"Matthew 21:22","es":"San Mateo 21:22","pt":"Mateus 21:22","fr":"Matthieu 21:22","de":"Matthäus 21:22"}},{"theme":"forgiveness","text":{"tr":"Ben kendi uğruma suçlarınızı silen benim; senin günahlarını da hatırlamayacağım.","en":"I, even I, am he who blots out your transgressions for my own sake; and I will not remember your sins.","es":"Yo, yo soy el que borro tus rebeliones por amor de mí; y no me acordaré de tus pecados.","pt":"Eu, eu mesmo, sou o que apago as tuas transgressões por amor de mim, e dos teus pecados não me lembro.","fr":"C'est moi, c'est moi qui efface tes forfaits pour l'amour de moi, et je ne me souviendrai plus de tes péchés.","de":"Ich, ich tilge deine Übertretungen um meinetwillen und gedenke deiner Sünden nicht."},"reference":{"tr":"Yeşaya 43:25","en":"Isaiah 43:25","es":"Isaías 43:25","pt":"Isaías 43:25","fr":"Ésaïe 43:25","de":"Jesaja 43:25"}},{"theme":"peace","text":{"tr":"Esenlik kaynağı olan Efendi’nin kendisi size her zaman, her yönden esenlik versin. Efendi hepinizle birlikte olsun.","en":"Now may the Lord of peace himself give you peace at all times in all ways. The Lord be with you all.","es":"Y el mismo Señor de paz os dé siempre paz en toda manera. El Señor sea con todos vosotros.","pt":"Ora, o próprio Senhor da paz vos dê paz sempre e de toda maneira. O Senhor seja com todos vós.","fr":"Que le Seigneur de paix vous donne lui-même la paix en tout temps et en toutes manières! Le Seigneur soit avec vous tous!","de":"Er aber, der HERR des Friedens, gebe euch Frieden allenthalben und auf allerlei Weise. Der HERR sei mit euch allen!"},"reference":{"tr":"2. Selanikliler 3:16","en":"2 Thessalonians 3:16","es":"2 Tesalonicenses 3:16","pt":"2 Tessalonicenses 3:16","fr":"2 Thessaloniciens 3:16","de":"2. Thessalonicher 3:16"}},{"theme":"strength","text":{"tr":"Bedenim ve yüreğim tükeniyor, ama Tanrı yüreğimin gücü, sonsuza dek bana düşen paydır.","en":"My flesh and my heart fails, but God is the strength of my heart and my portion forever.","es":"Mi carne y mi corazón desfallecen: mas la roca de mi corazón y mi porción es Dios para siempre.","pt":"A minha carne e o meu coração desfalecem; do meu coração, porém, Deus é a fortaleza, e o meu quinhão para sempre.","fr":"Ma chair et mon cœur défaillaient; mais Dieu est le rocher de mon cœur et mon partage à toujours.","de":"Wenn mir gleich Leib und Seele verschmachtet, so bist du doch, Gott, allezeit meines Herzens Trost und mein Teil."},"reference":{"tr":"Mezmur 73:26","en":"Psalm 73:26","es":"Salmo 73:26","pt":"Salmo 73:26","fr":"Psaume 73:26","de":"Psalm 73:26"}},{"theme":"trust","text":{"tr":"Kötü haberden korkmaz. Yüreği kararlıdır, Yahve’ye güvenir.","en":"He will not be afraid of evil news. His heart is steadfast, trusting in Yahweh.","es":"De mala fama no tendrá temor: su corazón está apercibido, confiado en Jehová.","pt":"Ele não teme más notícias; o seu coração está firme, confiando no Senhor.","fr":"Il n'a pas à craindre les mauvaises nouvelles; son cœur est ferme, s'assurant en l'Éternel.","de":"Wenn eine Plage kommen will, so fürchtet er sich nicht; sein Herz hofft unverzagt auf den HERRN."},"reference":{"tr":"Mezmur 112:7","en":"Psalm 112:7","es":"Salmo 112:7","pt":"Salmo 112:7","fr":"Psaume 112:7","de":"Psalm 112:7"}},{"theme":"rest","text":{"tr":"Boyunduruğumu takının ve benden öğrenin. Çünkü ben yumuşak huylu ve alçakgönüllüyüm. Ve böylece canlarınız rahat bulur. Çünkü boyunduruğum kolay, yüküm hafiftir.”","en":"Take my yoke upon you, and learn from me, for I am gentle and humble in heart; and you will find rest for your souls. For my yoke is easy, and my burden is light.”","es":"Llevad mi yugo sobre vosotros, y aprended de mí, que soy manso y humilde de corazón; y hallaréis descanso para vuestras almas. Porque mi yugo es fácil, y ligera mi carga.","pt":"Tomai sobre vós o meu jugo, e aprendei de mim, que sou manso e humilde de coração; e achareis descanso para as vossas almas. Porque o meu jugo é suave, e o meu fardo e leve.","fr":"Chargez-vous de mon joug, et apprenez de moi, parce que je suis doux et humble de cour, et vous trouverez le repos de vos âmes; car mon joug est aisé, et mon fardeau léger.","de":"Nehmet auf euch mein Joch und lernet von mir; denn ich bin sanftmütig und von Herzen demütig; so werdet ihr Ruhe finden für eure Seelen. Denn mein Joch ist sanft, und meine Last ist leicht."},"reference":{"tr":"Matta 11:29-30","en":"Matthew 11:29-30","es":"San Mateo 11:29-30","pt":"Mateus 11:29-30","fr":"Matthieu 11:29-30","de":"Matthäus 11:29-30"}},{"theme":"hope","text":{"tr":"İşte, Yahve’nin gözü kendisinden korkanların, O’nun sevgi dolu iyiliğine umut bağlayanların üzerindedir.","en":"Behold, Yahweh’s eye is on those who fear him, on those who hope in his loving kindness;","es":"He aquí, el ojo de Jehová sobre los que le temen, sobre los que esperan en su misericordia;","pt":"Eis que os olhos do Senhor estão sobre os que o temem, sobre os que esperam na sua benignidade,","fr":"Voici, l'œil de l'Éternel est sur ceux qui le craignent, sur ceux qui s'attendent à sa bonté,","de":"Siehe, des HERRN Auge sieht auf die, so ihn fürchten, die auf seine Güte hoffen,"},"reference":{"tr":"Mezmur 33:18","en":"Psalm 33:18","es":"Salmo 33:18","pt":"Salmo 33:18","fr":"Psaume 33:18","de":"Psalm 33:18"}},{"theme":"anxiety","text":{"tr":"Hanginiz kaygılanmakla boyuna bir arşın ekleyebilir? O zaman bu en ufak şeyi bile yapamıyorsanız, neden geri kalanlar için kaygılanıyorsunuz?","en":"Which of you by being anxious can add a cubit to his height? If then you aren’t able to do even the least things, why are you anxious about the rest?","es":"¿Y quién de vosotros podrá con afán añadir á su estatura un codo? Pues si no podéis aun lo que es menos, ¿para qué estaréis afanosos de lo demás?","pt":"Ora, qual de vós, por mais ansioso que esteja, pode acrescentar um côvado à sua estatura? Porquanto, se não podeis fazer nem as coisas mínimas, por que estais ansiosos pelas outras?","fr":"Et qui de vous peut, par ses inquiétudes, ajouter une coudée à sa taille? Si donc vous ne pouvez pas même les plus petites choses, pourquoi vous inquiétez-vous du reste?","de":"Welcher ist unter euch, ob er schon darum sorget, der da könnte eine Elle seiner Länge zusetzen? So ihr denn das Geringste nicht vermöget, warum sorgt ihr für das andere?"},"reference":{"tr":"Luka 12:25-26","en":"Luke 12:25-26","es":"San Lucas 12:25-26","pt":"Lucas 12:25-26","fr":"Luc 12:25-26","de":"Lukas 12:25-26"}},{"theme":"guidance","text":{"tr":"Öğüdünle bana yol gösterirsin, sonunda beni yüceliğe alırsın.","en":"You will guide me with your counsel, and afterward receive me to glory.","es":"Hasme guiado según tu consejo, y después me recibirás en gloria.","pt":"Tu me guias com o teu conselho, e depois me receberás em glória.","fr":"Tu me conduiras par ton conseil, puis tu me recevras dans la gloire.","de":"du leitest mich nach deinem Rat und nimmst mich endlich in Ehren an."},"reference":{"tr":"Mezmur 73:24","en":"Psalm 73:24","es":"Salmo 73:24","pt":"Salmo 73:24","fr":"Psaume 73:24","de":"Psalm 73:24"}},{"theme":"joy","text":{"tr":"Her zaman sevinin.","en":"Rejoice always.","es":"Estad siempre gozosos.","pt":"Regozijai-vos sempre.","fr":"Soyez toujours joyeux.","de":"Seid allezeit fröhlich,"},"reference":{"tr":"1. Selanikliler 5:16","en":"1 Thessalonians 5:16","es":"1 Tesalonicenses 5:16","pt":"1 Tessalonicenses 5:16","fr":"1 Thessaloniciens 5:16","de":"1. Thessalonicher 5:16"}},{"theme":"love","text":{"tr":"Her şeyden önce birbirinizi içten sevin. Çünkü sevgi birçok günahı örter.","en":"And above all things be earnest in your love among yourselves, for love covers a multitude of sins.","es":"Y sobre todo, tened entre vosotros ferviente caridad; porque la caridad cubrirá multitud de pecados.","pt":"tendo antes de tudo ardente amor uns para com os outros, porque o amor cobre uma multidão de pecados;","fr":"Surtout ayez les uns pour les autres une ardente charité; car la charité couvrira une multitude de péchés.","de":"So seid nun mäßig und nüchtern zum Gebet. Vor allen Dingen aber habt untereinander eine inbrünstige Liebe; denn die Liebe deckt auch der Sünden Menge."},"reference":{"tr":"1. Petrus 4:8","en":"1 Peter 4:8","es":"1 Pedro 4:8","pt":"1 Pedro 4:8","fr":"1 Pierre 4:8","de":"1. Petrus 4:8"}},{"theme":"gratitude","text":{"tr":"Şimdi dille anlatılamaz armağanı için Tanrı’ya şükürler olsun!","en":"Now thanks be to God for his unspeakable gift!","es":"Gracias á Dios por su don inefable.","pt":"Graças a Deus pelo seu dom inefável.","fr":"Or, grâces soient rendues à Dieu de son don ineffable!","de":"Gott aber sei Dank für seine unaussprechliche Gabe!"},"reference":{"tr":"2. Korintliler 9:15","en":"2 Corinthians 9:15","es":"2 Corintios 9:15","pt":"2 Coríntios 9:15","fr":"2 Corinthiens 9:15","de":"2. Korinther 9:15"}},{"theme":"comfort","text":{"tr":"Çünkü canımı ölümden, gözlerimi gözyaşından, ayaklarımı düşmekten kurtardın.","en":"For you have delivered my soul from death, my eyes from tears, and my feet from falling.","es":"Pues tú has librado mi alma de la muerte, mis ojos de lágrimas, y mis pies de desbarrar.","pt":"Pois livraste a minha alma da morte, os meus olhos das lágrimas, e os meus pés de tropeçar.","fr":"Car tu as délivré mon âme de la mort, mes yeux de pleurs, et mes pieds de chute.","de":"Denn du hast meine Seele aus dem Tode gerissen, meine Augen von den Tränen, meinen Fuß vom Gleiten."},"reference":{"tr":"Mezmur 116:8","en":"Psalm 116:8","es":"Salmo 116:8","pt":"Salmo 116:8","fr":"Psaume 116:8","de":"Psalm 116:8"}},{"theme":"faith","text":{"tr":"Bunun gibi, tek başına işleri olmayan iman da ölüdür.","en":"Even so faith, if it has no works, is dead in itself.","es":"Así también la fe, si no tuviere obras, es muerta en sí misma.","pt":"Assim também a fé, se não tiver obras, é morta em si mesma.","fr":"Il en est de même de la foi, si elle n'a pas les œuvres, elle est morte en elle-même.","de":"Also auch der Glaube, wenn er nicht Werke hat, ist er tot an ihm selber."},"reference":{"tr":"Yakup 2:17","en":"James 2:17","es":"Santiago 2:17","pt":"Tiago 2:17","fr":"Jacques 2:17","de":"Jakobus 2:17"}},{"theme":"forgiveness","text":{"tr":"Sonra Petrus Yeşua’ya gelip, “Efendimiz, kardeşim bana karşı kaç kez günah işlerse onu bağışlayayım? Yedi kereye kadar mı?” dedi. Yeşua ona, “Sana yedi kereye kadar değil, ben sana yetmiş kere yedi kez derim.","en":"Then Peter came and said to him, “Lord, how often shall my brother sin against me, and I forgive him? Until seven times?” Jesus said to him, “I don’t tell you until seven times, but, until seventy times seven.","es":"Entonces Pedro, llegándose á él, dijo: Señor, ¿cuántas veces perdonaré á mi hermano que pecare contra mí? ¿hasta siete? Jesús le dice: No te digo hasta siete, mas aun hasta setenta veces siete.","pt":"Então Pedro, aproximando-se dele, lhe perguntou: Senhor, até quantas vezes pecará meu irmão contra mim, e eu hei de perdoar? Até sete? Respondeu-lhe Jesus: Não te digo que até sete; mas até setenta vezes sete.","fr":"Alors Pierre, s'étant approché, lui dit: Seigneur, combien de fois pardonnerai-je à mon frère, lorsqu'il péchera contre moi? Sera-ce jusqu'à sept fois? Jésus lui répondit: Je ne te dis pas jusqu'à sept fois, mais jusqu'à septante fois sept fois.","de":"Da trat Petrus zu ihm und sprach: HERR, wie oft muß ich denn meinem Bruder, der an mir sündigt, vergeben? Ist's genug siebenmal? Jesus sprach zu ihm: Ich sage dir: Nicht siebenmal, sondern siebzigmal siebenmal."},"reference":{"tr":"Matta 18:21-22","en":"Matthew 18:21-22","es":"San Mateo 18:21-22","pt":"Mateus 18:21-22","fr":"Matthieu 18:21-22","de":"Matthäus 18:21-22"}},{"theme":"peace","text":{"tr":"Yahve Tanrı’nın ne söyleyeceğini dinleyeceğim. Çünkü halkına, kutsallarına esenlik konuşacak, ama onlar bir daha akılsızlığa dönmesinler.","en":"I will hear what God, Yahweh, will speak, for he will speak peace to his people, his saints; but let them not turn again to folly.","es":"Escucharé lo que hablará el Dios Jehová: porque hablará paz á su pueblo y á sus santos, para que no se conviertan á la locura.","pt":"Escutarei o que Deus, o Senhor, disser; porque falará de paz ao seu povo, e aos seus santos, contanto que não voltem à insensatez.","fr":"Fais-nous voir ta bonté, ô Éternel, et accorde-nous ta délivrance!","de":"HERR, erzeige uns deine Gnade und hilf uns!"},"reference":{"tr":"Mezmur 85:8","en":"Psalm 85:8","es":"Salmo 85:8","pt":"Salmo 85:8","fr":"Psaume 85:8","de":"Psalm 85:8"}},{"theme":"strength","text":{"tr":"Yahve'yi ve O'nun gücünü arayın. Daima O'nun yüzünü arayın.","en":"Seek Yahweh and his strength. Seek his face forever more.","es":"Buscad á Jehová y su fortaleza; buscad su rostro continuamente.","pt":"Buscai ao Senhor e a sua força; buscai a sua face continuamente.","fr":"Recherchez l'Éternel et sa force; cherchez continuellement sa face!","de":"Fraget nach dem HERRN und nach seiner Macht; suchet sein Angesicht allezeit!"},"reference":{"tr":"1. Tarihler 16:11","en":"1 Chronicles 16:11","es":"1 Crónicas 16:11","pt":"1 Crônicas 16:11","fr":"1 Chroniques 16:11","de":"1. Chronik 16:11"}},{"theme":"trust","text":{"tr":"Hagga ilahisi Yahve'ye güvenenler Siyon Dağı gibidir, sarsılmaz, sonsuza dek kalır.","en":"Those who trust in Yahweh are as Mount Zion, which can’t be moved, but remains forever.","es":"Cántico gradual. LOS que confían en Jehová son como el monte de Sión, que no deslizará: estará para siempre.","pt":"Aqueles que confiam no Senhor são como o monte Sião, que não pode ser abalado, mas permanece para sempre.","fr":"Cantique de Maaloth. Ceux qui se confient en l'Éternel sont comme la montagne de Sion, qui ne peut être ébranlée, et qui subsiste à toujours.","de":"Ein Lied im höhern Chor. Die auf den HERRN hoffen, die werden nicht fallen, sondern ewig bleiben wie der Berg Zion."},"reference":{"tr":"Mezmur 125:1","en":"Psalm 125:1","es":"Salmo 125:1","pt":"Salmo 125:1","fr":"Psaume 125:1","de":"Psalm 125:1"}},{"theme":"rest","text":{"tr":"Yedinci güne gelindiğinde Tanrı yapmakta olduğu bütün işi bitirdi; ve yaptığı işten yedinci günde dinlendi. Tanrı yedinci günü kutsadı ve onu kutsal kıldı. Çünkü Tanrı yaptığı bütün yaratılış işini tamamlayıp o gün dinlendi.","en":"On the seventh day God finished his work which he had done; and he rested on the seventh day from all his work which he had done. God blessed the seventh day, and made it holy, because he rested in it from all his work of creation which he had done.","es":"Y acabó Dios en el día séptimo su obra que hizo, y reposó el día séptimo de toda su obra que había hecho. Y bendijo Dios al día séptimo, y santificólo, porque en él reposó de toda su obra que había Dios criado y hecho.","pt":"Ora, havendo Deus completado no dia sétimo a obra que tinha feito, descansou nesse dia de toda a obra que fizera. Abençoou Deus o sétimo dia, e o santificou; porque nele descansou de toda a sua obra que criara e fizera.","fr":"Et Dieu eut achevé au septième jour son œuvre qu'il avait faite; et il se reposa au septième jour de toute son œuvre qu'il avait faite. Et Dieu bénit le septième jour, et le sanctifia, parce qu'en ce jour-là il se reposa de toute son œuvre, pour l'accomplissement de laquelle Dieu avait créé.","de":"Und also vollendete Gott am siebenten Tage seine Werke, die er machte, und ruhte am siebenten Tage von allen seinen Werken, die er machte. Und Gott segnete den siebenten Tag und heiligte ihn, darum daß er an demselben geruht hatte von allen seinen Werken, die Gott schuf und machte."},"reference":{"tr":"Yaratılış 2:2-3","en":"Genesis 2:2-3","es":"Génesis 2:2-3","pt":"Gênesis 2:2-3","fr":"Genèse 2:2-3","de":"1. Mose 2:2-3"}},{"theme":"hope","text":{"tr":"Ama ben Yahve'ye bakacağım. Kurtuluşumun Tanrısı'nı bekleyeceğim. Tanrım beni duyacak.","en":"But as for me, I will look to Yahweh. I will wait for the God of my salvation. My God will hear me.","es":"Yo empero á Jehová esperaré, esperaré al Dios de mi salud: el Dios mío me oirá.","pt":"Eu, porém, confiarei no Senhor; esperarei no Deus da minha salvação. O meu Deus me ouvirá.","fr":"Mais moi, je regarderai vers l'Éternel, je m'attendrai au Dieu de mon salut; mon Dieu m'exaucera.","de":"Ich aber will auf den HERRN schauen und des Gottes meines Heils warten; mein Gott wird mich hören."},"reference":{"tr":"Mika 7:7","en":"Micah 7:7","es":"Miqueas 7:7","pt":"Miquéias 7:7","fr":"Michée 7:7","de":"Micha 7:7"}},{"theme":"anxiety","text":{"tr":"Korktuğumda, sana güvenirim. Tanrı’ya, sözünü överim. Tanrı’ya güvenirim, korkmam. İnsan bana ne yapabilir?","en":"When I am afraid, I will put my trust in you. In God, I praise his word. In God, I put my trust. I will not be afraid. What can flesh do to me?","es":"En el día que temo, yo en ti confío. En Dios alabaré su palabra: en Dios he confiado, no temeré lo que la carne me hiciere.","pt":"No dia em que eu temer, hei de confiar em ti. Em Deus, cuja palavra eu lovo, em Deus ponho a minha confiança e não terei medo;","fr":"Tout le jour mes adversaires me poursuivent; car plusieurs font la guerre contre moi, ô Dieu Très-Haut! Le jour où je craindrai, je me confierai en toi.","de":"Meine Feinde schnauben täglich; denn viele streiten stolz wider mich. Wenn ich mich fürchte, so hoffe ich auf dich."},"reference":{"tr":"Mezmur 56:3-4","en":"Psalm 56:3-4","es":"Salmo 56:3-4","pt":"Salmo 56:3-4","fr":"Psaume 56:3-4","de":"Psalm 56:3-4"}},{"theme":"guidance","text":{"tr":"Bilgece rehberliğin olmadığı yerde ulus düşer, ama öğüt verenlerin çokluğunda zafer vardır.","en":"Where there is no wise guidance, the nation falls, but in the multitude of counselors there is victory.","es":"Cuando faltaren las industrias, caerá el pueblo: mas en la multitud de consejeros hay salud.","pt":"Quando não há sábia direção, o povo cai; mas na multidão de conselheiros há segurança.","fr":"Le peuple tombe, faute de prudence; mais la délivrance est dans la multitude des gens de bon conseil.","de":"Wo nicht Rat ist, da geht das Volk unter; wo aber viel Ratgeber sind, da geht es wohl zu."},"reference":{"tr":"Süleyman’ın Özdeyişleri 11:14","en":"Proverbs 11:14","es":"Proverbios 11:14","pt":"Provérbios 11:14","fr":"Proverbes 11:14","de":"Sprüche 11:14"}},{"theme":"joy","text":{"tr":"Ey doğrular, Yahve ile sevinin ve coşun! Ey yüreği doğru olanlar, sevinçle haykırın!","en":"Be glad in Yahweh, and rejoice, you righteous! Shout for joy, all you who are upright in heart!","es":"Alegraos en Jehová, y gozaos, justos: y cantad todos vosotros los rectos de corazón.","pt":"Alegrai-vos no Senhor, e regozijai-vos, vós justos; e cantai de júbilo, todos vós que sois retos de coração.","fr":"Justes, réjouissez-vous en l'Éternel, et vous égayez! Chantez de joie, vous tous qui avez le cœur droit!","de":"Freuet euch des HERRN und seid fröhlich, ihr Gerechten, und rühmet, alle ihr Frommen."},"reference":{"tr":"Mezmur 32:11","en":"Psalm 32:11","es":"Salmo 32:11","pt":"Salmo 32:11","fr":"Psaume 32:11","de":"Psalm 32:11"}},{"theme":"love","text":{"tr":"Büyük sular sevgiyi söndüremez, seller de onu boğamaz. Bir adam sevgisi için evinin bütün servetini verse, tümüyle hor görülür.","en":"Many waters can’t quench love, neither can floods drown it. If a man would give all the wealth of his house for love, he would be utterly scorned.","es":"Las muchas aguas no podrán apagar el amor, ni lo ahogarán los ríos. Si diese el hombre toda la hacienda de su casa por este amor, de cierto lo menospreciaran.","pt":"As muitas águas não podem apagar o amor, nem os rios afogá- lo. Se alguém oferecesse todos os bens de sua casa pelo amor, seria de todo desprezado.","fr":"Beaucoup d'eaux ne pourraient éteindre cet amour-là, et les fleuves même ne le pourraient pas noyer; si quelqu'un donnait tous les biens de sa maison pour cet amour-là, certainement on n'en tiendrait aucun compte.","de":"daß auch viele Wasser nicht mögen die Liebe auslöschen noch die Ströme sie ertränken. Wenn einer alles Gut in seinem Hause um die Liebe geben wollte, so gölte es alles nichts."},"reference":{"tr":"Ezgiler Ezgisi 8:7","en":"Song of Solomon 8:7","es":"Cantar de los Cantares 8:7","pt":"Cânticos 8:7","fr":"Cantique des Cantiques 8:7","de":"Hoheslied 8:7"}},{"theme":"gratitude","text":{"tr":"Yahve’yi öv, ey canım, iyiliklerinin hiçbirini unutma.","en":"Praise Yahweh, my soul, and don’t forget all his benefits;","es":"Bendice, alma mía á Jehová, y no olvides ninguno de sus beneficios.","pt":"Bendize, ó minha alma, ao Senhor, e não te esqueças de nenhum dos seus benefícios.","fr":"Mon âme, bénis l'Éternel, et n'oublie aucun de ses bienfaits!","de":"Lobe den HERRN, meine Seele, und vergiß nicht, was er dir Gutes getan hat:"},"reference":{"tr":"Mezmur 103:2","en":"Psalm 103:2","es":"Salmo 103:2","pt":"Salmo 103:2","fr":"Psaume 103:2","de":"Psalm 103:2"}},{"theme":"comfort","text":{"tr":"Bana iyiliğinin bir işaretini göster, ta ki, benden nefret edenler bunu görüp utansınlar, çünkü sen, ey Yahve, bana yardım ettin ve beni teselli ettin.","en":"Show me a sign of your goodness, that those who hate me may see it, and be shamed, because you, Yahweh, have helped me, and comforted me.","es":"Haz conmigo señal para bien, y véanla los que me aborrecen, y sean avergonzados; porque tú, Jehová, me ayudaste, y me consolaste.","pt":"Mostra-me um sinal do teu favor, para que o vejam aqueles que me odeiam, e sejam envergonhados, por me haveres tu, Senhor, ajuntado e confortado.","fr":"Accorde-moi un signe de ta faveur, et que ceux qui me haïssent le voient et soient confus, parce que toi, ô Éternel, tu m'auras aidé et tu m'auras consolé.","de":"Tu ein Zeichen an mir, daß mir's wohl gehe, daß es sehen, die mich hassen, und sich schämen müssen, daß du mir beistehst, HERR, und tröstest mich."},"reference":{"tr":"Mezmur 86:17","en":"Psalm 86:17","es":"Salmo 86:17","pt":"Salmo 86:17","fr":"Psaume 86:17","de":"Psalm 86:17"}},{"theme":"faith","text":{"tr":"Çünkü Tanrı’dan doğan herkes dünyayı yener. Dünyaya karşı zafer kazandıran imanınızdır.","en":"For whatever is born of God overcomes the world. This is the victory that has overcome the world: your faith.","es":"Porque todo aquello que es nacido de Dios vence al mundo: y esta es la victoria que vence al mundo, nuestra fe.","pt":"porque todo o que é nascido de Deus vence o mundo; e esta é a vitória que vence o mundo: a nossa fé.","fr":"Parce que tout ce qui est né de Dieu, est victorieux du monde, et la victoire qui a vaincu le monde, c'est notre foi.","de":"Denn alles, was von Gott geboren ist, überwindet die Welt; und unser Glaube ist der Sieg, der die Welt überwunden hat."},"reference":{"tr":"1. Yuhanna 5:4","en":"1 John 5:4","es":"1 Juan 5:4","pt":"1 João 5:4","fr":"1 Jean 5:4","de":"1. Johannes 5:4"}},{"theme":"forgiveness","text":{"tr":"Bende temiz bir yürek yarat, ey Tanrım. İçimdeki doğru ruhu tazele.","en":"Create in me a clean heart, O God. Renew a right spirit within me.","es":"Crea en mí, oh Dios, un corazón limpio; y renueva un espíritu recto dentro de mí.","pt":"Cria em mim, ó Deus, um coração puro, e renova em mim um espírito estável.","fr":"Fais-moi entendre la joie et l'allégresse; que les os que tu as brisés, se réjouissent!","de":"Laß mich hören Freude und Wonne, daß die Gebeine fröhlich werden, die du zerschlagen hast."},"reference":{"tr":"Mezmur 51:10","en":"Psalm 51:10","es":"Salmo 51:10","pt":"Salmo 51:10","fr":"Psaume 51:10","de":"Psalm 51:10"}},{"theme":"peace","text":{"tr":"'Yahve sizi kutsasın ve korusun. Yahve yüzünü sizin üzerinizde ışıldatsın ve size lütfetsin. Yahve yüzünü size doğru kaldırsın ve size esenlik versin.'","en":"‘Yahweh bless you, and keep you. Yahweh make his face to shine on you, and be gracious to you. Yahweh lift up his face toward you, and give you peace.’","es":"Jehová te bendiga, y te guarde: Haga resplandecer Jehová su rostro sobre ti, y haya de ti misericordia: Jehová alce á ti su rostro, y ponga en ti paz.","pt":"O Senhor te abençoe e te guarde; o Senhor faça resplandecer o seu rosto sobre ti, e tenha misericórdia de ti; o Senhor levante sobre ti o seu rosto, e te dê a paz.","fr":"L'Éternel te bénisse et te garde! L'Éternel fasse luire sa face sur toi et te fasse grâce! L'Éternel tourne sa face vers toi et te donne la paix!","de":"Der HERR segne dich und behüte dich; der HERR lasse sein Angesicht leuchten über dir und sei dir gnädig; der HERR hebe sein Angesicht über dich und gebe dir Frieden."},"reference":{"tr":"Çölde Sayım 6:24-26","en":"Numbers 6:24-26","es":"Números 6:24-26","pt":"Números 6:24-26","fr":"Nombres 6:24-26","de":"4. Mose 6:24-26"}},{"theme":"strength","text":{"tr":"David’in mezmuru Yahve benim ışığım ve kurtuluşumdur. Kimden çekineyim? Yahve yaşamımın gücüdür. Kimden korkayım?","en":"Yahweh is my light and my salvation. Whom shall I fear? Yahweh is the strength of my life. Of whom shall I be afraid?","es":"Salmo de David. JEHOVÁ es mi luz y mi salvación: ¿de quién temeré? Jehová es la fortaleza de mi vida: ¿de quién he de atemorizarme?","pt":"O Senhor é a minha luz e a minha salvação; a quem temerei? O Senhor é a força da minha vida; de quem me recearei?","fr":"Psaume de David. L'Éternel est ma lumière et ma délivrance; de qui aurais-je peur? L'Éternel est le rempart de ma vie; de qui aurais-je de la crainte?","de":"Ein Psalm Davids. Der HERR ist mein Licht und mein Heil; vor wem sollte ich mich fürchten! Der HERR ist meines Lebens Kraft; vor wem sollte mir grauen!"},"reference":{"tr":"Mezmur 27:1","en":"Psalm 27:1","es":"Salmo 27:1","pt":"Salmo 27:1","fr":"Psaume 27:1","de":"Psalm 27:1"}},{"theme":"trust","text":{"tr":"Tanrı’yı sevenler ve O’nun amacına göre çağrılmış olanlar için her şeyin birlikte iyilik için çalıştığını biliyoruz.","en":"We know that all things work together for good for those who love God, to those who are called according to his purpose.","es":"Y sabemos que á los que á Dios aman, todas las cosas les ayudan á bien, es á saber, á los que conforme al propósito son llamados.","pt":"E sabemos que todas as coisas concorrem para o bem daqueles que amam a Deus, daqueles que são chamados segundo o seu propósito.","fr":"Or, nous savons aussi que toutes choses concourent au bien de ceux qui aiment Dieu, de ceux qui sont appelés, selon son dessein.","de":"Wir wissen aber, daß denen, die Gott lieben, alle Dinge zum Besten dienen, denen, die nach dem Vorsatz berufen sind."},"reference":{"tr":"Romalılar 8:28","en":"Romans 8:28","es":"Romanos 8:28","pt":"Romanos 8:28","fr":"Romains 8:28","de":"Römer 8:28"}},{"theme":"rest","text":{"tr":"Sürüsünü bir çoban gibi güdecek. Kuzuları kollarına alacak, bağrında taşıyacak onları. Yavrularını usul usul güdecek.","en":"He will feed his flock like a shepherd. He will gather the lambs in his arm, and carry them in his bosom. He will gently lead those who have their young.","es":"Como pastor apacentará su rebaño; en su brazo cogerá los corderos, y en su seno los llevará; pastoreará suavemente las paridas.","pt":"Como pastor ele apascentará o seu rebanho; entre os seus braços recolherá os cordeirinhos, e os levará no seu regaço; as que amamentam, ele as guiará mansamente.","fr":"Il paîtra son troupeau comme un berger; il rassemblera les agneaux entre ses bras, et les portera dans son sein; il conduira celles qui allaitent.","de":"Er wird seine Herde weiden wie ein Hirte; er wird die Lämmer in seine Arme sammeln und in seinem Busen tragen und die Schafmütter führen."},"reference":{"tr":"Yeşaya 40:11","en":"Isaiah 40:11","es":"Isaías 40:11","pt":"Isaías 40:11","fr":"Ésaïe 40:11","de":"Jesaja 40:11"}},{"theme":"hope","text":{"tr":"Sahip olduğumuz bu umut, can için gemi çapası gibi güvenilir ve sarsılmazdır, perdenin ardındaki iç bölmeye girer.","en":"This hope we have as an anchor of the soul, a hope both sure and steadfast and entering into that which is within the veil;","es":"La cual tenemos como segura y firme ancla del alma, y que entra hasta dentro del velo;","pt":"a qual temos como âncora da alma, segura e firme, e que penetra até o interior do véu;","fr":"Espérance que nous gardons comme une ancre de l'âme, sûre et ferme, et qui pénètre au-dedans du voile,","de":"welche wir haben als einen sichern und festen Anker unsrer Seele, der auch hineingeht in das Inwendige des Vorhangs,"},"reference":{"tr":"İbraniler 6:19","en":"Hebrews 6:19","es":"Hebreos 6:19","pt":"Hebreus 6:19","fr":"Hébreux 6:19","de":"Hebräer 6:19"}},{"theme":"anxiety","text":{"tr":"Ama şimdi ey Yakov, seni yaratan, ey İsrael, sana biçim veren Yahve şöyle diyor: “Korkma, çünkü seni kurtardım. Seni adınla çağırdım. Sen benimsin. Sulardan geçtiğinde ben seninle olacağım, ırmakların içinden geçerken senin üzerine taşmayacak. Ateşin içinden yürürken yanmayacaksın, alev de seni yakmayacak.","en":"But now Yahweh who created you, Jacob, and he who formed you, Israel says: “Don’t be afraid, for I have redeemed you. I have called you by your name. You are mine. When you pass through the waters, I will be with you; and through the rivers, they will not overflow you. When you walk through the fire, you will not be burned, and flame will not scorch you.","es":"Y AHORA, así dice Jehová Criador tuyo, oh Jacob, y Formador tuyo, oh Israel: No temas, porque yo te redimí; te puse nombre, mío eres tú. Cuando pasares por las aguas, yo seré contigo; y por los ríos, no te anegarán. Cuando pasares por el fuego, no te quemarás, ni la llama arderá en ti.","pt":"Mas agora, assim diz o Senhor que te criou, ó Jacó, e que te formou, ó Israel: Não temas, porque eu te remi; chamei-te pelo teu nome, tu és meu. Quando passares pelas águas, eu serei contigo; quando pelos rios, eles não te submergirão; quando passares pelo fogo, não te queimarás, nem a chama arderá em ti.","fr":"Maintenant, ainsi a dit l'Éternel, celui qui t'a créé, ô Jacob! celui qui t'a formé, ô Israël! ne crains point, car je t'ai racheté; je t'ai appelé par ton nom, tu es à moi. Quand tu traverseras les eaux, je serai avec toi; et les fleuves, ils ne te submergeront point. Quand tu passeras par le feu, tu n'en seras pas brûlé, et la flamme ne te consumera pas.","de":"Und nun spricht der HERR, der dich geschaffen hat, Jakob, und dich gemacht hat, Israel: Fürchte dich nicht, denn ich habe dich erlöst; ich habe dich bei deinem Namen gerufen; du bist mein! Denn so du durch Wasser gehst, will ich bei dir sein, daß dich die Ströme nicht sollen ersäufen; und so du ins Feuer gehst, sollst du nicht brennen, und die Flamme soll dich nicht versengen."},"reference":{"tr":"Yeşaya 43:1-2","en":"Isaiah 43:1-2","es":"Isaías 43:1-2","pt":"Isaías 43:1-2","fr":"Ésaïe 43:1-2","de":"Jesaja 43:1-2"}},{"theme":"guidance","text":{"tr":"İsteğini yapmayı bana öğret, çünkü sen benim Tanrım’sın. Senin Ruh’un iyidir. Doğruluk diyarında bana öncülük et.","en":"Teach me to do your will, for you are my God. Your Spirit is good. Lead me in the land of uprightness.","es":"Enséñame á hacer tu voluntad, porque tú eres mi Dios: tu buen espíritu me guíe á tierra de rectitud.","pt":"Ensina-me a fazer a tua vontade, pois tu és o meu Deus; guie-me o teu bom Espírito por terreno plano.","fr":"Enseigne-moi à faire ta volonté, car tu es mon Dieu. Que ton bon Esprit me conduise dans le droit chemin!","de":"Lehre mich tun nach deinem Wohlgefallen, denn du bist mein Gott; dein guter Geist führe mich auf ebener Bahn."},"reference":{"tr":"Mezmur 143:10","en":"Psalm 143:10","es":"Salmo 143:10","pt":"Salmo 143:10","fr":"Psaume 143:10","de":"Psalm 143:10"}},{"theme":"joy","text":{"tr":"Melek onlara, “Korkmayın, çünkü işte, size tüm insanlığı çok sevindirecek bir haber müjdeliyorum” dedi.","en":"The angel said to them, “Don’t be afraid, for behold, I bring you good news of great joy which will be to all the people.","es":"Mas el ángel les dijo: No temáis; porque he aquí os doy nuevas de gran gozo, que será para todo el pueblo:","pt":"O anjo, porém, lhes disse: Não temais, porquanto vos trago novas de grande alegria que o será para todo o povo:","fr":"Alors l'ange leur dit: N'ayez point de peur; car je vous annonce une grande joie, qui sera pour tout le peuple;","de":"Und der Engel sprach zu ihnen: Fürchtet euch nicht! siehe, ich verkündige euch große Freude, die allem Volk widerfahren wird;"},"reference":{"tr":"Luka 2:10","en":"Luke 2:10","es":"San Lucas 2:10","pt":"Lucas 2:10","fr":"Luc 2:10","de":"Lukas 2:10"}},{"theme":"love","text":{"tr":"Sevgi komşuya zarar vermez. Bu nedenle sevgi, Kutsal Yasa’nın yerine getirilmesidir.","en":"Love doesn’t harm a neighbor. Love therefore is the fulfillment of the law.","es":"La caridad no hace mal al prójimo: así que, el cumplimento de la ley es la caridad.","pt":"O amor não faz mal ao próximo. De modo que o amor é o cumprimento da lei.","fr":"L'amour ne fait point de mal au prochain; l'amour est donc l'accomplissement de la loi.","de":"Denn Liebe tut dem Nächsten nichts Böses. So ist nun die Liebe des Gesetzes Erfüllung."},"reference":{"tr":"Romalılar 13:10","en":"Romans 13:10","es":"Romanos 13:10","pt":"Romanos 13:10","fr":"Romains 13:10","de":"Römer 13:10"}},{"theme":"gratitude","text":{"tr":"Tanrı'nın adını bir ezgiyle öveceğim, O’nu şükranla yücelteceğim.","en":"I will praise the name of God with a song, and will magnify him with thanksgiving.","es":"Alabaré yo el nombre de Dios con cántico, ensalzarélo con alabanza.","pt":"Louvarei o nome de Deus com um cântico, e engrandecê-lo-ei com ação de graças.","fr":"Pour moi, je suis affligé et dans la douleur; ta délivrance, ô Dieu, me mettra dans une haute retraite!","de":"Ich aber bin elend, und mir ist wehe. Gott, deine Hilfe schütze mich!"},"reference":{"tr":"Mezmur 69:30","en":"Psalm 69:30","es":"Salmo 69:30","pt":"Salmo 69:30","fr":"Psaume 69:30","de":"Psalm 69:30"}},{"theme":"comfort","text":{"tr":"“Avutun, halkımı avutun” diyor Tanrınız.","en":"“Comfort, comfort my people,” says your God.","es":"CONSOLAOS, consolaos, pueblo mío, dice vuestro Dios.","pt":"Consolai, consolai o meu povo, diz o vosso Deus.","fr":"Consolez, consolez mon peuple, dit votre Dieu.","de":"Tröstet, tröstet mein Volk! spricht euer Gott;"},"reference":{"tr":"Yeşaya 40:1","en":"Isaiah 40:1","es":"Isaías 40:1","pt":"Isaías 40:1","fr":"Ésaïe 40:1","de":"Jesaja 40:1"}},{"theme":"faith","text":{"tr":"İşte, canı övüngendir. İçinde doğru değildir, ancak doğru kişi kendi imanıyla yaşayacaktır.","en":"Behold, his soul is puffed up. It is not upright in him, but the righteous will live by his faith.","es":"He aquí se enorgullece aquel cuya alma no es derecha en él: mas el justo en su fe vivirá.","pt":"Eis o soberbo! A sua alma não é reta nele; mas o justo pela sua fé viverá.","fr":"Voici, l'âme de celui qui s'élève n'est pas droite en lui; mais le juste vivra par sa foi.","de":"Siehe, wer halsstarrig ist, der wird keine Ruhe in seinem Herzen haben; der Gerechte aber wird seines Glaubens leben."},"reference":{"tr":"Habakkuk 2:4","en":"Habakkuk 2:4","es":"Habacuc 2:4","pt":"Habacuque 2:4","fr":"Habacuc 2:4","de":"Habakuk 2:4"}},{"theme":"forgiveness","text":{"tr":"Çünkü haksızlıklarına karşı merhametli olacağım, Günahlarını ve suçlarını artık hatırlamayacağım.’”","en":"For I will be merciful to their unrighteousness. I will remember their sins and lawless deeds no more.”","es":"Porque seré propicio á sus injusticias, y de sus pecados y de sus iniquidades no me acordaré más.","pt":"Porque serei misericordioso para com suas iniquidades, e de seus pecados não me lembrarei mais.","fr":"Parce que je serai apaisé à l'égard de leurs injustices, et que je ne me souviendrai plus de leurs péchés, ni de leurs iniquités.","de":"Denn ich will gnädig sein ihrer Untugend und ihren Sünden, und ihrer Ungerechtigkeit will ich nicht mehr gedenken.\""},"reference":{"tr":"İbraniler 8:12","en":"Hebrews 8:12","es":"Hebreos 8:12","pt":"Hebreus 8:12","fr":"Hébreux 8:12","de":"Hebräer 8:12"}},{"theme":"peace","text":{"tr":"Yasanı sevenler büyük esenliğe sahip olurlar. Hiçbir şey onları tökezletemez.","en":"Those who love your law have great peace. Nothing causes them to stumble.","es":"Mucha paz tienen los que aman tu ley; y no hay para ellos tropiezo.","pt":"Muita paz têm os que amam a tua lei, e não há nada que os faça tropeçar.","fr":"Il y a une grande paix pour ceux qui aiment ta loi, et rien ne peut les renverser.","de":"Großen Frieden haben, die dein Gesetz lieben; sie werden nicht straucheln."},"reference":{"tr":"Mezmur 119:165","en":"Psalm 119:165","es":"Salmo 119:165","pt":"Salmo 119:165","fr":"Psaume 119:165","de":"Psalm 119:165"}},{"theme":"strength","text":{"tr":"Yahve benim gücüm ve ezgimdir. O benim kurtuluşum oldu. O benim Tanrım'dır ve O'nu öveceğim, babamın Tanrısı ve ben O'nu yücelteceğim.","en":"Yah is my strength and song. He has become my salvation. This is my God, and I will praise him; my father’s God, and I will exalt him.","es":"Jehová es mi fortaleza, y mi canción, y hame sido por salud: éste es mi Dios, y á éste engrandeceré; Dios de mi padre, y á éste ensalzaré.","pt":"O Senhor é a minha força, e o meu cântico; ele se tem tornado a minha salvação; é ele o meu Deus, portanto o louvarei; é o Deus de meu pai, por isso o exaltarei.","fr":"L'Éternel est ma force et ma louange: il a été mon libérateur. Il est mon Dieu, je le glorifierai; il est le Dieu de mon père, je l'exalterai.","de":"Der HERR ist meine Stärke und mein Lobgesang und ist mein Heil. Das ist mein Gott, ich will ihn preisen; er ist meines Vaters Gott, ich will ihn erheben."},"reference":{"tr":"Mısır’dan Çıkış 15:2","en":"Exodus 15:2","es":"Éxodo 15:2","pt":"Êxodo 15:2","fr":"Exode 15:2","de":"2. Mose 15:2"}},{"theme":"trust","text":{"tr":"Ama ben sana güveniyorum, ey Yahve. “Tanrım sensin” dedim.","en":"But I trust in you, Yahweh. I said, “You are my God.”","es":"Mas yo en ti confié, oh Jehová: yo dije: Dios mío eres tú.","pt":"Mas eu confio em ti, ó Senhor; e digo: Tu és o meu Deus.","fr":"Car j'entends les propos secrets de beaucoup de gens; la frayeur m'environne; ils se concertent ensemble contre moi, et complotent de m'ôter la vie.","de":"Denn ich höre, wie mich viele schelten, Schrecken ist um und um; sie ratschlagen miteinander über mich und denken, mir das Leben zu nehmen."},"reference":{"tr":"Mezmur 31:14","en":"Psalm 31:14","es":"Salmo 31:14","pt":"Salmo 31:14","fr":"Psaume 31:14","de":"Psalm 31:14"}},{"theme":"rest","text":{"tr":"Yahve’de dinlen, O’nu sabırla bekle. Üzülme işi yolunda olup da, kötü planlarını gerçekleştiren kişi için.","en":"Rest in Yahweh, and wait patiently for him. Don’t fret because of him who prospers in his way, because of the man who makes wicked plots happen.","es":"Calla á Jehová, y espera en él: no te alteres con motivo del que prospera en su camino, por el hombre que hace maldades.","pt":"Descansa no Senhor, e espera nele; não te enfades por causa daquele que prospera em seu caminho, por causa do homem que executa maus desígnios.","fr":"Demeure tranquille en regardant à l'Éternel, et t'attends à lui; ne t'irrite pas contre celui qui vient à bout de ses desseins.","de":"Sei stille dem HERRN und warte auf ihn; erzürne dich nicht über den, dem sein Mutwille glücklich fortgeht."},"reference":{"tr":"Mezmur 37:7","en":"Psalm 37:7","es":"Salmo 37:7","pt":"Salmo 37:7","fr":"Psaume 37:7","de":"Psalm 37:7"}},{"theme":"hope","text":{"tr":"Şimdi, ey Efendim, ben neyi bekliyorum? Umudum sende.","en":"Now, Lord, what do I wait for? My hope is in you.","es":"Y ahora, Señor, ¿qué esperaré? Mi esperanza en ti está.","pt":"Agora, pois, Senhor, que espero eu? a minha esperança está em ti.","fr":"Oui, l'homme se promène comme une ombre; oui, c'est en vain qu'on s'agite; on amasse des biens, et on ne sait qui les recueillera.","de":"Sie gehen daher wie ein Schemen und machen sich viel vergebliche Unruhe; sie sammeln, und wissen nicht, wer es einnehmen wird."},"reference":{"tr":"Mezmur 39:7","en":"Psalm 39:7","es":"Salmo 39:7","pt":"Salmo 39:7","fr":"Psaume 39:7","de":"Psalm 39:7"}},{"theme":"anxiety","text":{"tr":"Önünden giden Yahve'nin kendisidir. O seninle olacak. Seni yüzüstü bırakmayacak ve seni terk etmeyecek. Korkma. Yılma.”","en":"Yahweh himself is who goes before you. He will be with you. He will not fail you nor forsake you. Don’t be afraid. Don’t be discouraged.”","es":"Y Jehová es el que va delante de ti; él será contigo, no te dejará, ni te desamparará; no temas, ni te intimides.","pt":"O Senhor, pois, é aquele que vai adiante de ti; ele será contigo, não te deixará, nem te desamparará. Não temas, nem te espantes.","fr":"C'est l'Éternel qui marche devant toi; il sera lui-même avec toi; il ne te laissera point, et ne t'abandonnera point; ne crains point, et ne sois point effrayé.","de":"Der HERR aber, der selber vor euch her geht, der wird mit dir sein und wird die Hand nicht abtun noch dich verlassen. Fürchte dich nicht und erschrick nicht."},"reference":{"tr":"Yasa’nın Tekrarı 31:8","en":"Deuteronomy 31:8","es":"Deuteronomio 31:8","pt":"Deuteronômio 31:8","fr":"Deutéronome 31:8","de":"5. Mose 31:8"}},{"theme":"guidance","text":{"tr":"Körleri bilmedikleri bir yoldan getireceğim. Onlara bilmedikleri yollarda öncülük edeceğim. Önlerindeki karanlığı ışık, eğri yerleri düz edeceğim. Bunları yapacağım ve onları bırakmayacağım.”","en":"I will bring the blind by a way that they don’t know. I will lead them in paths that they don’t know. I will make darkness light before them, and crooked places straight. I will do these things, and I will not forsake them.","es":"Y guiaré los ciegos por camino que no sabían, haréles pisar por las sendas que no habían conocido; delante de ellos tornaré las tinieblas en luz, y los rodeos en llanura. Estas cosas les haré, y no los desampararé.","pt":"E guiarei os cegos por um caminho que não conhecem; fá-los- ei caminhar por veredas que não têm conhecido; tornarei as trevas em luz perante eles, e aplanados os caminhos escabrosos. Estas coisas lhes farei; e não os desampararei.","fr":"Je ferai marcher les aveugles par un chemin qu'ils ne connaissent pas; je les conduirai par des sentiers inconnus; je changerai devant eux les ténèbres en lumière, et les lieux montueux en plaine. Je leur ferai cela, et ne les abandonnerai point.","de":"Aber die Blinden will ich auf dem Wege leiten, den sie nicht wissen; ich will sie führen auf den Steigen, die sie nicht kennen; ich will die Finsternis vor ihnen her zum Licht machen und das Höckerichte zur Ebene. Solches will ich ihnen alles tun und sie nicht verlassen."},"reference":{"tr":"Yeşaya 42:16","en":"Isaiah 42:16","es":"Isaías 42:16","pt":"Isaías 42:16","fr":"Ésaïe 42:16","de":"Jesaja 42:16"}},{"theme":"joy","text":{"tr":"Çünkü, ey Yahve, işinle beni sevindirdin. Senin ellerinin işleriyle zafer kazanıyorum.","en":"For you, Yahweh, have made me glad through your work. I will triumph in the works of your hands.","es":"Por cuanto me has alegrado, oh Jehová, con tus obras; en las obras de tus manos me gozo.","pt":"Pois me alegraste, Senhor, pelos teus feitos; exultarei nas obras das tuas mãos.","fr":"Sur la lyre à dix cordes et sur le luth, au son des accords de la harpe!","de":"auf den zehn Saiten und Psalter, mit Spielen auf der Harfe."},"reference":{"tr":"Mezmur 92:4","en":"Psalm 92:4","es":"Salmo 92:4","pt":"Salmo 92:4","fr":"Psaume 92:4","de":"Psalm 92:4"}},{"theme":"love","text":{"tr":"Bütün bunların üstüne yetkin birliğin bağı olan sevgide yürüyün.","en":"Above all these things, walk in love, which is the bond of perfection.","es":"Y sobre todas estas cosas vestíos de caridad, la cual es el vínculo de la perfección.","pt":"E, sobre tudo isto, revestí-vos do amor, que é o vínculo da perfeição.","fr":"Mais par-dessus toutes choses revêtez-vous de la charité, qui est le lien de la perfection.","de":"Über alles aber ziehet an die Liebe, die da ist das Band der Vollkommenheit."},"reference":{"tr":"Koloseliler 3:14","en":"Colossians 3:14","es":"Colosenses 3:14","pt":"Colossenses 3:14","fr":"Colossiens 3:14","de":"Kolosser 3:14"}},{"theme":"gratitude","text":{"tr":"Yahve'ye şükredin, çünkü O iyidir, çünkü O'nun sevgi dolu iyiliği sonsuza dek sürer.","en":"Oh give thanks to Yahweh, for he is good, for his loving kindness endures forever.","es":"Celebrad á Jehová, porque es bueno; porque su misericordia es eterna.","pt":"Dai graças ao Senhor, porque ele é bom; porque a sua benignidade dura para sempre.","fr":"Célébrez l'Éternel, car il est bon, car sa miséricorde demeure à toujours!","de":"Danket dem HERRN; denn er ist freundlich, und seine Güte währet ewiglich."},"reference":{"tr":"1. Tarihler 16:34","en":"1 Chronicles 16:34","es":"1 Crónicas 16:34","pt":"1 Crônicas 16:34","fr":"1 Chroniques 16:34","de":"1. Chronik 16:34"}},{"theme":"comfort","text":{"tr":"Yasımı benim için raksa çevirdin. Çulumu çıkardın ve bana sevinç giydirdin,","en":"You have turned my mourning into dancing for me. You have removed my sackcloth, and clothed me with gladness,","es":"Has tornado mi endecha en baile; desataste mi saco, y ceñísteme de alegría.","pt":"Tornaste o meu pranto em regozijo, tiraste o meu cilício, e me cingiste de alegria;","fr":"Éternel, écoute, aie pitié de moi! Éternel, sois-moi en aide!","de":"HERR, höre und sei mir gnädig! HERR, sei mein Helfer!"},"reference":{"tr":"Mezmur 30:11","en":"Psalm 30:11","es":"Salmo 30:11","pt":"Salmo 30:11","fr":"Psaume 30:11","de":"Psalm 30:11"}},{"theme":"faith","text":{"tr":"Yaşayanlar diyarında Yahve’nin iyiliğini göreceğimden ben hâlâ eminim.","en":"I am still confident of this: I will see the goodness of Yahweh in the land of the living.","es":"Hubiera yo desmayado, si no creyese que tengo de ver la bondad de Jehová en la tierra de los vivientes.","pt":"Creio que hei de ver a bondade do Senhor na terra dos viventes.","fr":"Ah! si je n'avais cru que je verrais les biens de l'Éternel dans la terre des vivants!","de":"Ich glaube aber doch, daß ich sehen werde das Gute des HERRN im Lande der Lebendigen."},"reference":{"tr":"Mezmur 27:13","en":"Psalm 27:13","es":"Salmo 27:13","pt":"Salmo 27:13","fr":"Psaume 27:13","de":"Psalm 27:13"}},{"theme":"forgiveness","text":{"tr":"Duaya durduğunuz zaman, birine karşı bir şeyiniz varsa onu bağışlayın ki, gökteki Babanız da sizin suçlarınızı bağışlasın.","en":"Whenever you stand praying, forgive, if you have anything against anyone; so that your Father, who is in heaven, may also forgive you your transgressions.","es":"Y cuando estuviereis orando, perdonad, si tenéis algo contra alguno, para que vuestro Padre que está en los cielos os perdone también á vosotros vuestras ofensas.","pt":"Quando estiverdes orando, perdoai, se tendes alguma coisa contra alguém, para que também vosso Pai que está no céu, vos perdoe as vossas ofensas.","fr":"Mais quand vous vous présenterez pour faire votre prière, si vous avez quelque chose contre quelqu'un, pardonnez-lui, afin que votre Père qui est dans les cieux vous pardonne aussi vos offenses.","de":"Und wenn ihr stehet und betet, so vergebet, wo ihr etwas wider jemand habt, auf daß auch euer Vater im Himmel euch vergebe eure Fehler."},"reference":{"tr":"Markos 11:25","en":"Mark 11:25","es":"Marcos 11:25","pt":"Marcos 11:25","fr":"Marc 11:25","de":"Markus 11:25"}},{"theme":"peace","text":{"tr":"Mümkünse, elinizden geldiğince, bütün insanlarla barış içinde olun.","en":"If it is possible, as much as it is up to you, be at peace with all men.","es":"Si se puede hacer, cuanto está en vosotros, tened paz con todos los hombres.","pt":"Se for possível, quanto depender de vós, tende paz com todos os homens.","fr":"S'il se peut faire, et autant qu'il dépend de vous, ayez la paix avec tous les hommes.","de":"Ist es möglich, soviel an euch ist, so habt mit allen Menschen Frieden."},"reference":{"tr":"Romalılar 12:18","en":"Romans 12:18","es":"Romanos 12:18","pt":"Romanos 12:18","fr":"Romains 12:18","de":"Römer 12:18"}},{"theme":"strength","text":{"tr":"Güçlü ve cesur olun. Onlardan korkmayın ve onlardan ürkmeyin; çünkü seninle birlikte giden Tanrın Yahve'nin kendisidir. Seni yüzüstü bırakmayacak ve seni terk etmeyecek.”","en":"Be strong and courageous. Don’t be afraid or scared of them; for Yahweh your God himself is who goes with you. He will not fail you nor forsake you.”","es":"Esforzaos y cobrad ánimo; no temáis, ni tengáis miedo de ellos: que Jehová tu Dios es el que va contigo: no te dejará ni te desamparará.","pt":"Sede fortes e corajosos; não temais, nem vos atemorizeis diante deles; porque o Senhor vosso Deus é quem vai convosco. Não vos deixará, nem vos desamparará.","fr":"Fortifiez-vous et prenez courage; ne craignez point, et ne soyez point effrayés devant eux; car c'est l'Éternel ton Dieu qui marche avec toi; il ne te laissera point, et ne t'abandonnera point.","de":"Seid getrost und unverzagt, fürchtet euch nicht und laßt euch nicht vor ihnen grauen; denn der HERR, dein Gott, wird selber mit dir wandeln und wird die Hand nicht abtun noch dich verlassen."},"reference":{"tr":"Yasa’nın Tekrarı 31:6","en":"Deuteronomy 31:6","es":"Deuteronomio 31:6","pt":"Deuteronômio 31:6","fr":"Deutéronome 31:6","de":"5. Mose 31:6"}},{"theme":"trust","text":{"tr":"Ama ben senin sevgi dolu iyiliğine güveniyorum. Yüreğim senin kurtuluşunla seviniyor.","en":"But I trust in your loving kindness. My heart rejoices in your salvation.","es":"Mas yo en tu misericordia he confiado: alegraráse mi corazón en tu salud.","pt":"Mas eu confio na tua benignidade; o meu coração se regozija na tua salvação.","fr":"De peur que mon ennemi ne dise: J'ai eu le dessus; que mes adversaires ne se réjouissent, si j'étais ébranlé.","de":"daß nicht mein Feind rühme, er sei mein mächtig geworden, und meine Widersacher sich nicht freuen, daß ich niederlage."},"reference":{"tr":"Mezmur 13:5","en":"Psalm 13:5","es":"Salmo 13:5","pt":"Salmo 13:5","fr":"Psaume 13:5","de":"Psalm 13:5"}},{"theme":"rest","text":{"tr":"Sakinlikle bir avuç dolusu, emekle ve rüzgârı kovalamakla iki avuç dolusundan daha iyidir.","en":"Better is a handful, with quietness, than two handfuls with labor and chasing after wind.","es":"Mas vale el un puño lleno con descanso, que ambos puños llenos con trabajo y aflicción de espíritu.","pt":"Melhor é um punhado com tranqüilidade do que ambas as mãos cheias com trabalho e vão desejo.","fr":"Mieux vaut plein le creux de la main avec repos, que plein les deux paumes, avec travail et tourment d'esprit.","de":"Es ist besser eine Handvoll mit Ruhe denn beide Fäuste voll mit Mühe und Haschen nach Wind."},"reference":{"tr":"Vaiz 4:6","en":"Ecclesiastes 4:6","es":"Eclesiastés 4:6","pt":"Eclesiastes 4:6","fr":"Ecclésiaste 4:6","de":"Prediger 4:6"}},{"theme":"hope","text":{"tr":"Bizi tüm kötülüklerden kurtarmak, arıtıp kendisine ait, iyi işlerde gayretli bir halk yapmak üzere kendisini bizim için feda eden büyük Tanrımız ve Kurtarıcımız Yeşua Mesih’in kutlu umudunu, yücelik içinde görünmesini bekliyoruz.","en":"looking for the blessed hope and appearing of the glory of our great God and Savior, Jesus Christ;","es":"Esperando aquella esperanza bienaventurada, y la manifestación gloriosa del gran Dios y Salvador nuestro Jesucristo,","pt":"aguardando a bem-aventurada esperança e o aparecimento da glória do nosso grande Deus e Salvador Cristo Jesus,","fr":"En attendant la bienheureuse espérance, et la manifestation de la gloire de notre grand Dieu et Sauveur Jésus-Christ,","de":"und warten auf die selige Hoffnung und Erscheinung der Herrlichkeit des großen Gottes und unsers Heilandes, Jesu Christi,"},"reference":{"tr":"Titus 2:13","en":"Titus 2:13","es":"Tito 2:13","pt":"Tito 2:13","fr":"Tite 2:13","de":"Titus 2:13"}},{"theme":"anxiety","text":{"tr":"Hagga ilahisi Gözlerimi tepelere kaldırıyorum. Yardımım nereden gelecek? Yardımım yeri ve göğü yaratan Yahve'den gelecek.","en":"I will lift up my eyes to the hills. Where does my help come from? My help comes from Yahweh, who made heaven and earth.","es":"Cántico gradual. ALZARÉ mis ojos á los montes, de donde vendrá mi socorro. Mi socorro viene de Jehová, que hizo los cielos y la tierra.","pt":"Elevo os meus olhos para os montes; de onde me vem o socorro? O meu socorro vem do Senhor, que fez os céus e a terra.","fr":"Cantique de Maaloth. J'élève mes yeux vers les montagnes d'où me viendra le secours. Mon secours vient de l'Éternel, qui a fait les cieux et la terre.","de":"Ein Lied im höhern Chor. Ich hebe meine Augen auf zu den Bergen von welchen mir Hilfe kommt. Meine Hilfe kommt von dem HERRN, der Himmel und Erde gemacht hat."},"reference":{"tr":"Mezmur 121:1-2","en":"Psalm 121:1-2","es":"Salmo 121:1-2","pt":"Salmo 121:1-2","fr":"Psaume 121:1-2","de":"Psalm 121:1-2"}},{"theme":"guidance","text":{"tr":"Karanlıkta ve ölümün gölgesinde oturanların üzerine parlayacak, ayaklarımızı esenlik yoluna yöneltecek.”","en":"to shine on those who sit in darkness and the shadow of death; to guide our feet into the way of peace.”","es":"Para dar luz á los que habitan en tinieblas y en sombra de muerte; para encaminar nuestros pies por camino de paz.","pt":"para alumiar aos que jazem nas trevas e na sombra da morte, a fim de dirigir os nossos pés no caminho da paz.","fr":"Pour éclairer ceux qui sont assis dans les ténèbres et dans l'ombre de la mort, et pour conduire nos pas dans le chemin de la paix.","de":"auf daß er erscheine denen, die da sitzen in Finsternis und Schatten des Todes, und richte unsere Füße auf den Weg des Friedens."},"reference":{"tr":"Luka 1:79","en":"Luke 1:79","es":"San Lucas 1:79","pt":"Lucas 1:79","fr":"Luc 1:79","de":"Lukas 1:79"}},{"theme":"joy","text":{"tr":"Yahve'de çok sevineceğim! Canım Tanrım'da sevinç duyacak, çünkü O beni kurtuluş giysisiyle sardı. Damadın çelenkle süslenmesi gibi, gelinin de mücevherleriyle süslenmesi gibi, doğruluk kaftanıyla beni örttü.","en":"I will greatly rejoice in Yahweh! My soul will be joyful in my God; for he has clothed me with the garments of salvation. He has covered me with the robe of righteousness, as a bridegroom decks himself with a garland, and as a bride adorns herself with her jewels.","es":"En gran manera me gozaré en Jehová, mi alma se alegrará en mi Dios; porque me vistió de vestidos de salud, rodeóme de manto de justicia, como á novio me atavió, y como á novia compuesta de sus joyas.","pt":"Regozijar-me-ei muito no Senhor, a minha alma se alegrará no meu Deus, porque me vestiu de vestes de salvação, cobriu-me com o manto de justiça, como noivo que se adorna com uma grinalda, e como noiva que se enfeita com as suas jóias.","fr":"Je me réjouirai en l'Éternel, et mon âme s'égaiera en mon Dieu; car il m'a revêtu des vêtements du salut, et m'a couvert du manteau de la justice, comme un époux se pare d'un diadème et comme une épouse s'orne de ses joyaux.","de":"Ich freue mich im HERRN, und meine Seele ist fröhlich in meinem Gott; denn er hat mich angezogen mit Kleidern des Heils und mit dem Rock der Gerechtigkeit gekleidet, wie einen Bräutigam, mit priesterlichem Schmuck geziert, und wie eine Braut, die in ihrem Geschmeide prangt."},"reference":{"tr":"Yeşaya 61:10","en":"Isaiah 61:10","es":"Isaías 61:10","pt":"Isaías 61:10","fr":"Ésaïe 61:10","de":"Jesaja 61:10"}},{"theme":"love","text":{"tr":"Baba’nın bize ne kadar büyük bir sevgi verdiğine bakın! Bize “Tanrı’nın çocukları” deniyor. Bu nedenle dünya bizi tanımıyor, çünkü Baba’yı da tanımadı.","en":"See how great a love the Father has given to us, that we should be called children of God! For this cause the world doesn’t know us, because it didn’t know him.","es":"MIRAD cuál amor nos ha dado el Padre, que seamos llamados hijos de Dios: por esto el mundo no nos conoce, porque no le conoce á él.","pt":"Vede que grande amor nos tem concedido o Pai: que fôssemos chamados filhos de Deus; e nós o somos. Por isso o mundo não nos conhece; porque não conheceu a ele.","fr":"Voyez quel amour le Père nous a témoigné, que nous soyons appelés enfants de Dieu! Le monde ne nous connaît point, parce qu'il ne l'a point connu.","de":"Sehet, welch eine Liebe hat uns der Vater erzeigt, daß wir Gottes Kinder sollen heißen! Darum kennt euch die Welt nicht; denn sie kennt ihn nicht."},"reference":{"tr":"1. Yuhanna 3:1","en":"1 John 3:1","es":"1 Juan 3:1","pt":"1 João 3:1","fr":"1 Jean 3:1","de":"1. Johannes 3:1"}},{"theme":"gratitude","text":{"tr":"Bana yönelik tüm iyiliklerine karşılık Yahve’ye ne vereyim?","en":"What will I give to Yahweh for all his benefits toward me?","es":"¿Qué pagaré á Jehová por todos sus beneficios para conmigo?","pt":"Que darei eu ao Senhor por todos os benefícios que me tem feito?","fr":"Que rendrai-je à l'Éternel? Tous ses bienfaits sont sur moi.","de":"Wie soll ich dem HERRN vergelten alle seine Wohltat, die er an mir tut?"},"reference":{"tr":"Mezmur 116:12","en":"Psalm 116:12","es":"Salmo 116:12","pt":"Salmo 116:12","fr":"Psaume 116:12","de":"Psalm 116:12"}},{"theme":"comfort","text":{"tr":"Öyle düşünüyorum ki, içinde bulunduğumuz bu zamanın acıları, bize gösterilecek olan yücelikle karşılaştırılmaya değmez.","en":"For I consider that the sufferings of this present time are not worthy to be compared with the glory which will be revealed toward us.","es":"Porque tengo por cierto que lo que en este tiempo se padece, no es de comparar con la gloria venidera que en nosotros ha de ser manifestada.","pt":"Pois tenho para mim que as aflições deste tempo presente não se podem comparar com a glória que em nós há de ser revelada.","fr":"Car j'estime qu'il n'y a point de proportion entre les souffrances du temps présent et la gloire à venir, qui sera manifestée en nous.","de":"Denn ich halte es dafür, daß dieser Zeit Leiden der Herrlichkeit nicht wert sei, die an uns soll offenbart werden."},"reference":{"tr":"Romalılar 8:18","en":"Romans 8:18","es":"Romanos 8:18","pt":"Romanos 8:18","fr":"Romains 8:18","de":"Römer 8:18"}},{"theme":"faith","text":{"tr":"Ama Yeşua, söylenen sözü duyunca, hemen havra yöneticisine, “Korkma, yalnızca iman et” dedi.","en":"But Jesus, when he heard the message spoken, immediately said to the ruler of the synagogue, “Don’t be afraid, only believe.”","es":"Mas luego Jesús, oyendo esta razón que se decía, dijo al príncipe de la sinagoga: No temas, cree solamente.","pt":"O que percebendo Jesus, disse ao chefe da sinagoga: Não temas, crê somente.","fr":"Aussitôt que Jésus eut entendu cela, il dit au chef de la synagogue: Ne crains point, crois seulement.","de":"Jesus aber hörte alsbald die Rede, die da gesagt ward, und sprach zu dem Obersten der Schule: Fürchte dich nicht, glaube nur!"},"reference":{"tr":"Markos 5:36","en":"Mark 5:36","es":"Marcos 5:36","pt":"Marcos 5:36","fr":"Marc 5:36","de":"Markus 5:36"}},{"theme":"forgiveness","text":{"tr":"Çünkü sen iyisin, bağışlamaya hazırsın, ey Efendi seni çağıran herkese karşı boldur sevgi dolu iyiliğin.","en":"For you, Lord, are good, and ready to forgive; abundant in loving kindness to all those who call on you.","es":"Porque tú, Señor, eres bueno y perdonador, y grande en misericordia para con todos los que te invocan.","pt":"Porque tu, Senhor, és bom, e pronto a perdoar, e abundante em benignidade para com todos os que te invocam.","fr":"Car tu es bon et clément, Seigneur, et plein de bonté pour tous ceux qui t'invoquent.","de":"Denn du, HERR, bist gut und gnädig, von großer Güte allen, die dich anrufen."},"reference":{"tr":"Mezmur 86:5","en":"Psalm 86:5","es":"Salmo 86:5","pt":"Salmo 86:5","fr":"Psaume 86:5","de":"Psalm 86:5"}},{"theme":"peace","text":{"tr":"Doğruluğun ürünü barış yapıcıları tarafından barış içinde ekilir.","en":"Now the fruit of righteousness is sown in peace by those who make peace.","es":"Y el fruto de justicia se siembra en paz para aquellos que hacen paz.","pt":"Ora, o fruto da justiça semeia-se em paz para aqueles que promovem a paz.","fr":"Or, le fruit de la justice se sème dans la paix, pour ceux qui s'adonnent à la paix.","de":"Die Frucht aber der Gerechtigkeit wird gesät im Frieden denen, die den Frieden halten."},"reference":{"tr":"Yakup 3:18","en":"James 3:18","es":"Santiago 3:18","pt":"Tiago 3:18","fr":"Jacques 3:18","de":"Jakobus 3:18"}},{"theme":"strength","text":{"tr":"Yah benim gücüm ve ezgimdir. O benim kurtuluşum oldu.","en":"Yah is my strength and song. He has become my salvation.","es":"Mi fortaleza y mi canción es JAH; y él me ha sido por salud.","pt":"O Senhor é a minha força e o meu cântico; tornou-se a minha salvação.","fr":"L'Éternel est ma force et mon cantique; il a été mon libérateur.","de":"Der HERR ist meine Macht und mein Psalm und ist mein Heil."},"reference":{"tr":"Mezmur 118:14","en":"Psalm 118:14","es":"Salmo 118:14","pt":"Salmo 118:14","fr":"Psaume 118:14","de":"Psalm 118:14"}},{"theme":"trust","text":{"tr":"Ne mutlu Yahve’ye güvenen insana, kibirlilere, yalana sapanlara saygı duymayana.","en":"Blessed is the man who makes Yahweh his trust, and doesn’t respect the proud, nor such as turn away to lies.","es":"Bienaventurado el hombre que puso á Jehová por su confianza, y no mira á los soberbios, ni á los que declinan á la mentira.","pt":"Bem-aventurado o homem que faz do Senhor a sua confiança, e que não atenta para os soberbos nem para os apóstatas mentirosos.","fr":"Et il a mis dans ma bouche un nouveau chant de louange à notre Dieu. Plusieurs le verront, et auront de la crainte, et se confieront en l'Éternel.","de":"und hat mir ein neues Lied in meinen Mund gegeben, zu loben unsern Gott. Das werden viele sehen und den HERRN fürchten und auf ihn hoffen."},"reference":{"tr":"Mezmur 40:4","en":"Psalm 40:4","es":"Salmo 40:4","pt":"Salmo 40:4","fr":"Psaume 40:4","de":"Psalm 40:4"}},{"theme":"rest","text":{"tr":"Ana kucağında sütten kesilmiş bir çocuk gibi gerçekten canımı sakinleştirip susturdum, canım sütten kesilmiş bir çocuk gibi.","en":"Surely I have stilled and quieted my soul, like a weaned child with his mother, like a weaned child is my soul within me.","es":"En verdad que me he comportado y he acallado mi alma, como un niño destetado de su madre: como un niño destetado está mi alma.","pt":"Pelo contrário, tenho feito acalmar e sossegar a minha alma; qual criança desmamada sobre o seio de sua mãe, qual criança desmamada está a minha alma para comigo.","fr":"N'ai-je pas soumis et fait taire mon âme, comme un enfant sevré fait envers sa mère? Mon âme est en moi comme un enfant sevré.","de":"Ja, ich habe meine Seele gesetzt und gestillt; so ist meine Seele in mir wie ein entwöhntes Kind bei seiner Mutter."},"reference":{"tr":"Mezmur 131:2","en":"Psalm 131:2","es":"Salmo 131:2","pt":"Salmo 131:2","fr":"Psaume 131:2","de":"Psalm 131:2"}},{"theme":"hope","text":{"tr":"Yahve kendisinden korkanlardan, sevgi dolu iyiliğine umut bağlayanlardan hoşlanır.","en":"Yahweh takes pleasure in those who fear him, in those who hope in his loving kindness.","es":"Complácese Jehová en los que le temen, y en los que esperan en su misericordia.","pt":"O Senhor se compraz nos que o temem, nos que esperam na sua benignidade.","fr":"L'Éternel prend son plaisir en ceux qui le craignent, en ceux qui s'attendent à sa bonté.","de":"Der HERR hat Gefallen an denen, die ihn fürchten, die auf seine Güte hoffen."},"reference":{"tr":"Mezmur 147:11","en":"Psalm 147:11","es":"Salmo 147:11","pt":"Salmo 147:11","fr":"Psaume 147:11","de":"Psalm 147:11"}},{"theme":"anxiety","text":{"tr":"Öyleyse bu şeyler için ne diyelim? Eğer Tanrı bizden yanaysa, kim bize karşı olabilir?","en":"What then shall we say about these things? If God is for us, who can be against us?","es":"¿Pues qué diremos á esto? Si Dios por nosotros, ¿quién contra nosotros?","pt":"Que diremos, pois, a estas coisas? Se Deus é por nós, quem será contra nós?","fr":"Que dirons-nous donc sur cela? Si Dieu est pour nous, qui sera contre nous?","de":"Was wollen wir nun hierzu sagen? Ist Gott für uns, wer mag wider uns sein?"},"reference":{"tr":"Romalılar 8:31","en":"Romans 8:31","es":"Romanos 8:31","pt":"Romanos 8:31","fr":"Romains 8:31","de":"Römer 8:31"}},{"theme":"guidance","text":{"tr":"Canımı onarır. Adı uğruna doğruluk yollarında bana rehberlik eder.","en":"He restores my soul. He guides me in the paths of righteousness for his name’s sake.","es":"Confortará mi alma; guiaráme por sendas de justicia por amor de su nombre.","pt":"Refrigera a minha alma; guia-me nas veredas da justiça por amor do seu nome.","fr":"Il restaure mon âme, il me conduit dans les sentiers de la justice, à cause de son nom.","de":"Er erquicket meine Seele; er führet mich auf rechter Straße um seines Namens willen."},"reference":{"tr":"Mezmur 23:3","en":"Psalm 23:3","es":"Salmo 23:3","pt":"Salmo 23:3","fr":"Psaume 23:3","de":"Psalm 23:3"}},{"theme":"joy","text":{"tr":"Neşeli yürek iyi ilaçtır, ama ezilmiş bir yürek kemikleri kurutur.","en":"A cheerful heart makes good medicine, but a crushed spirit dries up the bones.","es":"El corazón alegre produce buena disposición: mas el espíritu triste seca los huesos.","pt":"O coração alegre serve de bom remédio; mas o espírito abatido seca os ossos.","fr":"Le cœur joyeux vaut un remède; mais l'esprit abattu dessèche les os.","de":"Ein fröhlich Herz macht das Leben lustig; aber ein betrübter Mut vertrocknet das Gebein."},"reference":{"tr":"Süleyman’ın Özdeyişleri 17:22","en":"Proverbs 17:22","es":"Proverbios 17:22","pt":"Provérbios 17:22","fr":"Proverbes 17:22","de":"Sprüche 17:22"}},{"theme":"love","text":{"tr":"Yahve merhametli ve lütufkârdır, öfkelenmekte yavaş, sevgi dolu iyiliği boldur.","en":"Yahweh is merciful and gracious, slow to anger, and abundant in loving kindness.","es":"Misericordioso y clemente es Jehová; lento para la ira, y grande en misericordia.","pt":"Compassivo e misericordioso é o Senhor; tardio em irar-se e grande em benignidade.","fr":"L'Éternel est compatissant et miséricordieux; lent à la colère et abondant en grâce.","de":"Barmherzig und gnädig ist der HERR, geduldig und von großer Güte."},"reference":{"tr":"Mezmur 103:8","en":"Psalm 103:8","es":"Salmo 103:8","pt":"Salmo 103:8","fr":"Psaume 103:8","de":"Psalm 103:8"}},{"theme":"gratitude","text":{"tr":"Bu nedenle, bize sarsılmaz bir krallık verildiğine göre lütfa sahip olalım. Öyle ki, Tanrı’yı hoşnut edecek biçimde saygı ve korkuyla hizmet edelim.","en":"Therefore, receiving a Kingdom that can’t be shaken, let us have grace, through which we serve God acceptably, with reverence and awe,","es":"Así que, tomando el reino inmóvil, retengamos la gracia por la cual sirvamos á Dios agradándole con temor y reverencia;","pt":"Pelo que, recebendo nós um reino que não pode ser abalado, retenhamos a graça, pela qual sirvamos a Deus agradavelmente, com reverência e temor;","fr":"C'est pourquoi, saisissant le royaume inébranlable, conservons la grâce, afin que par elle nous rendions notre culte à Dieu d'une manière qui lui soit agréable, avec respect et crainte;","de":"Darum, dieweil wir empfangen ein unbeweglich Reich, haben wir Gnade, durch welche wir sollen Gott dienen, ihm zu gefallen, mit Zucht und Furcht;"},"reference":{"tr":"İbraniler 12:28","en":"Hebrews 12:28","es":"Hebreos 12:28","pt":"Hebreus 12:28","fr":"Hébreux 12:28","de":"Hebräer 12:28"}},{"theme":"comfort","text":{"tr":"Avare avare dolaşmalarımı saydın. Gözyaşlarımı kabına koydun. Onlar senin kitabında değil mi?","en":"You count my wanderings. You put my tears into your bottle. Aren’t they in your book?","es":"Mis huídas has tú contado: pon mis lágrimas en tu redoma: ¿no están ellas en tu libro?","pt":"Tu contaste as minhas aflições; põe as minhas lágrimas no teu odre; não estão elas no teu livro?","fr":"Ils comptent sur l'iniquité pour se sauver. O Dieu, précipite les peuples dans ta colère!","de":"Sollten sie mit ihrer Bosheit entrinnen? Gott, stoße solche Leute ohne alle Gnade hinunter!"},"reference":{"tr":"Mezmur 56:8","en":"Psalm 56:8","es":"Salmo 56:8","pt":"Salmo 56:8","fr":"Psaume 56:8","de":"Psalm 56:8"}},{"theme":"faith","text":{"tr":"Açıkça dile getirdiğimiz umuda sımsıkı tutunalım. Çünkü vaat eden sadıktır.","en":"let us hold fast the confession of our hope without wavering; for he who promised is faithful.","es":"Mantengamos firme la profesión de nuestra fe sin fluctuar; que fiel es el que prometió:","pt":"retenhamos inabalável a confissão da nossa esperança, porque fiel é aquele que fez a promessa;","fr":"Retenons sans fléchir la profession de notre espérance; car celui qui a fait la promesse est fidèle.","de":"und lasset uns halten an dem Bekenntnis der Hoffnung und nicht wanken; denn er ist treu, der sie verheißen hat;"},"reference":{"tr":"İbraniler 10:23","en":"Hebrews 10:23","es":"Hebreos 10:23","pt":"Hebreus 10:23","fr":"Hébreux 10:23","de":"Hebräer 10:23"}},{"theme":"forgiveness","text":{"tr":"Bu nedenle, Mesih Yeşua’da olanlara artık hiçbir mahkûmiyet yoktur. Onlar benliğe göre değil, Ruh'a göre yürürler.","en":"There is therefore now no condemnation to those who are in Christ Jesus, who don’t walk according to the flesh, but according to the Spirit.","es":"AHORA pues, ninguna condenación hay para los que están en Cristo Jesús, los que no andan conforme á la carne, mas conforme al espíritu.","pt":"Portanto, agora nenhuma condenação há para os que estão em Cristo Jesus.","fr":"Il n'y a donc maintenant aucune condamnation pour ceux qui sont en Jésus-Christ, qui marchent, non selon la chair, mais selon l'esprit;","de":"So ist nun nichts Verdammliches an denen, die in Christo Jesu sind, die nicht nach dem Fleisch wandeln, sondern nach dem Geist."},"reference":{"tr":"Romalılar 8:1","en":"Romans 8:1","es":"Romanos 8:1","pt":"Romanos 8:1","fr":"Romains 8:1","de":"Römer 8:1"}},{"theme":"peace","text":{"tr":"Doğruluğun işi esenlik olacak, doğruluğun sonucu da sonsuz sakinlik ve güven olacaktır.","en":"The work of righteousness will be peace; and the effect of righteousness, quietness and confidence forever.","es":"Y el efecto de la justicia será paz; y la labor de justicia, reposo y seguridad para siempre.","pt":"E a obra da justiça será paz; e o efeito da justiça será sossego e segurança para sempre.","fr":"La justice produira la paix, et le fruit de la justice sera le repos et la sûreté pour toujours.","de":"und der Gerechtigkeit Frucht wird Friede sein, und der Gerechtigkeit Nutzen wird ewige Stille und Sicherheit sein,"},"reference":{"tr":"Yeşaya 32:17","en":"Isaiah 32:17","es":"Isaías 32:17","pt":"Isaías 32:17","fr":"Ésaïe 32:17","de":"Jesaja 32:17"}},{"theme":"strength","text":{"tr":"Çünkü Tanrı bize korku ruhu değil, güç, sevgi ve özdenetim ruhu verdi.","en":"For God didn’t give us a spirit of fear, but of power, love, and self-control.","es":"Porque no nos ha dado Dios el espíritu de temor, sino el de fortaleza, y de amor, y de templanza.","pt":"Porque Deus não nos deu o espírito de covardia, mas de poder, de amor e de moderação.","fr":"Car Dieu ne nous a point donné un esprit de timidité, mais de force, de charité et de prudence.","de":"Denn Gott hat uns nicht gegeben den Geist der Furcht, sondern der Kraft und der Liebe und der Zucht."},"reference":{"tr":"2. Timoteos 1:7","en":"2 Timothy 1:7","es":"2 Timoteo 1:7","pt":"2 Timóteo 1:7","fr":"2 Timothée 1:7","de":"2. Timotheus 1:7"}},{"theme":"trust","text":{"tr":"Ey Ordular Yahvesi, ne mutlu sana güvenen insana.","en":"Yahweh of Armies, blessed is the man who trusts in you.","es":"Jehová de los ejércitos, dichoso el hombre que en ti confía.","pt":"Ó Senhor dos exércitos, bem-aventurado o homem que em ti põe a sua confiança.","fr":"Car l'Éternel Dieu est un soleil et un bouclier; l'Éternel donne la grâce et la gloire; il ne refuse aucun bien à ceux qui marchent dans l'intégrité.","de":"Denn Gott der HERR ist Sonne und Schild; der HERR gibt Gnade und Ehre: er wird kein Gutes mangeln lassen den Frommen."},"reference":{"tr":"Mezmur 84:12","en":"Psalm 84:12","es":"Salmo 84:12","pt":"Salmo 84:12","fr":"Psaume 84:12","de":"Psalm 84:12"}},{"theme":"rest","text":{"tr":"Tanrınız Yahve, güçlü Kurtarıcı, senin içindedir. O sevinçle senin için sevinecek. Sevgisinde seni sakinleştirecek. Ezgi söyleyerek senin için coşacaktır.","en":"Yahweh, your God, is among you, a mighty one who will save. He will rejoice over you with joy. He will calm you in his love. He will rejoice over you with singing.","es":"Jehová en medio de ti, poderoso, él salvará; gozaráse sobre ti con alegría, callará de amor, se regocijará sobre ti con cantar.","pt":"O Senhor teu Deus está no meio de ti, poderoso para te salvar; ele se deleitará em ti com alegria; renovar-te-á no seu amor, regozijar-se-á em ti com júbilo.","fr":"L'Éternel ton Dieu est au milieu de toi, un héros qui sauve. Il se réjouira à cause de toi d'une grande joie; il se taira dans son amour; il se réjouira à ton sujet avec chant de triomphe.","de":"denn der HERR, dein Gott, ist bei dir, ein starker Heiland; er wird sich über dich freuen und dir freundlich sein und vergeben und wird über dir mit Schall fröhlich sein."},"reference":{"tr":"Sefanya 3:17","en":"Zephaniah 3:17","es":"Sofonías 3:17","pt":"Sofonias 3:17","fr":"Sophonie 3:17","de":"Zefanja 3:17"}},{"theme":"hope","text":{"tr":"Yahve kendisini bekleyenlere, kendisini arayan cana iyidir.","en":"Yahweh is good to those who wait for him, to the soul who seeks him.","es":"Bueno es Jehová á los que en él esperan, al alma que le buscare.","pt":"Bom é o Senhor para os que esperam por ele, para a alma que o busca.","fr":"L'Éternel est bon pour ceux qui s'attendent à lui, pour l'âme qui le recherche.","de":"Denn der HERR ist freundlich dem, der auf sie harrt, und der Seele, die nach ihm fragt."},"reference":{"tr":"Ağıtlar 3:25","en":"Lamentations 3:25","es":"Lamentaciones 3:25","pt":"Lamentações 3:25","fr":"Lamentations 3:25","de":"Klagelieder 3:25"}},{"theme":"anxiety","text":{"tr":"Yahve benden yanadır. Korkmam. İnsan bana ne yapabilir?","en":"Yahweh is on my side. I will not be afraid. What can man do to me?","es":"Jehová está por mí: no temeré lo que me pueda hacer el hombre.","pt":"O Senhor é por mim, não recearei; que me pode fazer o homem?","fr":"L'Éternel est pour moi, je ne craindrai point; que me ferait l'homme?","de":"Der HERR ist mit mir, darum fürchte ich mich nicht; was können mir Menschen tun?"},"reference":{"tr":"Mezmur 118:6","en":"Psalm 118:6","es":"Salmo 118:6","pt":"Salmo 118:6","fr":"Psaume 118:6","de":"Psalm 118:6"}},{"theme":"guidance","text":{"tr":"Seni bilgeliğin yolunda eğittim. Seni dosdoğru yollara yönelttim.","en":"I have taught you in the way of wisdom. I have led you in straight paths.","es":"Por el camino de la sabiduría te he encaminado, y por veredas derechas te he hecho andar.","pt":"Eu te ensinei o caminho da sabedoria; guiei-te pelas veredas da retidão.","fr":"Je t'ai enseigné le chemin de la sagesse, et je t'ai fait marcher dans les sentiers de la droiture.","de":"Ich will dich den Weg der Weisheit führen; ich will dich auf rechter Bahn leiten,"},"reference":{"tr":"Süleyman’ın Özdeyişleri 4:11","en":"Proverbs 4:11","es":"Proverbios 4:11","pt":"Provérbios 4:11","fr":"Proverbes 4:11","de":"Sprüche 4:11"}},{"theme":"joy","text":{"tr":"Canım zengin yiyeceklere doyar gibi doyacak. Ağzım neşeli dudaklarla seni övecek.","en":"My soul shall be satisfied as with the richest food. My mouth shall praise you with joyful lips,","es":"Como de meollo y de grosura será saciada mi alma; y con labios de júbilo te alabará mi boca,","pt":"A minha alma se farta, como de tutano e de gordura; e a minha boca te louva com alegres lábios.","fr":"Ainsi je te bénirai pendant ma vie; j'élèverai mes mains en ton nom.","de":"Daselbst wollte ich dich gerne loben mein Leben lang und meine Hände in deinem Namen aufheben."},"reference":{"tr":"Mezmur 63:5","en":"Psalm 63:5","es":"Salmo 63:5","pt":"Salmo 63:5","fr":"Psaume 63:5","de":"Psalm 63:5"}},{"theme":"love","text":{"tr":"Ama merhamette zengin olan Tanrı, bize duyduğu büyük sevgisinden ötürü, suçlarımız yüzünden ölüyken, bizi Mesih’le birlikte diriltti, lütfuyla kurtuldunuz.","en":"But God, being rich in mercy, for his great love with which he loved us, even when we were dead through our trespasses, made us alive together with Christ (by grace you have been saved),","es":"Empero Dios, que es rico en misericordia, por su mucho amor con que nos amó, Aun estando nosotros muertos en pecados, nos dió vida juntamente con Cristo; por gracia sois salvos;","pt":"Mas Deus, sendo rico em misericórdia, pelo seu muito amor com que nos amou, estando nós ainda mortos em nossos delitos, nos vivificou juntamente com Cristo (pela graça sois salvos),","fr":"Mais Dieu, qui est riche en miséricorde à cause de la grande charité dont il nous a aimés, Lorsque nous étions morts dans nos fautes, nous a rendus à la vie ensemble en Christ, (c'est par grâce que vous êtes sauvés; )","de":"Aber Gott, der da reich ist an Barmherzigkeit, durch seine große Liebe, damit er uns geliebt hat, da wir tot waren in den Sünden, hat er uns samt Christo lebendig gemacht (denn aus Gnade seid ihr selig geworden)"},"reference":{"tr":"Efesliler 2:4-5","en":"Ephesians 2:4-5","es":"Efesios 2:4-5","pt":"Efésios 2:4-5","fr":"Éphésiens 2:4-5","de":"Epheser 2:4-5"}},{"theme":"gratitude","text":{"tr":"Mezmur - Şabat Günü için ilahi Yahve’ye şükretmek, ey Yüceler Yücesi, adını ilahilerle övmek,","en":"It is a good thing to give thanks to Yahweh, to sing praises to your name, Most High;","es":"Salmo: Canción para el día del Sábado. BUENO es alabar á Jehová, y cantar salmos á tu nombre, oh Altísimo;","pt":"Bom é render graças ao Senhor, e cantar louvores ao teu nome, ó Altíssimo,","fr":"Psaume. Cantique pour le jour du Sabbat.","de":"Ein Psalmlied auf den Sabbattag."},"reference":{"tr":"Mezmur 92:1","en":"Psalm 92:1","es":"Salmo 92:1","pt":"Salmo 92:1","fr":"Psaume 92:1","de":"Psalm 92:1"}},{"theme":"comfort","text":{"tr":"Ölümü sonsuza dek yuttu! Efendi Yahve bütün yüzlerden gözyaşlarını silecek. Halkının utancını bütün yeryüzünden kaldıracak, çünkü bunu Yahve söyledi.","en":"He has swallowed up death forever! The Lord Yahweh will wipe away tears from off all faces. He will take the reproach of his people away from off all the earth, for Yahweh has spoken it.","es":"Destruirá á la muerte para siempre; y enjugará el Señor toda lágrima de todos los rostros: y quitará la afrenta de su pueblo de toda la tierra: porque Jehová lo ha dicho.","pt":"Aniquilará a morte para sempre, e assim enxugará o Senhor Deus as lágrimas de todos os rostos, e tirará de toda a terra o opróbrio do seu povo; porque o Senhor o disse.","fr":"Il détruira la mort pour jamais; le Seigneur, l'Éternel, essuiera les larmes de tous les visages, et fera disparaître de toute la terre l'opprobre de son peuple; car l'Éternel a parlé.","de":"Er wird den Tod verschlingen ewiglich; und der Herr, HERR wird die Tränen von allen Angesichtern abwischen und wird aufheben alle Schmach seines Volks in allen Landen; denn der HERR hat's gesagt."},"reference":{"tr":"Yeşaya 25:8","en":"Isaiah 25:8","es":"Isaías 25:8","pt":"Isaías 25:8","fr":"Ésaïe 25:8","de":"Jesaja 25:8"}},{"theme":"faith","text":{"tr":"İyi mücadeleyi verdim, yarışı tamamladım, imanı korudum.","en":"I have fought the good fight. I have finished the course. I have kept the faith.","es":"He peleado la buena batalla, he acabado la carrera, he guardado la fe.","pt":"Combati o bom combate, acabei a carreira, guardei a fé.","fr":"J'ai combattu le bon combat, j'ai achevé la course, j'ai gardé la foi.","de":"Ich habe einen guten Kampf gekämpft, ich habe den Lauf vollendet, ich habe Glauben gehalten;"},"reference":{"tr":"2. Timoteos 4:7","en":"2 Timothy 4:7","es":"2 Timoteo 4:7","pt":"2 Timóteo 4:7","fr":"2 Timothée 4:7","de":"2. Timotheus 4:7"}},{"theme":"forgiveness","text":{"tr":"Ey Yah, sen eğer günahların kaydını tutarsan, kim ayakta durabilir, ey Efendim? Ama sende bağışlanma var, bunun için senden korkulsun.","en":"If you, Yah, kept a record of sins, Lord, who could stand? But there is forgiveness with you, therefore you are feared.","es":"JAH, si mirares á los pecados, ¿quién, oh Señor, podrá mantenerse? Empero hay perdón cerca de ti, para que seas temido.","pt":"Se tu, Senhor, observares as iniqüidades, Senhor, quem subsistirá? Mas contigo está o perdão, para que sejas temido.","fr":"Éternel, si tu prends garde aux iniquités, Seigneur, qui subsistera? Mais le pardon se trouve auprès de toi, afin qu'on te craigne.","de":"So du willst, HERR, Sünden zurechnen, HERR, wer wird bestehen? Denn bei dir ist die Vergebung, daß man dich fürchte."},"reference":{"tr":"Mezmur 130:3-4","en":"Psalm 130:3-4","es":"Salmo 130:3-4","pt":"Salmo 130:3-4","fr":"Psaume 130:3-4","de":"Psalm 130:3-4"}},{"theme":"peace","text":{"tr":"Yeşua kalkıp rüzgârı azarladı ve denize, “Sus! Sakin ol!” dedi. Rüzgâr durdu ve büyük bir sakinlik oldu.","en":"He awoke, and rebuked the wind, and said to the sea, “Peace! Be still!” The wind ceased, and there was a great calm.","es":"Y levantándose, increpó al viento, y dijo á la mar: Calla, enmudece. Y cesó el viento, y fué hecha grande bonanza.","pt":"E ele, levantando-se, repreendeu o vento, e disse ao mar: Cala-te, aquieta-te. E cessou o vento, e fez-se grande bonança.","fr":"Mais lui, étant réveillé, parla avec autorité aux vents, et il dit à la mer: Tais-toi, sois tranquille. Et le vent cessa, et il se fit un grand calme.","de":"Und er stand auf und bedrohte den Wind und sprach zu dem Meer: Schweig und verstumme! Und der Wind legte sich, und es ward eine große Stille."},"reference":{"tr":"Markos 4:39","en":"Mark 4:39","es":"Marcos 4:39","pt":"Marcos 4:39","fr":"Marc 4:39","de":"Markus 4:39"}},{"theme":"strength","text":{"tr":"İşte, Tanrı benim kurtuluşumdur. Güveneceğim ve korkmayacağım; çünkü Yah, Yahve benim gücüm ve ezgimdir; O benim kurtuluşum oldu.”","en":"Behold, God is my salvation. I will trust, and will not be afraid; for Yah, Yahweh, is my strength and song; and he has become my salvation.”","es":"He aquí Dios es salud mía; aseguraréme, y no temeré; porque mi fortaleza y mi canción es JAH Jehová, el cual ha sido salud para mí.","pt":"Eis que Deus é a minha salvação; eu confiarei e não temerei porque o Senhor, sim o Senhor é a minha força e o meu cântico; e se tornou a minha salvação.","fr":"Voici, Dieu est mon salut; j'aurai confiance, et je ne craindrai point. Car l'Éternel, l'Éternel est ma force et ma louange, et il a été mon Sauveur!","de":"Siehe, Gott ist mein Heil, ich bin sicher und fürchte mich nicht; denn Gott der HERR ist meine Stärke und mein Psalm und ist mein Heil."},"reference":{"tr":"Yeşaya 12:2","en":"Isaiah 12:2","es":"Isaías 12:2","pt":"Isaías 12:2","fr":"Ésaïe 12:2","de":"Jesaja 12:2"}},{"theme":"trust","text":{"tr":"İşlerini Yahve'ye teslim et, o zaman tasarıların başarıya ulaşır.","en":"Commit your deeds to Yahweh, and your plans shall succeed.","es":"Encomienda á Jehová tus obras, y tus pensamientos serán afirmados.","pt":"Entrega ao Senhor as tuas obras, e teus desígnios serão estabelecidos.","fr":"Remets tes affaires à l'Éternel, et tes desseins seront affermis.","de":"Befiehl dem HERRN deine Werke, so werden deine Anschläge fortgehen."},"reference":{"tr":"Süleyman’ın Özdeyişleri 16:3","en":"Proverbs 16:3","es":"Proverbios 16:3","pt":"Provérbios 16:3","fr":"Proverbes 16:3","de":"Sprüche 16:3"}},{"theme":"rest","text":{"tr":"“Keşke güvercin gibi kanatlarım olsaydı!” dedim. Uçup gider, rahatlardım.","en":"I said, “Oh that I had wings like a dove! Then I would fly away, and be at rest.","es":"Y dije: ¡Quién me diese alas como de paloma! volaría yo, y descansaría.","pt":"Pelo que eu disse: Ah! quem me dera asas como de pomba! então voaria, e encontraria descanso.","fr":"La crainte et le tremblement viennent sur moi; l'effroi m'enveloppe.","de":"Furcht und Zittern ist mich angekommen, und Grauen hat mich überfallen."},"reference":{"tr":"Mezmur 55:6","en":"Psalm 55:6","es":"Salmo 55:6","pt":"Salmo 55:6","fr":"Psaume 55:6","de":"Psalm 55:6"}},{"theme":"hope","text":{"tr":"Emniyette olacaksın, çünkü umut var. Evet, araştıracaksın ve güven içinde dinleneceksin.","en":"You shall be secure, because there is hope. Yes, you shall search, and shall take your rest in safety.","es":"Y confiarás, que habrá esperanza; y cavarás, y dormirás seguro:","pt":"E terás confiança, porque haverá esperança; olharás ao redor de ti e repousarás seguro.","fr":"Tu seras plein de confiance, parce que tu auras lieu d'espérer; tu exploreras autour de toi, et tu te coucheras en sécurité;","de":"und dürftest dich dessen trösten, daß Hoffnung da sei; würdest dich umsehen und in Sicherheit schlafen legen;"},"reference":{"tr":"Eyüp 11:18","en":"Job 11:18","es":"Job 11:18","pt":"Jó 11:18","fr":"Job 11:18","de":"Hiob 11:18"}},{"theme":"anxiety","text":{"tr":"Yüreği korkak olanlara şunu söyleyin: “Güçlü ol! Korkma! İşte, sizin Tanrınız öç almak için, Tanrı'nın misillemesiyle gelecek. O gelip sizi kurtaracak.","en":"Tell those who have a fearful heart, “Be strong. Don’t be afraid. Behold, your God will come with vengeance, God’s retribution. He will come and save you.","es":"Decid á los de corazón apocado: Confortaos, no temáis: he aquí que vuestro Dios viene con venganza, con pago; el mismo Dios vendrá, y os salvará.","pt":"Dizei aos turbados de coração: Sede fortes, não temais; eis o vosso Deus! com vingança virá, sim com a recompensa de Deus; ele virá, e vos salvará.","fr":"Dites à ceux qui ont le cœur troublé: Prenez courage et ne craignez plus! voici votre Dieu! La vengeance viendra, la rétribution de Dieu. Il viendra lui-même, et vous délivrera.","de":"Saget den verzagten Herzen: Seid getrost, fürchtet euch nicht! Sehet, euer Gott, der kommt zur Rache; Gott, der da vergilt, kommt und wird euch helfen."},"reference":{"tr":"Yeşaya 35:4","en":"Isaiah 35:4","es":"Isaías 35:4","pt":"Isaías 35:4","fr":"Ésaïe 35:4","de":"Jesaja 35:4"}},{"theme":"guidance","text":{"tr":"'Beni çağır da sana yanıt vereyim, bilmediğin büyük ve zor şeyleri sana göstereyim.'","en":"‘Call to me, and I will answer you, and will show you great and difficult things, which you don’t know.’","es":"Clama á mí, y te responderé, y te enseñaré cosas grandes y dificultosas que tú no sabes.","pt":"Clama a mim, e responder-te-ei, e anunciar-te-ei coisas grandes e ocultas, que não sabes.","fr":"Crie vers moi, et je te répondrai, et je te déclarerai des choses grandes et cachées que tu ne connais pas.","de":"Rufe mich an, so will ich dir antworten und will dir anzeigen große und gewaltige Dinge, die du nicht weißt."},"reference":{"tr":"Yeremya 33:3","en":"Jeremiah 33:3","es":"Jeremías 33:3","pt":"Jeremias 33:3","fr":"Jérémie 33:3","de":"Jeremia 33:3"}},{"theme":"joy","text":{"tr":"Ama sana sığınanların hepsi sevinsinler. Her zaman sevinç çığlıkları atsınlar, çünkü onları savunan sensin. Adını sevenler de sende sevinçle coşsunlar.","en":"But let all those who take refuge in you rejoice, Let them always shout for joy, because you defend them. Let them also who love your name be joyful in you.","es":"Y alegrarse han todos los que en ti confían; para siempre darán voces de júbilo, porque tú los defiendes: y en ti se regocijarán los que aman tu nombre.","pt":"Mas alegrem-se todos os que confiam em ti; exultem eternamente, porquanto tu os defendes; sim, gloriem-se em ti os que amam o teu nome.","fr":"Condamne-les, ô Dieu! Qu'ils échouent dans leurs desseins; renverse-les à cause de la multitude de leurs crimes; car ils se sont révoltés contre toi.","de":"Sprich sie schuldig, Gott, daß sie fallen von ihrem Vornehmen. Stoße sie aus um ihrer großen Übertretungen willen; denn sie sind widerspenstig."},"reference":{"tr":"Mezmur 5:11","en":"Psalm 5:11","es":"Salmo 5:11","pt":"Salmo 5:11","fr":"Psaume 5:11","de":"Psalm 5:11"}},{"theme":"love","text":{"tr":"Mesih’le birlikte çarmıha gerildim. Artık ben yaşamıyorum, Mesih bende yaşıyor. Şimdi bedende yaşadığım bu hayatı, beni seven ve benim için kendini feda eden Tanrı Oğlu’ndaki imanla yaşıyorum.","en":"I have been crucified with Christ, and it is no longer I that live, but Christ lives in me. That life which I now live in the flesh, I live by faith in the Son of God, who loved me, and gave himself up for me.","es":"Con Cristo estoy juntamente crucificado, y vivo, no ya yo, mas vive Cristo en mí: y lo que ahora vivo en la carne, lo vivo en la fe del Hijo de Dios, el cual me amó, y se entregó á sí mismo por mí.","pt":"Já estou crucificado com Cristo; e vivo, não mais eu, mas Cristo vive em mim; e a vida que agora vivo na carne, vivo-a na fé no filho de Deus, o qual me amou, e se entregou a si mesmo por mim.","fr":"Je suis crucifié avec Christ, et si je vis, ce n'est plus moi, mais c'est Christ qui vit en moi; et si je vis encore dans la chair, je vis dans la foi au Fils de Dieu qui m'a aimé, et qui s'est donné lui-même pour moi.","de":"Ich lebe aber; doch nun nicht ich, sondern Christus lebt in mir. Denn was ich jetzt lebe im Fleisch, das lebe ich in dem Glauben des Sohnes Gottes, der mich geliebt hat und sich selbst für mich dargegeben."},"reference":{"tr":"Galatyalılar 2:20","en":"Galatians 2:20","es":"Gálatas 2:20","pt":"Gálatas 2:20","fr":"Galates 2:20","de":"Galater 2:20"}},{"theme":"gratitude","text":{"tr":"Müzik şefi için - “Yok Etme” makamında - Asaf’ın mezmuru - İlahi Sana şükrederiz ey Tanrı. Şükrederiz, çünkü adın yakındır. İnsanlar senin şaşılası işlerini anlatırlar.","en":"We give thanks to you, God. We give thanks, for your Name is near. Men tell about your wondrous works.","es":"Al Músico principal: sobre No destruyas: Salmo de Asaph: Cántico. ALABARÉMOSTE, oh Dios, alabaremos; que cercano está tu nombre: cuenten tus maravillas.","pt":"Damos-te graças, ó Deus, damos-te graças, pois o teu nome está perto; os que invocam o teu nome anunciam as tuas maravilhas.","fr":"Au maître-chantre. Al-Thasheth (ne détruis pas). Psaume. Cantique d'Asaph.","de":"Ein Psalm und Lied Asaphs, daß er nicht umkäme, vorzusingen."},"reference":{"tr":"Mezmur 75:1","en":"Psalm 75:1","es":"Salmo 75:1","pt":"Salmo 75:1","fr":"Psaume 75:1","de":"Psalm 75:1"}},{"theme":"comfort","text":{"tr":"Sulardan geçtiğinde ben seninle olacağım, ırmakların içinden geçerken senin üzerine taşmayacak. Ateşin içinden yürürken yanmayacaksın, alev de seni yakmayacak.","en":"When you pass through the waters, I will be with you; and through the rivers, they will not overflow you. When you walk through the fire, you will not be burned, and flame will not scorch you.","es":"Cuando pasares por las aguas, yo seré contigo; y por los ríos, no te anegarán. Cuando pasares por el fuego, no te quemarás, ni la llama arderá en ti.","pt":"Quando passares pelas águas, eu serei contigo; quando pelos rios, eles não te submergirão; quando passares pelo fogo, não te queimarás, nem a chama arderá em ti.","fr":"Quand tu traverseras les eaux, je serai avec toi; et les fleuves, ils ne te submergeront point. Quand tu passeras par le feu, tu n'en seras pas brûlé, et la flamme ne te consumera pas.","de":"Denn so du durch Wasser gehst, will ich bei dir sein, daß dich die Ströme nicht sollen ersäufen; und so du ins Feuer gehst, sollst du nicht brennen, und die Flamme soll dich nicht versengen."},"reference":{"tr":"Yeşaya 43:2","en":"Isaiah 43:2","es":"Isaías 43:2","pt":"Isaías 43:2","fr":"Ésaïe 43:2","de":"Jesaja 43:2"}},{"theme":"faith","text":{"tr":"Öyle ki, imanınız insan bilgeliğine değil, Tanrı’nın gücüne dayansın.","en":"that your faith wouldn’t stand in the wisdom of men, but in the power of God.","es":"Para que vuestra fe no esté fundada en sabiduría de hombres, mas en poder de Dios.","pt":"para que a vossa fé não se apoiasse na sabedoria dos homens, mas no poder de Deus.","fr":"Afin que votre foi fût fondée, non sur la sagesse des hommes, mais sur la puissance de Dieu.","de":"auf daß euer Glaube bestehe nicht auf Menschenweisheit, sondern auf Gottes Kraft."},"reference":{"tr":"1. Korintliler 2:5","en":"1 Corinthians 2:5","es":"1 Corintios 2:5","pt":"1 Coríntios 2:5","fr":"1 Corinthiens 2:5","de":"1. Korinther 2:5"}},{"theme":"forgiveness","text":{"tr":"Günahlar beni bunalttı, ama Sen suçlarımızın kefaretini ödedin.","en":"Sins overwhelmed me, but you atoned for our transgressions.","es":"Palabras de iniquidades me sobrepujaron: mas nuestras rebeliones tú las perdonarás.","pt":"Prevalecem as iniqüidades contra mim; mas as nossas transgressões, tu as perdoarás.","fr":"O toi qui entends la prière, toute créature viendra jusqu'à toi.","de":"Du erhörst Gebet; darum kommt alles Fleisch zu dir."},"reference":{"tr":"Mezmur 65:3","en":"Psalm 65:3","es":"Salmo 65:3","pt":"Salmo 65:3","fr":"Psaume 65:3","de":"Psalm 65:3"}},{"theme":"peace","text":{"tr":"Bu nedenle imanla aklandığımıza göre, Efendimiz Yeşua Mesih aracılığıyla Tanrı’yla barış içindeyiz.","en":"Being therefore justified by faith, we have peace with God through our Lord Jesus Christ;","es":"JUSTIFICADOS pues por la fe, tenemos paz para con Dios por medio de nuestro Señor Jesucristo:","pt":"Justificados, pois, pela fé, tenhamos paz com Deus, por nosso Senhor Jesus Cristo,","fr":"Etant donc justifiés par la foi, nous avons la paix avec Dieu, par notre Seigneur Jésus-Christ,","de":"Nun wir denn sind gerecht geworden durch den Glauben, so haben wir Frieden mit Gott durch unsern HERRN Jesus Christus,"},"reference":{"tr":"Romalılar 5:1","en":"Romans 5:1","es":"Romanos 5:1","pt":"Romanos 5:1","fr":"Romains 5:1","de":"Römer 5:1"}},{"theme":"strength","text":{"tr":"Çağırdığım gün bana yanıt verdin. Canımdaki güçle beni cesaretlendirdin.","en":"In the day that I called, you answered me. You encouraged me with strength in my soul.","es":"En el día que clamé, me respondiste; esforzásteme con fortaleza en mi alma.","pt":"No dia em que eu clamei, atendeste-me; alentaste-me, fortalecendo a minha alma.","fr":"Le jour que je t'ai invoqué, tu m'as exaucé; tu m'as délivré, tu as fortifié mon âme.","de":"Wenn ich dich anrufe, so erhörst du mich und gibst meiner Seele große Kraft."},"reference":{"tr":"Mezmur 138:3","en":"Psalm 138:3","es":"Salmo 138:3","pt":"Salmo 138:3","fr":"Psaume 138:3","de":"Psalm 138:3"}},{"theme":"trust","text":{"tr":"Çok keder gelir kötülerin başına, ama güveni Yahve olanı sevgi dolu iyilik kuşatacaktır.","en":"Many sorrows come to the wicked, but loving kindness shall surround him who trusts in Yahweh.","es":"Muchos dolores para el impío; mas el que espera en Jehová, lo cercará misericordia.","pt":"O ímpio tem muitas dores, mas aquele que confia no Senhor, a misericórdia o cerca.","fr":"Beaucoup de douleurs atteindront le méchant; mais la grâce environnera celui qui se confie en l'Éternel.","de":"Der Gottlose hat viel Plage; wer aber auf den HERRN hofft, den wird die Güte umfangen."},"reference":{"tr":"Mezmur 32:10","en":"Psalm 32:10","es":"Salmo 32:10","pt":"Salmo 32:10","fr":"Psaume 32:10","de":"Psalm 32:10"}},{"theme":"rest","text":{"tr":"Yahve şöyle diyor, “Yollarda durup bakın ve eski yolları sorun, ‘İyi yol nerede?’ ve onda yürüyün, böylece canlarınız için rahat bulacaksınız. Ama onlar dediler ki, 'Biz onda yürümeyeceğiz.'","en":"Yahweh says, “Stand in the ways and see, and ask for the old paths, ‘Where is the good way?’ and walk in it, and you will find rest for your souls. But they said, ‘We will not walk in it.’","es":"Así dijo Jehová: Paraos en los caminos, y mirad, y preguntad por las sendas antiguas, cuál sea el buen camino, y andad por él, y hallaréis descanso para vuestra alma. Mas dijeron: No andaremos.","pt":"Assim diz o Senhor: Ponde-vos nos caminhos, e vede, e perguntai pelas veredas antigas, qual é o bom caminho, e andai por ele; e achareis descanso para as vossas almas. Mas eles disseram: Não andaremos nele.","fr":"Ainsi a dit l'Éternel: Tenez-vous sur les chemins, et regardez, et enquérez-vous des sentiers d'autrefois, quel est le bon chemin; et marchez-y, et vous trouverez le repos de vos âmes! Et ils répondent: Nous n'y marcherons point.","de":"So spricht der HERR: Tretet auf die Wege und schauet und fraget nach den vorigen Wegen, welches der gute Weg sei, und wandelt darin, so werdet ihr Ruhe finden für eure Seele! Aber sie sprechen: Wir wollen's nicht tun!"},"reference":{"tr":"Yeremya 6:16","en":"Jeremiah 6:16","es":"Jeremías 6:16","pt":"Jeremias 6:16","fr":"Jérémie 6:16","de":"Jeremia 6:16"}},{"theme":"hope","text":{"tr":"Ey canım, sessizce yalnız Tanrı’yı bekle, çünkü umudum O’ndandır.","en":"My soul, wait in silence for God alone, for my expectation is from him.","es":"Alma mía, en Dios solamente reposa; porque de él es mi esperanza.","pt":"Ó minha alma, espera silenciosa somente em Deus, porque dele vem a minha esperança.","fr":"Ils ne font que consulter pour le faire tomber de son élévation; ils se plaisent au mensonge; de leur bouche ils bénissent, mais dans leur cœur ils maudissent. (Sélah.)","de":"Sie denken nur, wie sie ihn dämpfen, fleißigen sich der Lüge; geben gute Worte, aber im Herzen fluchen sie. (Sela.)"},"reference":{"tr":"Mezmur 62:5","en":"Psalm 62:5","es":"Salmo 62:5","pt":"Salmo 62:5","fr":"Psaume 62:5","de":"Psalm 62:5"}},{"theme":"anxiety","text":{"tr":"Ölüm gölgesindeki vadiden geçsem bile, kötülükten hiç korkmam, çünkü sen benimlesin. Senin asan, değneğin, onlar rahatlatır beni.","en":"Even though I walk through the valley of the shadow of death, I will fear no evil, for you are with me. Your rod and your staff, they comfort me.","es":"Aunque ande en valle de sombra de muerte, no temeré mal alguno; porque tú estarás conmigo: tu vara y tu cayado me infundirán aliento.","pt":"Ainda que eu ande pelo vale da sombra da morte, não temerei mal algum, porque tu estás comigo; a tua vara e o teu cajado me consolam.","fr":"Même quand je marcherais dans la vallée de l'ombre de la mort, je ne craindrais aucun mal; car tu es avec moi; c'est ton bâton et ta houlette qui me consolent.","de":"Und ob ich schon wanderte im finstern Tal, fürchte ich kein Unglück; denn du bist bei mir, dein Stecken und dein Stab trösten mich."},"reference":{"tr":"Mezmur 23:4","en":"Psalm 23:4","es":"Salmo 23:4","pt":"Salmo 23:4","fr":"Psaume 23:4","de":"Psalm 23:4"}},{"theme":"guidance","text":{"tr":"Alçakgönüllülere adalet yolunda yol gösterecek. Kendi yolunu onlara öğretecek.","en":"He will guide the humble in justice. He will teach the humble his way.","es":"Encaminará á los humildes por el juicio, y enseñará á los mansos su carrera.","pt":"Guia os mansos no que é reto, e lhes ensina o seu caminho.","fr":"Il fera marcher les humbles dans la justice; il enseignera sa voie aux humbles.","de":"Er leitet die Elenden recht und lehrt die Elenden seinen Weg."},"reference":{"tr":"Mezmur 25:9","en":"Psalm 25:9","es":"Salmo 25:9","pt":"Salmo 25:9","fr":"Psaume 25:9","de":"Psalm 25:9"}},{"theme":"joy","text":{"tr":"Ama şimdi sana geliyorum ve sevincim onlarda tamamlansın diye bunları dünyadayken söylüyorum.","en":"But now I come to you, and I say these things in the world, that they may have my joy made full in themselves.","es":"Mas ahora vengo á ti; y hablo esto en el mundo, para que tengan mi gozo cumplido en sí mismos.","pt":"Mas agora vou para ti; e isto falo no mundo, para que eles tenham a minha alegria completa em si mesmos.","fr":"Et maintenant je vais à toi, et je dis ces choses dans le monde, afin qu'ils aient ma joie accomplie en eux.","de":"Nun aber komme ich zu dir und rede solches in der Welt, auf daß sie in ihnen haben meine Freude vollkommen."},"reference":{"tr":"Yuhanna 17:13","en":"John 17:13","es":"Juan 17:13","pt":"João 17:13","fr":"Jean 17:13","de":"Johannes 17:13"}},{"theme":"love","text":{"tr":"Sevgi dolu iyiliğin ne değerli, ey Tanrı! İnsanoğulları kanatlarının gölgesine sığınır.","en":"How precious is your loving kindness, God! The children of men take refuge under the shadow of your wings.","es":"¡Cuán ilustre, oh Dios, es tu misericordia! Por eso los hijos de los hombres se amparan bajo la sombra de tus alas.","pt":"Quão preciosa é, ó Deus, a tua benignidade! Os filhos dos homens se refugiam à sombra das tuas asas.","fr":"Ta justice est comme les montagnes de Dieu; tes jugements sont un grand abîme. Éternel, tu conserves les hommes et les bêtes.","de":"Deine Gerechtigkeit steht wie die Berge Gottes und dein Recht wie eine große Tiefe. HERR, du hilfst Menschen und Vieh."},"reference":{"tr":"Mezmur 36:7","en":"Psalm 36:7","es":"Salmo 36:7","pt":"Salmo 36:7","fr":"Psaume 36:7","de":"Psalm 36:7"}},{"theme":"gratitude","text":{"tr":"Yah’ı övün! Doğruların meclisinde ve topluluk içinde bütün yüreğimle Yahve’ye şükürler sunacağım,","en":"Praise Yah! I will give thanks to Yahweh with my whole heart, in the council of the upright, and in the congregation.","es":"Aleluya. ALABARÉ á Jehová con todo el corazón, en la compañía y congregación de los rectos.","pt":"Louvai ao Senhor. De todo o coração darei graças ao Senhor, no concílio dos retos e na congregação.","fr":"Louez l'Éternel! Je célébrerai l'Éternel de tout mon cœur, dans le conseil des justes, et dans l'assemblée.","de":"Halleluja! Ich danke dem HERRN von ganzem Herzen im Rat der Frommen und in der Gemeinde."},"reference":{"tr":"Mezmur 111:1","en":"Psalm 111:1","es":"Salmo 111:1","pt":"Salmo 111:1","fr":"Psaume 111:1","de":"Psalm 111:1"}},{"theme":"comfort","text":{"tr":"Sıkıntının ortasında yürüsem bile, sen beni canlandırırsın. Düşmanlarımın gazabına karşı elini uzatırsın. Sağ elin beni kurtaracak.","en":"Though I walk in the middle of trouble, you will revive me. You will stretch out your hand against the wrath of my enemies. Your right hand will save me.","es":"Si anduviere yo en medio de la angustia, tú me vivificarás: contra la ira de mis enemigos extenderás tu mano, y salvaráme tu diestra.","pt":"Embora eu ande no meio da angústia, tu me revivificas; contra a ira dos meus inimigos estendes a tua mão, e a tua destra me salva.","fr":"Si je marche au milieu de l'adversité, tu me rendras la vie; tu étendras ta main contre la colère de mes ennemis, et ta droite me délivrera.","de":"Wenn ich mitten in der Angst wandle, so erquickst du mich und streckst deine Hand über den Zorn meiner Feinde und hilfst mir mit deiner Rechten."},"reference":{"tr":"Mezmur 138:7","en":"Psalm 138:7","es":"Salmo 138:7","pt":"Salmo 138:7","fr":"Psaume 138:7","de":"Psalm 138:7"}},{"theme":"faith","text":{"tr":"Biz sizin imanınızı denetlemiyoruz, sevinciniz için sizinle birlikte çalışıyoruz. Çünkü imanda sağlam duruyorsunuz.","en":"Not that we control your faith, but are fellow workers with you for your joy. For you stand firm in faith.","es":"No que nos enseñoreemos de vuestra fe, mas somos ayudadores de vuestro gozo: porque por la fe estáis firmes.","pt":"não que tenhamos domínio sobre a vossa fé, mas somos cooperadores de vosso gozo; pois pela fé estais firmados.","fr":"Non que nous dominions sur votre foi, mais nous contribuons à votre joie, puisque c'est par la foi que vous demeurez fermes.","de":"Nicht daß wir Herren seien über euren Glauben, sondern wir sind Gehilfen eurer Freude; denn ihr stehet im Glauben."},"reference":{"tr":"2. Korintliler 1:24","en":"2 Corinthians 1:24","es":"2 Corintios 1:24","pt":"2 Coríntios 1:24","fr":"2 Corinthiens 1:24","de":"2. Korinther 1:24"}},{"theme":"forgiveness","text":{"tr":"O’nda kurtuluşa, günahlarımızın bağışına sahibiz.","en":"in whom we have our redemption, the forgiveness of our sins;","es":"En el cual tenemos redención por su sangre, la remisión de pecados:","pt":"em quem temos a redenção, a saber, a remissão dos pecados;","fr":"En qui nous avons la rédemption par son sang, la rémission des péchés.","de":"an welchem wir haben die Erlösung durch sein Blut, die Vergebung der Sünden;"},"reference":{"tr":"Koloseliler 1:14","en":"Colossians 1:14","es":"Colosenses 1:14","pt":"Colossenses 1:14","fr":"Colossiens 1:14","de":"Kolosser 1:14"}},{"theme":"peace","text":{"tr":"Çünkü O bizim esenliğimizdir. Yasa’yı, buyrukları ve kurallarıyla birlikte ortadan kaldırarak ikisini birleştirdi. Aradaki ayrılık duvarını, düşmanlığı kendi bedeninde yıktı. Öyle ki, kendisinde ikisinden yeni bir insan yaratsın ve esenliği sağlasın, düşmanlığı çarmıhla öldürsün ve çarmıh aracılığıyla bir bedende ikisini Tanrı’yla barıştırsın.","en":"For he is our peace, who made both one, and broke down the middle wall of partition,","es":"Porque él es nuestra paz, que de ambos hizo uno, derribando la pared intermedia de separación;","pt":"Porque ele é a nossa paz, o qual de ambos os povos fez um; e, derrubando a parede de separação que estava no meio, na sua carne desfez a inimizade,","fr":"Car c'est lui qui est notre paix, lui qui des deux peuples n'en a fait qu'un, en abattant le mur de séparation;","de":"Denn er ist unser Friede, der aus beiden eines hat gemacht und hat abgebrochen den Zaun, der dazwischen war, indem er durch sein Fleisch wegnahm die Feindschaft,"},"reference":{"tr":"Efesliler 2:14","en":"Ephesians 2:14","es":"Efesios 2:14","pt":"Efésios 2:14","fr":"Éphésiens 2:14","de":"Epheser 2:14"}},{"theme":"strength","text":{"tr":"Her şeye sevinçle dayanıp sabredebilmeniz için O’nun yüceliğinin gücüne göre, tam kudretle güçlenmenizi diliyoruz.","en":"strengthened with all power, according to the might of his glory, for all endurance and perseverance with joy;","es":"Corroborados de toda fortaleza, conforme á la potencia de su gloria, para toda tolerancia y largura de ánimo con gozo;","pt":"corroborados com toda a fortaleza, segundo o poder da sua glória, para toda a perseverança e longanimidade com gozo;","fr":"Fortifiés en toute manière selon sa puissance glorieuse, pour avoir toute patience, et constance avec joie;","de":"und wachset in der Erkenntnis Gottes und gestärkt werdet mit aller Kraft nach seiner herrlichen Macht zu aller Geduld und Langmütigkeit mit Freuden,"},"reference":{"tr":"Koloseliler 1:11","en":"Colossians 1:11","es":"Colosenses 1:11","pt":"Colossenses 1:11","fr":"Colossiens 1:11","de":"Kolosser 1:11"}},{"theme":"trust","text":{"tr":"“Yüreğiniz sıkılmasın, Tanrı’ya iman edin. Bana da iman edin.","en":"“Don’t let your heart be troubled. Believe in God. Believe also in me.","es":"NO se turbe vuestro corazón: creéis en Dios, creed también en mí.","pt":"Não se turbe o vosso coração; credes em Deus, crede também em mim.","fr":"Que votre cœur ne se trouble point; croyez en Dieu, croyez aussi en moi.","de":"Und er sprach zu seinen Jüngern: Euer Herz erschrecke nicht! Glaubet an Gott und glaubet an mich!"},"reference":{"tr":"Yuhanna 14:1","en":"John 14:1","es":"Juan 14:1","pt":"João 14:1","fr":"Jean 14:1","de":"Johannes 14:1"}},{"theme":"hope","text":{"tr":"Ey siz umut tutsakları, kaleye dönün! Tam bugün size iki katını geri vereceğimi ilan ediyorum.","en":"Turn to the stronghold, you prisoners of hope! Even today I declare that I will restore double to you.","es":"Tornaos á la fortaleza, oh presos de esperanza: hoy también os anuncio que os daré doblado.","pt":"Voltai à fortaleza, ó presos de esperança; também hoje anuncio que te recompensarei em dobro.","fr":"Retournez au lieu fort, captifs qui avez espérance! Aujourd'hui même je le déclare, je te rendrai deux fois autant","de":"So kehrt euch nun zu der Festung, ihr, die ihr auf Hoffnung gefangen liegt; denn auch heute verkündige ich, daß ich dir Zwiefältiges vergelten will."},"reference":{"tr":"Zekeriya 9:12","en":"Zechariah 9:12","es":"Zacarías 9:12","pt":"Zacarias 9:12","fr":"Zacharie 9:12","de":"Sacharja 9:12"}},{"theme":"guidance","text":{"tr":"Bana yaşam yolunu göstereceksin. Bol sevinç senin huzurundadır. Sağ elinde sonsuz zevkler vardır.","en":"You will show me the path of life. In your presence is fullness of joy. In your right hand there are pleasures forever more.","es":"Me mostrarás la senda de la vida: hartura de alegrías hay con tu rostro; deleites en tu diestra para siempre.","pt":"Tu me farás conhecer a vereda da vida; na tua presença há plenitude de alegria; à tua mão direita há delícias perpetuamente.","fr":"Tu me feras connaître le chemin de la vie; il y a un rassasiement de joie devant ta face, et des délices à ta droite pour jamais.","de":"Du tust mir kund den Weg zum Leben; vor dir ist Freude die Fülle und liebliches Wesen zu deiner Rechten ewiglich."},"reference":{"tr":"Mezmur 16:11","en":"Psalm 16:11","es":"Salmo 16:11","pt":"Salmo 16:11","fr":"Psaume 16:11","de":"Psalm 16:11"}},{"theme":"joy","text":{"tr":"Yaşam yollarını bana bildirdin. Varlığınla beni sevinçle dolduracaksın.’","en":"You made known to me the ways of life. You will make me full of gladness with your presence.’","es":"Hicísteme notorios los caminos de la vida; me henchirás de gozo con tu presencia.","pt":"fizeste-me conhecer os caminhos da vida; encher-me-ás de alegria na tua presença.","fr":"Tu m'as fait connaître le chemin de la vie; tu me rempliras de joie devant ta face.","de":"Du hast mir kundgetan die Wege des Lebens; du wirst mich erfüllen mit Freuden vor deinem Angesicht.\""},"reference":{"tr":"Elçilerin İşleri 2:28","en":"Acts 2:28","es":"Hechos 2:28","pt":"Atos 2:28","fr":"Actes 2:28","de":"Apostelgeschichte 2:28"}},{"theme":"love","text":{"tr":"Tanrın Efendi’ni bütün yüreğinle, bütün canınla, bütün aklınla ve bütün gücünle seveceksin.’ İlk buyruk budur. İkincisi de bunun gibi: ‘Komşunu kendin gibi seveceksin.’ Bunlardan daha büyük bir buyruk yoktur.”","en":"you shall love the Lord your God with all your heart, and with all your soul, and with all your mind, and with all your strength.’ This is the first commandment. The second is like this, ‘You shall love your neighbor as yourself.’ There is no other commandment greater than these.”","es":"Amarás pues al Señor tu Dios de todo tu corazón, y de toda tu alma, y de toda tu mente, y de todas tus fuerzas; este es el principal mandamiento. Y el segundo es semejante á él: Amarás á tu prójimo como á ti mismo. No hay otro mandamiento mayor que éstos.","pt":"Amarás, pois, ao Senhor teu Deus de todo o teu coração, de toda a tua alma, de todo o teu entendimento e de todas as tuas forças. E o segundo é este: Amarás ao teu próximo como a ti mesmo. Não há outro mandamento maior do que esses.","fr":"Tu aimeras le Seigneur ton Dieu de tout ton cœur, de toute ton âme, de toute ta pensée, et de toute ta force. C'est là le premier commandement. Et voici le second qui lui est semblable: Tu aimeras ton prochain comme toi-même. Il n'y a point d'autre commandement plus grand que ceux-ci.","de":"und du sollst Gott, deinen HERRN, lieben von ganzem Herzen, von ganzer Seele, von ganzem Gemüte und von allen deinen Kräften.\" Das ist das vornehmste Gebot. Und das andere ist ihm gleich: \"Du sollst deinen Nächsten lieben wie dich selbst.\" Es ist kein anderes Gebot größer denn diese."},"reference":{"tr":"Markos 12:30-31","en":"Mark 12:30-31","es":"Marcos 12:30-31","pt":"Marcos 12:30-31","fr":"Marc 12:30-31","de":"Markus 12:30-31"}},{"theme":"comfort","text":{"tr":"Bununla birlikte, alçakgönüllüleri teselli eden Tanrı, Titus'un gelişiyle bizi teselli etti.","en":"Nevertheless, he who comforts the lowly, God, comforted us by the coming of Titus;","es":"Mas Dios, que consuela á los humildes, nos consoló con la venida de Tito:","pt":"Mas Deus, que consola os abatidos, nos consolou com a vinda de Tito;","fr":"Mais Dieu, qui console ceux qui sont abattus, nous a consolés par l'arrivée de Tite;","de":"Aber Gott, der die Geringen tröstet, der tröstete auch uns durch die Ankunft des Titus;"},"reference":{"tr":"2. Korintliler 7:6","en":"2 Corinthians 7:6","es":"2 Corintios 7:6","pt":"2 Coríntios 7:6","fr":"2 Corinthiens 7:6","de":"2. Korinther 7:6"}},{"theme":"faith","text":{"tr":"Gözümüzü imanımızı başlatan ve tamamlayan Yeşua’ya dikelim. O, önüne konan sevinç uğruna çarmıhın utancını hiçe sayarak katlandı ve Tanrı’nın tahtının sağında oturdu.","en":"looking to Jesus, the author and perfecter of faith, who for the joy that was set before him endured the cross, despising its shame, and has sat down at the right hand of the throne of God.","es":"Puestos los ojos en al autor y consumador de la fe, en Jesús; el cual, habiéndole sido propuesto gozo, sufrió la cruz, menospreciando la vergüenza, y sentóse á la diestra del trono de Dios.","pt":"fitando os olhos em Jesus, autor e consumador da nossa fé, o qual, pelo gozo que lhe está proposto, suportou a cruz, desprezando a ignomínia, e está assentado à direita do trono de Deus.","fr":"Regardant à Jésus, le chef et le consommateur de la foi, qui, méprisant l'ignominie, à cause de la joie qui lui était proposée, a souffert la croix, et s'est assis à la droite du trône de Dieu.","de":"und aufsehen auf Jesum, den Anfänger und Vollender des Glaubens; welcher, da er wohl hätte mögen Freude haben, erduldete das Kreuz und achtete der Schande nicht und hat sich gesetzt zur Rechten auf den Stuhl Gottes."},"reference":{"tr":"İbraniler 12:2","en":"Hebrews 12:2","es":"Hebreos 12:2","pt":"Hebreus 12:2","fr":"Hébreux 12:2","de":"Hebräer 12:2"}},{"theme":"forgiveness","text":{"tr":"ve itaat etmeyi reddettiler. Aralarında yaptığın harikaları hatırlamadılar, ancak boyunlarını sertleştirdiler ve isyanlarında kendi köleliklerine geri dönmek için bir önder atadılar. Ama sen bağışlamaya hazır, lütufkâr ve merhametli, geç öfkelenen, iyilik dolu sevgisi bol olan bir Tanrı'sın ve onları bırakmadın.","en":"and refused to obey. They weren’t mindful of your wonders that you did among them, but hardened their neck, and in their rebellion appointed a captain to return to their bondage. But you are a God ready to pardon, gracious and merciful, slow to anger, and abundant in loving kindness, and didn’t forsake them.","es":"Y no quisieron oir, ni se acordaron de tus maravillas que habías hecho con ellos; antes endurecieron su cerviz, y en su rebelión pensaron poner caudillo para volverse á su servidumbre. Tú empero, eres Dios de perdones, clemente y piadoso, tardo para la ira, y de mucha misericordia, que no los dejaste.","pt":"recusando ouvir-te e não se lembrando das tuas maravilhas, que fizeste no meio deles; antes endureceram a cerviz e, na sua rebeldia, levantaram um chefe, a fim de voltarem para sua servidão. Tu, porém, és um Deus pronto para perdoar, clemente e misericordioso, tardio em irar-te e grande em beneficência, e não os abandonaste.","fr":"Ils refusèrent d'écouter, et ne se souvinrent point des merveilles que tu avais faites en leur faveur, mais ils raidirent leur cou, et dans leur rébellion ils se donnèrent un chef, pour retourner dans leur servitude. Mais toi, qui es un Dieu qui pardonnes, miséricordieux, pitoyable, lent à la colère, et abondant en grâce, tu ne les abandonnas point.","de":"und weigerten sich zu hören und gedachten auch nicht an deine Wunder, die du an ihnen tatest; sondern sie wurden halsstarrig und warfen ihr Haupt auf, daß sie sich zurückwendeten zu Dienstbarkeit in ihrer Ungeduld. Aber du, mein Gott, vergabst und warst gnädig, barmherzig, geduldig und von großer Barmherzigkeit und verließest sie nicht."},"reference":{"tr":"Nehemya 9:17","en":"Nehemiah 9:17","es":"Nehemías 9:17","pt":"Neemias 9:17","fr":"Néhémie 9:17","de":"Nehemia 9:17"}},{"theme":"peace","text":{"tr":"Kusursuz adamın üzerine bir nişan koy, doğru adama bak, çünkü gelecek esenlik adamınındır.","en":"Mark the perfect man, and see the upright, for there is a future for the man of peace.","es":"Considera al íntegro, y mira al justo: que la postrimería de cada uno de ellos es paz.","pt":"Nota o homem íntegro, e considera o reto, porque há para o homem de paz um porvir feliz.","fr":"Observe l'homme intègre, et considère l'homme droit; car il y a un avenir pour l'homme de paix.","de":"Bleibe fromm und halte dich recht; denn solchem wird's zuletzt wohl gehen."},"reference":{"tr":"Mezmur 37:37","en":"Psalm 37:37","es":"Salmo 37:37","pt":"Salmo 37:37","fr":"Psaume 37:37","de":"Psalm 37:37"}},{"theme":"strength","text":{"tr":"Uyanık kalın! İmanda sağlam durun! Cesur ve güçlü olun!","en":"Watch! Stand firm in the faith! Be courageous! Be strong!","es":"Velad, estad firmes en la fe; portaos varonilmente, y esforzaos.","pt":"Vigiai, estai firmes na fé, portai-vos varonilmente, sede fortes.","fr":"Veillez, demeurez fermes dans la foi, agissez courageusement, fortifiez-vous;","de":"Wachet, stehet im Glauben, seid männlich und seid stark!"},"reference":{"tr":"1. Korintliler 16:13","en":"1 Corinthians 16:13","es":"1 Corintios 16:13","pt":"1 Coríntios 16:13","fr":"1 Corinthiens 16:13","de":"1. Korinther 16:13"}},{"theme":"trust","text":{"tr":"Sabahleyin sevgi dolu iyiliğini duyur, çünkü sana güveniyorum. Yürümem gereken yolu bana bildir, çünkü canımı sana kaldırıyorum.","en":"Cause me to hear your loving kindness in the morning, for I trust in you. Cause me to know the way in which I should walk, for I lift up my soul to you.","es":"Hazme oir por la mañana tu misericordia, porque en ti he confiado: hazme saber el camino por donde ande, porque á ti he alzado mi alma.","pt":"Faze-me ouvir da tua benignidade pela manhã, pois em ti confio; faze-me saber o caminho que devo seguir, porque a ti elevo a minha alma.","fr":"Fais-moi entendre dès le matin ta bonté, car je me suis confié en toi; fais-moi connaître le chemin où je dois marcher, car j'ai élevé mon âme à toi.","de":"Laß mich frühe hören deine Gnade; denn ich hoffe auf dich. Tue mir kund den Weg, darauf ich gehen soll; denn mich verlangt nach dir."},"reference":{"tr":"Mezmur 143:8","en":"Psalm 143:8","es":"Salmo 143:8","pt":"Salmo 143:8","fr":"Psaume 143:8","de":"Psalm 143:8"}},{"theme":"hope","text":{"tr":"Çünkü eminim ki, ne ölüm, ne yaşam, ne melekler, ne hükümdarlıklar, ne şimdiki, ne gelecek şeyler, ne güçler, ne yükseklik, ne derinlik, ne de yaratılmış başka bir şey bizi Efendimiz Mesih Yeşua’da olan Tanrı sevgisinden ayırmaya gücü yetecektir.","en":"For I am persuaded that neither death, nor life, nor angels, nor principalities, nor things present, nor things to come, nor powers, nor height, nor depth, nor any other created thing, will be able to separate us from God’s love, which is in Christ Jesus our Lord.","es":"Por lo cual estoy cierto que ni la muerte, ni la vida, ni ángeles, ni principados, ni potestades, ni lo presente, ni lo por venir, Ni lo alto, ni lo bajo, ni ninguna criatura nos podrá apartar del amor de Dios, que es en Cristo Jesús Señor nuestro.","pt":"Porque estou certo de que, nem a morte, nem a vida, nem anjos, nem principados, nem coisas presentes, nem futuras, nem potestades, nem a altura, nem a profundidade, nem qualquer outra criatura nos poderá separar do amor de Deus, que está em Cristo Jesus nosso Senhor.","fr":"Car je suis assuré que ni la mort, ni la vie, ni les anges, ni les principautés, ni les puissances, ni les choses présentes, ni les choses à venir, Ni la hauteur, ni la profondeur, ni aucune autre créature, ne pourra nous séparer de l'amour de Dieu manifesté en Jésus-Christ notre Seigneur.","de":"Denn ich bin gewiß, daß weder Tod noch Leben, weder Engel noch Fürstentümer noch Gewalten, weder Gegenwärtiges noch Zukünftiges, weder Hohes noch Tiefes noch keine andere Kreatur mag uns scheiden von der Liebe Gottes, die in Christo Jesu ist, unserm HERRN."},"reference":{"tr":"Romalılar 8:38-39","en":"Romans 8:38-39","es":"Romanos 8:38-39","pt":"Romanos 8:38-39","fr":"Romains 8:38-39","de":"Römer 8:38-39"}},{"theme":"guidance","text":{"tr":"Çünkü Yahve bilgelik verir. O'nun ağzından bilgi ve anlayış çıkar.","en":"For Yahweh gives wisdom. Out of his mouth comes knowledge and understanding.","es":"Porque Jehová da la sabiduría, y de su boca viene el conocimiento y la inteligencia.","pt":"Porque o Senhor dá a sabedoria; da sua boca procedem o conhecimento e o entendimento;","fr":"Car l'Éternel donne la sagesse; de sa bouche procèdent la connaissance et l'intelligence.","de":"Denn der HERR gibt Weisheit, und aus seinem Munde kommt Erkenntnis und Verstand."},"reference":{"tr":"Süleyman’ın Özdeyişleri 2:6","en":"Proverbs 2:6","es":"Proverbios 2:6","pt":"Provérbios 2:6","fr":"Proverbes 2:6","de":"Sprüche 2:6"}},{"theme":"joy","text":{"tr":"Dudaklarım sevinçle haykıracak! Kurtarmış olduğun canım seni ezgilerle övecek!","en":"My lips shall shout for joy! My soul, which you have redeemed, sings praises to you!","es":"Mis labios cantarán cuando á ti salmeare, y mi alma, á la cual redimiste.","pt":"Os meus lábios exultarão quando eu cantar os teus louvores, assim como a minha alma, que tu remiste.","fr":"Mes lèvres, et mon âme que tu as rachetée, chanteront de joie quand je te psalmodierai.","de":"Meine Lippen und meine Seele, die du erlöst hast, sind fröhlich und lobsingen dir."},"reference":{"tr":"Mezmur 71:23","en":"Psalm 71:23","es":"Salmo 71:23","pt":"Salmo 71:23","fr":"Psaume 71:23","de":"Psalm 71:23"}},{"theme":"love","text":{"tr":"Bu nedenle şunu bil ki, Tanrın Yahve Tanrı'nın kendisidir, kendisini seven ve buyruklarını tutan bin kuşak boyunca antlaşmasını ve sevgi dolu iyiliğini koruyan,","en":"Know therefore that Yahweh your God himself is God, the faithful God, who keeps covenant and loving kindness with them who love him and keep his commandments to a thousand generations,","es":"Conoce, pues, que Jehová tu Dios es Dios, Dios fiel, que guarda el pacto y la misericordia á los que le aman y guardan sus mandamientos, hasta las mil generaciones;","pt":"Saberás, pois, que o Senhor teu Deus é que é Deus, o Deus fiel, que guarda o pacto e a misericórdia, até mil gerações, aos que o amam e guardam os seus mandamentos;","fr":"Reconnais donc que c'est l'Éternel ton Dieu qui est Dieu, le Dieu fidèle, qui garde son alliance et sa miséricorde jusqu'à mille générations à ceux qui l'aiment et qui observent ses commandements,","de":"So sollst du nun wissen, daß der HERR, dein Gott, ein Gott ist, ein treuer Gott, der den Bund und die Barmherzigkeit hält denen, die ihn lieben und seine Gebote halten, in tausend Glieder,"},"reference":{"tr":"Yasa’nın Tekrarı 7:9","en":"Deuteronomy 7:9","es":"Deuteronomio 7:9","pt":"Deuteronômio 7:9","fr":"Deutéronome 7:9","de":"5. Mose 7:9"}},{"theme":"comfort","text":{"tr":"Yahve gündüz vakti sevgi dolu iyiliğini buyurur. Gece vakti O’nun ezgisi, yaşamımın Tanrısı’na dua benimledir.","en":"Yahweh will command his loving kindness in the daytime. In the night his song shall be with me: a prayer to the God of my life.","es":"De día mandará Jehová su misericordia, y de noche su canción será conmigo, y oración al Dios de mi vida.","pt":"Contudo, de dia o Senhor ordena a sua bondade, e de noite a sua canção está comigo, uma oração ao Deus da minha vida.","fr":"Un abîme appelle un autre abîme au bruit de tes torrents; toutes tes vagues, tous tes flots ont passé sur moi.","de":"Deine Fluten rauschen daher, daß hier eine Tiefe und da eine Tiefe brausen; alle deine Wasserwogen und Wellen gehen über mich."},"reference":{"tr":"Mezmur 42:8","en":"Psalm 42:8","es":"Salmo 42:8","pt":"Salmo 42:8","fr":"Psaume 42:8","de":"Psalm 42:8"}},{"theme":"faith","text":{"tr":"İmanın iyi mücadelesini ver. Çağrılmış olduğun sonsuz yaşama sımsıkı sarıl! Birçok tanık önünde yüce bildiriyi açıkça dile getirdin.","en":"Fight the good fight of faith. Take hold of the eternal life to which you were called, and you confessed the good confession in the sight of many witnesses.","es":"Pelea la buena batalla de la fe, echa mano de la vida eterna, á la cual asimismo eres llamado, habiendo hecho buena profesión delante de muchos testigos.","pt":"Peleja a boa peleja da fé, apodera-te da vida eterna, para a qual foste chamado, tendo já feito boa confissão diante de muitas testemunhas.","fr":"Combats le bon combat de la foi, saisis la vie éternelle, à laquelle tu as été appelé, et pour laquelle tu as fait une belle confession en présence de plusieurs témoins.","de":"kämpfe den guten Kampf des Glaubens; ergreife das ewige Leben, dazu du auch berufen bist und bekannt hast ein gutes Bekenntnis vor vielen Zeugen."},"reference":{"tr":"1. Timoteos 6:12","en":"1 Timothy 6:12","es":"1 Timoteo 6:12","pt":"1 Timóteo 6:12","fr":"1 Timothée 6:12","de":"1. Timotheus 6:12"}},{"theme":"forgiveness","text":{"tr":"Yeşua, “Baba, onları bağışla, çünkü ne yaptıklarını bilmiyorlar” dedi. Kura çekip O’nun giysilerini aralarında paylaştılar.","en":"Jesus said, “Father, forgive them, for they don’t know what they are doing.” Dividing his garments among them, they cast lots.","es":"Y Jesús decía: Padre, perdónalos, porque no saben lo que hacen. Y partiendo sus vestidos, echaron suertes.","pt":"Jesus, porém, dizia: Pai, perdoa-lhes; porque não sabem o que fazem. Então repartiram as vestes dele, deitando sortes sobre elas.","fr":"Mais Jésus disait: Père, pardonne-leur, car ils ne savent ce qu'ils font. Puis se partageant ses vêtements, ils les tirèrent au sort.","de":"Jesus aber sprach: Vater, vergib ihnen sie wissen nicht, was sie tun! Und sie teilten seine Kleider und warfen das Los darum."},"reference":{"tr":"Luka 23:34","en":"Luke 23:34","es":"San Lucas 23:34","pt":"Lucas 23:34","fr":"Luc 23:34","de":"Lukas 23:34"}},{"theme":"peace","text":{"tr":"Çünkü sevinçle çıkacak ve esenlikle götürüleceksiniz. Dağlar ve tepeler önünüzde ezgi söylemeye başlayacaklar; kırlardaki bütün ağaçlar da el çırpacaklar.","en":"For you shall go out with joy, and be led out with peace. The mountains and the hills will break out before you into singing; and all the trees of the fields will clap their hands.","es":"Porque con alegría saldréis, y con paz seréis vueltos; los montes y los collados levantarán canción delante de vosotros, y todos los árboles del campo darán palmadas de aplauso.","pt":"Pois com alegria saireis, e em paz sereis guiados; os montes e os outeiros romperão em cânticos diante de vós, e todas as árvores de campo baterão palmas.","fr":"Car vous sortirez avec joie, et vous serez conduits en paix; les montagnes et les collines éclateront en cris de joie devant vous, et tous les arbres des champs battront des mains.","de":"Denn ihr sollt in Freuden ausziehen und im Frieden geleitet werden. Berge und Hügel sollen vor euch her frohlocken mit Ruhm und alle Bäume auf dem Felde mit den Händen klatschen."},"reference":{"tr":"Yeşaya 55:12","en":"Isaiah 55:12","es":"Isaías 55:12","pt":"Isaías 55:12","fr":"Ésaïe 55:12","de":"Jesaja 55:12"}},{"theme":"strength","text":{"tr":"Ey sizler, Yahve’ye umut bağlayanlar, hepiniz, güçlü olun ve yüreğiniz cesaretli olsun.","en":"Be strong, and let your heart take courage, all you who hope in Yahweh.","es":"Esforzaos todos vosotros los que esperáis en Jehová, y tome vuestro corazón aliento.","pt":"Esforçai-vos, e fortaleça-se o vosso coração, vós todos os que esperais no Senhor.","fr":"Aimez l'Éternel, vous tous ses bien-aimés! L'Éternel garde les fidèles, mais il rend à celui qui agit avec orgueil tout ce qu'il a mérité.","de":"Liebet den HERRN, alle seine Heiligen! Die Gläubigen behütet der HERR und vergilt reichlich dem, der Hochmut übt."},"reference":{"tr":"Mezmur 31:24","en":"Psalm 31:24","es":"Salmo 31:24","pt":"Salmo 31:24","fr":"Psaume 31:24","de":"Psalm 31:24"}},{"theme":"trust","text":{"tr":"Yahve için derim: “O benim sığınağım ve kalemdir, Tanrım’dır, O’na güvenirim.”","en":"I will say of Yahweh, “He is my refuge and my fortress; my God, in whom I trust.”","es":"Diré yo á Jehová: Esperanza mía, y castillo mío; mi Dios, en él confiaré.","pt":"Direi do Senhor: Ele é o meu refúgio e a minha fortaleza, o meu Deus, em quem confio.","fr":"Je dis à l'Éternel: Mon refuge et ma forteresse! mon Dieu en qui je m'assure!","de":"der spricht zu dem HERRN: Meine Zuversicht und meine Burg, mein Gott, auf den ich hoffe."},"reference":{"tr":"Mezmur 91:2","en":"Psalm 91:2","es":"Salmo 91:2","pt":"Salmo 91:2","fr":"Psaume 91:2","de":"Psalm 91:2"}},{"theme":"hope","text":{"tr":"Şimdi ise, iman, umut ve sevgi—bu üçü kalıcıdır. Bunların en büyüğü sevgidir.","en":"But now faith, hope, and love remain—these three. The greatest of these is love.","es":"Y ahora permanecen la fe, la esperanza, y la caridad, estas tres: empero la mayor de ellas es la caridad.","pt":"Agora, pois, permanecem a fé, a esperança, o amor, estes três; mas o maior destes é o amor.","fr":"Maintenant donc, ces trois choses demeurent: la foi, l'espérance, la charité; mais la plus grande d'elles est la charité.","de":"Nun aber bleibt Glaube, Hoffnung, Liebe, diese drei; aber die Liebe ist die größte unter ihnen."},"reference":{"tr":"1. Korintliler 13:13","en":"1 Corinthians 13:13","es":"1 Corintios 13:13","pt":"1 Coríntios 13:13","fr":"1 Corinthiens 13:13","de":"1. Korinther 13:13"}},{"theme":"guidance","text":{"tr":"Bana kendi yolunu öğret, ey Yahve. Düşmanlarımdan ötürü bana doğru yolda rehber ol.","en":"Teach me your way, Yahweh. Lead me in a straight path, because of my enemies.","es":"Enséñame, oh Jehová, tu camino, y guíame por senda de rectitud, á causa de mis enemigos.","pt":"Ensina-me, ó Senhor, o teu caminho, e guia-me por uma vereda plana, por causa dos que me espreitam.","fr":"Éternel, enseigne-moi ta voie, et me conduis dans le droit chemin, à cause de mes ennemis.","de":"HERR, weise mir deinen Weg und leite mich auf richtiger Bahn um meiner Feinde willen."},"reference":{"tr":"Mezmur 27:11","en":"Psalm 27:11","es":"Salmo 27:11","pt":"Salmo 27:11","fr":"Psaume 27:11","de":"Psalm 27:11"}},{"theme":"joy","text":{"tr":"Ey bütün yeryüzü Yahve’ye sevinçle haykırın! Neşeyle ortalığı çınlatın, ezgiler söyleyin!","en":"Make a joyful noise to Yahweh, all the earth! Burst out and sing for joy, yes, sing praises!","es":"Cantad alegres á Jehová, toda la tierra; levantad la voz, y aplaudid, y salmead.","pt":"Celebrai com júbilo ao Senhor, todos os habitantes da terra; dai brados de alegria, regozijai-vos, e cantai louvores.","fr":"Vous, toute la terre, jetez des cris de réjouissance à l'Éternel; éclatez en cris de joie, et chantez!","de":"Jauchzet dem HERRN, alle Welt; singet, rühmet und lobet!"},"reference":{"tr":"Mezmur 98:4","en":"Psalm 98:4","es":"Salmo 98:4","pt":"Salmo 98:4","fr":"Psaume 98:4","de":"Psalm 98:4"}},{"theme":"love","text":{"tr":"Hiç kimsede, birinin dostları uğruna hayatını vermesinden daha büyük bir sevgi yoktur.","en":"Greater love has no one than this, that someone lay down his life for his friends.","es":"Nadie tiene mayor amor que este, que ponga alguno su vida por sus amigos.","pt":"Ninguém tem maior amor do que este, de dar alguém a sua vida pelos seus amigos.","fr":"Nul n'a un plus grand amour que celui qui donne sa vie pour ses amis.","de":"Niemand hat größere Liebe denn die, daß er sein Leben läßt für seine Freunde."},"reference":{"tr":"Yuhanna 15:13","en":"John 15:13","es":"Juan 15:13","pt":"João 15:13","fr":"Jean 15:13","de":"Johannes 15:13"}},{"theme":"comfort","text":{"tr":"Yahve düşen herkese destek olur, eğilenlerin hepsini doğrultur.","en":"Yahweh upholds all who fall, and raises up all those who are bowed down.","es":"Sostiene Jehová á todos los que caen, y levanta á todos los oprimidos.","pt":"O Senhor sustém a todos os que estão a cair, e levanta a todos os que estão abatidos.","fr":"L'Éternel soutient tous ceux qui sont près de tomber, et il redresse tous ceux qui sont courbés.","de":"Der HERR erhält alle, die da fallen, und richtet auf alle, die niedergeschlagen sind."},"reference":{"tr":"Mezmur 145:14","en":"Psalm 145:14","es":"Salmo 145:14","pt":"Salmo 145:14","fr":"Psaume 145:14","de":"Psalm 145:14"}},{"theme":"faith","text":{"tr":"Yeşua ona, “Yoluna git, imanın seni iyileştirdi” dedi. Hemen gözleri gördü ve yol boyunca Yeşua’nın peşinden gitti.","en":"Jesus said to him, “Go your way. Your faith has made you well.” Immediately he received his sight, and followed Jesus on the way.","es":"Y Jesús le dijo: Ve, tu fe te ha salvado. Y luego cobró la vista, y seguía á Jesús en el camino.","pt":"Disse-lhe Jesus: Vai, a tua fé te salvou. E imediatamente recuperou a vista, e foi seguindo pelo caminho.","fr":"Et Jésus lui dit: Va, ta foi t'a guéri.","de":"Jesus aber sprach zu ihm: Gehe hin; dein Glaube hat dir geholfen. Und alsbald ward er sehend und folgte ihm nach auf dem Wege."},"reference":{"tr":"Markos 10:52","en":"Mark 10:52","es":"Marcos 10:52","pt":"Marcos 10:52","fr":"Marc 10:52","de":"Markus 10:52"}},{"theme":"forgiveness","text":{"tr":"Adın uğruna, ey Yahve, günahımı bağışla, çünkü günahım büyüktür.","en":"For your name’s sake, Yahweh, pardon my iniquity, for it is great.","es":"Por amor de tu nombre, oh Jehová, perdonarás también mi pecado; porque es grande.","pt":"Por amor do teu nome, Senhor, perdoa a minha iniqüidade, pois é grande.","fr":"Pour l'amour de ton nom, ô Éternel, tu me pardonneras mon iniquité; car elle est grande.","de":"Um deines Namens willen, HERR, sei gnädig meiner Missetat, die da groß ist."},"reference":{"tr":"Mezmur 25:11","en":"Psalm 25:11","es":"Salmo 25:11","pt":"Salmo 25:11","fr":"Psaume 25:11","de":"Psalm 25:11"}},{"theme":"peace","text":{"tr":"Kötülükten uzak durun, iyilik yapın. Esenliği arayın ve ardınca gidin.","en":"Depart from evil, and do good. seek peace, and pursue it.","es":"Apártate del mal, y haz el bien; busca la paz, y síguela.","pt":"Aparta-te do mal, e faze o bem: busca a paz, e segue-a.","fr":"Garde ta langue du mal, et tes lèvres de proférer la tromperie.","de":"Behüte deine Zunge vor Bösem und deine Lippen, daß sie nicht Trug reden."},"reference":{"tr":"Mezmur 34:14","en":"Psalm 34:14","es":"Salmo 34:14","pt":"Salmo 34:14","fr":"Psaume 34:14","de":"Psalm 34:14"}},{"theme":"strength","text":{"tr":"Sana buyurmadım mı? Güçlü ve cesur ol. Korkma. Yılma, çünkü Tanrın Yahve gitmekte olduğun her yerde seninledir.”","en":"Haven’t I commanded you? Be strong and courageous. Don’t be afraid. Don’t be dismayed, for Yahweh your God is with you wherever you go.”","es":"Mira que te mando que te esfuerces y seas valiente: no temas ni desmayes, porque Jehová tu Dios será contigo en donde quiera que fueres.","pt":"Não to mandei eu? Esforça-te, e tem bom ânimo; não te atemorizes, nem te espantes; porque o Senhor teu Deus está contigo, por onde quer que andares.","fr":"Ne te l'ai-je pas commandé? Fortifie-toi et prends courage. Ne t'épouvante point et ne t'effraie de rien; car l'Éternel ton Dieu est avec toi, partout où tu iras.","de":"Siehe, ich habe dir geboten, daß du getrost und freudig seist. Laß dir nicht grauen und entsetze dich nicht; denn der HERR, dein Gott, ist mit dir in allem, was du tun wirst."},"reference":{"tr":"Yeşu 1:9","en":"Joshua 1:9","es":"Josué 1:9","pt":"Josué 1:9","fr":"Josué 1:9","de":"Josua 1:9"}},{"theme":"trust","text":{"tr":"Tanrı'ya gelince, O'nun yolu kusursuzdur. Yahve'nin sözü sınanmıştır. O kendisine sığınanların hepsine kalkandır.","en":"As for God, his way is perfect. Yahweh’s word is tested. He is a shield to all those who take refuge in him.","es":"Dios, perfecto su camino: la palabra de Jehová purificada, escudo es de todos los que en él esperan.","pt":"Quanto a Deus, o seu caminho é perfeito, e a palavra do Senhor é fiel; é ele o escudo de todos os que nele se refugiam.","fr":"La voie de Dieu est parfaite, la parole de l'Éternel est éprouvée; il est le bouclier de tous ceux qui se retirent vers lui.","de":"Gottes Wege sind vollkommen; des HERRN Reden sind durchläutert. Er ist ein Schild allen, die ihm vertrauen."},"reference":{"tr":"2. Samuel 22:31","en":"2 Samuel 22:31","es":"2 Samuel 22:31","pt":"2 Samuel 22:31","fr":"2 Samuel 22:31","de":"2. Samuel 22:31"}},{"theme":"hope","text":{"tr":"Tanrı kutsallarına bu sırrın uluslar arasında ne denli yüce ve zengin olduğunu bildirmekten hoşnut oldu. Bu sır Mesih içinizdedir, yücelik umududur.","en":"to whom God was pleased to make known what are the riches of the glory of this mystery among the Gentiles, which is Christ in you, the hope of glory;","es":"A los cuales quiso Dios hacer notorias las riquezas de la gloria de este misterio entre los Gentiles; que es Cristo en vosotros la esperanza de gloria:","pt":"a quem Deus quis fazer conhecer quais são as riquezas da glória deste mistério entre os gentios, que é Cristo em vós, a esperança da glória;","fr":"A qui Dieu a voulu faire connaître quelle est la richesse de la gloire de ce mystère parmi les Gentils; savoir: Christ en vous, l'espérance de la gloire.","de":"denen Gott gewollt hat kundtun, welcher da sei der herrliche Reichtum dieses Geheimnisses unter den Heiden, welches ist Christus in euch, der da ist die Hoffnung der Herrlichkeit."},"reference":{"tr":"Koloseliler 1:27","en":"Colossians 1:27","es":"Colosenses 1:27","pt":"Colossenses 1:27","fr":"Colossiens 1:27","de":"Kolosser 1:27"}},{"theme":"guidance","text":{"tr":"Birçok halk gidip şöyle diyecek: “Gelin, Yahve'nin dağına, Yakov'un Tanrısı'nın Evi'ne çıkalım; O bize kendi yollarını öğretecek ve biz de O'nun yollarında yürüyeceğiz.” Çünkü yasa Siyon'dan, Yahve'nin sözü Yeruşalem'den çıkacak.","en":"Many peoples shall go and say, “Come, let’s go up to the mountain of Yahweh, to the house of the God of Jacob; and he will teach us of his ways, and we will walk in his paths.” For out of Zion the law shall go out, and Yahweh’s word from Jerusalem.","es":"Y vendrán muchos pueblos, y dirán: Venid, y subamos al monte de Jehová, á la casa del Dios de Jacob; y nos enseñará en sus caminos, y caminaremos por sus sendas. Porque de Sión saldrá la ley, y de Jerusalem la palabra de Jehová.","pt":"Irão muitos povos, e dirão: Vinde, e subamos ao monte do Senhor, à casa do Deus de Jacó, para que nos ensine os seus caminhos, e andemos nas suas veredas; porque de Sião sairá a lei, e de Jerusalém a palavra do Senhor.","fr":"Et plusieurs peuples viendront et diront: Venez et montons à la montagne de l'Éternel, à la maison du Dieu de Jacob; il nous instruira de ses voies, et nous marcherons dans ses sentiers! Car la loi sortira de Sion et la parole de l'Éternel de Jérusalem.","de":"und viele Völker hingehen und sagen: Kommt, laßt uns auf den Berg des HERRN gehen, zum Hause des Gottes Jakobs, daß er uns lehre seine Wege und wir wandeln auf seinen Steigen! Denn von Zion wird das Gesetz ausgehen, und des HERRN Wort von Jerusalem."},"reference":{"tr":"Yeşaya 2:3","en":"Isaiah 2:3","es":"Isaías 2:3","pt":"Isaías 2:3","fr":"Ésaïe 2:3","de":"Jesaja 2:3"}},{"theme":"joy","text":{"tr":"O gün çok kurbanlar sundular ve sevindiler, çünkü Tanrı onları büyük sevinçle sevindirmişti; kadınlar ve çocuklar da sevindiler, öyle ki Yeruşalem'in sevinci çok uzaklardan bile duyuldu.","en":"They offered great sacrifices that day, and rejoiced; for God had made them rejoice with great joy; and the women and the children also rejoiced; so that the joy of Jerusalem was heard even far away.","es":"Y sacrificaron aquel día grandes víctimas, é hicieron alegrías; porque Dios los había recreado con grande contentamiento: alegráronse también las mujeres y muchachos; y el alborozo de Jerusalem fué oído de lejos.","pt":"Naquele dia ofereceram grandes sacrifícios, e se alegraram, pois Deus lhes dera motivo de grande alegria; também as mulheres e as crianças se alegraram, de modo que o júbilo de Jerusalém se fez ouvir longe.","fr":"On offrit aussi, en ce jour-là, de grands sacrifices, et on se réjouit, parce que Dieu leur avait donné une grande joie; même les femmes et les enfants se réjouirent; et la joie de Jérusalem fut entendue au loin.","de":"Und es wurden desselben Tages große Opfer geopfert, und sie waren fröhlich; denn Gott hatte ihnen eine große Freude gemacht, daß sich auch die Weiber und Kinder freuten, und man hörte die Freude Jerusalems ferne."},"reference":{"tr":"Nehemya 12:43","en":"Nehemiah 12:43","es":"Nehemías 12:43","pt":"Neemias 12:43","fr":"Néhémie 12:43","de":"Nehemia 12:43"}},{"theme":"love","text":{"tr":"Nefret çekişmeyi körükler, ama sevgi tüm hataları örter.","en":"Hatred stirs up strife, but love covers all wrongs.","es":"El odio despierta rencillas: mas la caridad cubrirá todas las faltas.","pt":"O ódio excita contendas; mas o amor cobre todas as transgressões.","fr":"La haine excite les querelles; mais la charité couvre toutes les fautes.","de":"Haß erregt Hader; aber Liebe deckt zu alle Übertretungen."},"reference":{"tr":"Süleyman’ın Özdeyişleri 10:12","en":"Proverbs 10:12","es":"Proverbios 10:12","pt":"Provérbios 10:12","fr":"Proverbes 10:12","de":"Sprüche 10:12"}},{"theme":"comfort","text":{"tr":"Çünkü tahtın ortasında olan Kuzu onları güdecek ve yaşam veren suların pınarlarına götürecek. Tanrı onların gözlerinden bütün gözyaşlarını silecek.”","en":"for the Lamb who is in the middle of the throne shepherds them, and leads them to springs of life-giving waters. And God will wipe away every tear from their eyes.”","es":"Porque el Cordero que está en medio del trono los pastoreará, y los guiará á fuentes vivas de aguas: y Dios limpiará toda lágrima de los ojos de ellos.","pt":"porque o Cordeiro que está no meio, diante do trono, os apascentará e os conduzirá às fontes das águas da vida; e Deus lhes enxugará dos olhos toda lágrima.","fr":"Car l'Agneau qui est au milieu du trône, les paîtra et les conduira aux sources des eaux vives, et Dieu essuiera toute larme de leurs yeux.","de":"denn das Lamm mitten im Stuhl wird sie weiden und leiten zu den lebendigen Wasserbrunnen, und Gott wird abwischen alle Tränen von ihren Augen."},"reference":{"tr":"Vahiy 7:17","en":"Revelation 7:17","es":"Apocalipsis 7:17","pt":"Apocalipse 7:17","fr":"Apocalypse 7:17","de":"Offenbarung 7:17"}},{"theme":"faith","text":{"tr":"O’nda sahip olduğumuz iman aracılığıyla cesaretle ve güvenle O’nun önüne gelebiliriz.","en":"in whom we have boldness and access in confidence through our faith in him.","es":"En el cual tenemos seguridad y entrada con confianza por la fe de él.","pt":"no qual temos ousadia e acesso em confiança, pela nossa fé nele.","fr":"En qui nous avons la liberté de nous approcher de Dieu avec confiance, par la foi que nous avons en lui.","de":"durch welchen wir haben Freudigkeit und Zugang in aller Zuversicht durch den Glauben an ihn."},"reference":{"tr":"Efesliler 3:12","en":"Ephesians 3:12","es":"Efesios 3:12","pt":"Efésios 3:12","fr":"Éphésiens 3:12","de":"Epheser 3:12"}},{"theme":"peace","text":{"tr":"Bütün insanlarla barış içinde yaşamaya ve kutsal olmaya gayret gösterin. Bu olmadan kimse Efendi’yi göremeyecek.","en":"Follow after peace with all men, and the sanctification without which no man will see the Lord,","es":"Seguid la paz con todos, y la santidad, sin la cual nadie verá al Señor:","pt":"Segui a paz com todos, e a santificação, sem a qual ninguém verá o Senhor,","fr":"Recherchez la paix avec tous, et la sanctification, sans laquelle personne ne verra le Seigneur;","de":"Jaget nach dem Frieden gegen jedermann und der Heiligung, ohne welche wird niemand den HERRN sehen,"},"reference":{"tr":"İbraniler 12:14","en":"Hebrews 12:14","es":"Hebreos 12:14","pt":"Hebreus 12:14","fr":"Hébreux 12:14","de":"Hebräer 12:14"}},{"theme":"strength","text":{"tr":"O zaman yanıt verip bana şöyle dedi: “Bu, Yahve'nin Zerubbabel’e söylediği sözdür: ‘Güçle, kuvvetle değil, ancak benim Ruhum'la’ diyor Ordular Yahvesi.","en":"Then he answered and spoke to me, saying, “This is Yahweh’s word to Zerubbabel, saying, ‘Not by might, nor by power, but by my Spirit,’ says Yahweh of Armies.","es":"Entonces respondió y hablóme, diciendo: Esta es palabra de Jehová á Zorobabel, en que se dice: No con ejército, ni con fuerza, sino con mi espíritu, ha dicho Jehová de los ejércitos.","pt":"Ele me respondeu, dizendo: Esta é a palavra do Senhor a Zorobabel, dizendo: Não por força nem por poder, mas pelo meu Espírito, diz o Senhor dos exércitos.","fr":"Alors il reprit et me dit: C'est ici la parole de l'Éternel, qu'il adresse à Zorobabel, disant: Ce n'est point par puissance, ni par force, mais par mon Esprit, a dit l'Éternel des armées.","de":"Und er antwortete und sprach zu mir: Das ist das Wort des HERRN von Serubabel: Es soll nicht durch Heer oder Kraft, sondern durch meinen Geist geschehen, spricht der HERR Zebaoth."},"reference":{"tr":"Zekeriya 4:6","en":"Zechariah 4:6","es":"Zacarías 4:6","pt":"Zacarias 4:6","fr":"Zacharie 4:6","de":"Sacharja 4:6"}},{"theme":"trust","text":{"tr":"Böylece cesaretle diyoruz ki, “Efendi benim yardımcımdır. Korkmayacağım. İnsan bana ne yapabilir?”","en":"So that with good courage we say, “The Lord is my helper. I will not fear. What can man do to me?”","es":"De tal manera que digamos confiadamente: El Señor es mi ayudador; no temeré lo que me hará el hombre.","pt":"De modo que com plena confiança digamos: O Senhor é quem me ajuda, não temerei; que me fará o homem?","fr":"De sorte que nous disons avec assurance: Le Seigneur est mon aide, et je ne craindrai point; que me fera l'homme?","de":"also daß wir dürfen sagen: \"Der HERR ist mein Helfer, ich will mich nicht fürchten; was sollte mir ein Mensch tun?\""},"reference":{"tr":"İbraniler 13:6","en":"Hebrews 13:6","es":"Hebreos 13:6","pt":"Hebreus 13:6","fr":"Hébreux 13:6","de":"Hebräer 13:6"}},{"theme":"hope","text":{"tr":"Bana kendi gerçeğinde yol göster ve öğret, çünkü sen kurtuluşumun Tanrısı’sın, bütün gün seni bekliyorum.","en":"Guide me in your truth, and teach me, For you are the God of my salvation, I wait for you all day long.","es":"Encamíname en tu verdad, y enséñame; porque tú eres el Dios de mi salud: en ti he esperado todo el día.","pt":"Guia-me na tua verdade, e ensina-me; pois tu és o Deus da minha salvação; por ti espero o dia todo.","fr":"Fais-moi marcher dans ta vérité et m'enseigne; car tu es le Dieu de ma délivrance, je m'attends à toi tout le jour.","de":"leite mich in deiner Wahrheit und lehre mich! Denn du bist der Gott, der mir hilft; täglich harre ich dein."},"reference":{"tr":"Mezmur 25:5","en":"Psalm 25:5","es":"Salmo 25:5","pt":"Salmo 25:5","fr":"Psaume 25:5","de":"Psalm 25:5"}},{"theme":"guidance","text":{"tr":"Adımlarımı sözünde pekiştir. Hiçbir kötülük bana hakim olmasın.","en":"Establish my footsteps in your word. Don’t let any iniquity have dominion over me.","es":"Ordena mis pasos con tu palabra; y ninguna iniquidad se enseñoree de mí.","pt":"Firma os meus passos na tua palavra; e não se apodere de mim iniqüidade alguma.","fr":"Affermis mes pas dans ta parole, et ne laisse aucune iniquité dominer sur moi!","de":"Laß meinen Gang gewiß sein in deinem Wort und laß kein Unrecht über mich herrschen."},"reference":{"tr":"Mezmur 119:133","en":"Psalm 119:133","es":"Salmo 119:133","pt":"Salmo 119:133","fr":"Psaume 119:133","de":"Psalm 119:133"}},{"theme":"joy","text":{"tr":"Çünkü Tanrı’nın Krallığı yiyecek içecek değil, ama doğruluk, esenlik ve Kutsal Ruh’ta sevinçtir.","en":"for God’s Kingdom is not eating and drinking, but righteousness, peace, and joy in the Holy Spirit.","es":"Que el reino de Dios no es comida ni bebida, sino justicia y paz y gozo por el Espíritu Santo.","pt":"porque o reino de Deus não consiste no comer e no beber, mas na justiça, na paz, e na alegria no Espírito Santo.","fr":"Car le royaume de Dieu ne consiste ni dans le manger, ni dans le boire, mais dans la justice, la paix, et la joie par le Saint-Esprit.","de":"Denn das Reich Gottes ist nicht Essen und Trinken, sondern Gerechtigkeit und Friede und Freude in dem heiligen Geiste."},"reference":{"tr":"Romalılar 14:17","en":"Romans 14:17","es":"Romanos 14:17","pt":"Romanos 14:17","fr":"Romains 14:17","de":"Römer 14:17"}},{"theme":"love","text":{"tr":"Sevgide korku yoktur. Tersine tam sevgi korkuyu kovar. Çünkü korkuda ceza vardır. Korkan kişi sevgide tam kılınmamıştır.","en":"There is no fear in love; but perfect love casts out fear, because fear has punishment. He who fears is not made perfect in love.","es":"En amor no hay temor; mas el perfecto amor echa fuera el temor: porque el temor tiene pena. De donde el que teme, no está perfecto en el amor.","pt":"No amor não há medo antes o perfeito amor lança fora o medo; porque o medo envolve castigo; e quem tem medo não está aperfeiçoado no amor.","fr":"Il n'y a point de crainte dans la charité, mais la parfaite charité bannit la crainte; car la crainte renferme une punition, et celui qui craint n'est pas parfait dans la charité.","de":"Furcht ist nicht in der Liebe, sondern die völlige Liebe treibt die Furcht aus; denn die Furcht hat Pein. Wer sich aber fürchtet, der ist nicht völlig in der Liebe."},"reference":{"tr":"1. Yuhanna 4:18","en":"1 John 4:18","es":"1 Juan 4:18","pt":"1 João 4:18","fr":"1 Jean 4:18","de":"1. Johannes 4:18"}},{"theme":"faith","text":{"tr":"Artık hiç kimsenin Tanrı önünde Yasa’yla aklanmadığı açıktır. Çünkü, “Doğru kişi imanla yaşayacaktır.”","en":"Now that no man is justified by the law before God is evident, for, “The righteous will live by faith.”","es":"Mas por cuanto por la ley ninguno se justifica para con Dios, queda manifiesto: Que el justo por la fe vivirá.","pt":"É evidente que pela lei ninguém é justificado diante de Deus, porque: O justo viverá da fé;","fr":"Et que nul ne soit justifié devant Dieu par la loi, cela est évident; parce que: Le juste vivra par la foi.","de":"Daß aber durchs Gesetz niemand gerecht wird vor Gott, ist offenbar; denn \"der Gerechte wird seines Glaubens leben.\""},"reference":{"tr":"Galatyalılar 3:11","en":"Galatians 3:11","es":"Gálatas 3:11","pt":"Gálatas 3:11","fr":"Galates 3:11","de":"Galater 3:11"}},{"theme":"peace","text":{"tr":"Boyunduruğumu takının ve benden öğrenin. Çünkü ben yumuşak huylu ve alçakgönüllüyüm. Ve böylece canlarınız rahat bulur.","en":"Take my yoke upon you, and learn from me, for I am gentle and humble in heart; and you will find rest for your souls.","es":"Llevad mi yugo sobre vosotros, y aprended de mí, que soy manso y humilde de corazón; y hallaréis descanso para vuestras almas.","pt":"Tomai sobre vós o meu jugo, e aprendei de mim, que sou manso e humilde de coração; e achareis descanso para as vossas almas.","fr":"Chargez-vous de mon joug, et apprenez de moi, parce que je suis doux et humble de cour, et vous trouverez le repos de vos âmes;","de":"Nehmet auf euch mein Joch und lernet von mir; denn ich bin sanftmütig und von Herzen demütig; so werdet ihr Ruhe finden für eure Seelen."},"reference":{"tr":"Matta 11:29","en":"Matthew 11:29","es":"San Mateo 11:29","pt":"Mateus 11:29","fr":"Matthieu 11:29","de":"Matthäus 11:29"}},{"theme":"strength","text":{"tr":"Kısa bir süre acı çektikten sonra sizi Mesih Yeşua aracılığıyla sonsuz yüceliğine çağıran tüm lütfun kaynağı olan Tanrı sizi yetkinleştirip, pekiştirecek, güçlendirip temellendirecektir.","en":"But may the God of all grace, who called you to his eternal glory by Christ Jesus, after you have suffered a little while, perfect, establish, strengthen, and settle you.","es":"Mas el Dios de toda gracia, que nos ha llamado á su gloria eterna por Jesucristo, después que hubiereis un poco de tiempo padecido, él mismo os perfeccione, confirme, corrobore y establezca.","pt":"E o Deus de toda a graça, que em Cristo vos chamou à sua eterna glória, depois de haverdes sofrido por um pouco, ele mesmo vos há de aperfeiçoar, confirmar e fortalecer.","fr":"Or, que le Dieu de toute grâce, qui nous a appelés à sa gloire éternelle en Jésus-Christ, après que vous aurez un peu souffert, vous rende parfaits, fermes, forts et inébranlables.","de":"Der Gott aber aller Gnade, der uns berufen hat zu seiner ewigen Herrlichkeit in Christo Jesu, der wird euch, die ihr eine kleine Zeit leidet, vollbereiten, stärken, kräftigen, gründen."},"reference":{"tr":"1. Petrus 5:10","en":"1 Peter 5:10","es":"1 Pedro 5:10","pt":"1 Pedro 5:10","fr":"1 Pierre 5:10","de":"1. Petrus 5:10"}},{"theme":"trust","text":{"tr":"Yüreğimiz O’nda sevinç bulur, çünkü biz O'nun kutsal adına güvendik.","en":"For our heart rejoices in him, because we have trusted in his holy name.","es":"Por tanto en él se alegrará nuestro corazón, porque en su santo nombre hemos confiado.","pt":"Pois nele se alegra o nosso coração, porquanto temos confiado no seu santo nome.","fr":"Car notre cœur se réjouit en lui; car nous nous confions en son saint nom.","de":"Denn unser Herz freut sich sein, und wir trauen auf seinen heiligen Namen."},"reference":{"tr":"Mezmur 33:21","en":"Psalm 33:21","es":"Salmo 33:21","pt":"Salmo 33:21","fr":"Psaume 33:21","de":"Psalm 33:21"}},{"theme":"hope","text":{"tr":"Ertelenen umut yüreği hasta eder, ama hasret giderildiğinde yaşam ağacıdır.","en":"Hope deferred makes the heart sick, but when longing is fulfilled, it is a tree of life.","es":"La esperanza que se prolonga, es tormento del corazón: mas árbol de vida es el deseo cumplido.","pt":"A esperança adiada entristece o coração; mas o desejo cumprido é árvore devida.","fr":"L'espérance différée fait languir le cœur; mais le souhait accompli est comme l'arbre de vie.","de":"Die Hoffnung, die sich verzieht, ängstet das Herz; wenn's aber kommt, was man begehrt, das ist wie ein Baum des Lebens."},"reference":{"tr":"Süleyman’ın Özdeyişleri 13:12","en":"Proverbs 13:12","es":"Proverbios 13:12","pt":"Provérbios 13:12","fr":"Proverbes 13:12","de":"Sprüche 13:12"}},{"theme":"guidance","text":{"tr":"Kurtarıcın, İsrael'in Kutsalı Yahve şöyle diyor: “Yararlı olanı sana öğreten, gitmen gereken yolda sana öncülük eden, ben Tanrın Yahve'yim.","en":"Yahweh, your Redeemer, the Holy One of Israel says: “I am Yahweh your God, who teaches you to profit, who leads you by the way that you should go.","es":"Así ha dicho Jehová, Redentor tuyo, el Santo de Israel: Yo Jehová Dios tuyo, que te enseña provechosamente, que te encamina por el camino que andas.","pt":"Assim diz o Senhor, o teu Redentor, o Santo de Israel: Eu sou o Senhor, o teu Deus, que te ensina o que é útil, e te guia pelo caminho em que deves andar.","fr":"Ainsi a dit l'Éternel, ton Rédempteur, le Saint d'Israël: Je suis l'Éternel ton Dieu, qui t'enseigne ce qui est bon, qui te conduis dans le chemin où tu dois marcher.","de":"So spricht der HERR, dein Erlöser, der Heilige in Israel: Ich bin der HERR, dein Gott, der dich lehrt, was nützlich ist, und leitet dich auf dem Wege, den du gehst."},"reference":{"tr":"Yeşaya 48:17","en":"Isaiah 48:17","es":"Isaías 48:17","pt":"Isaías 48:17","fr":"Ésaïe 48:17","de":"Jesaja 48:17"}},{"theme":"joy","text":{"tr":"Uzaklarda oturanlar da senin harikalarından korkarlar. Sabahın şafağını ve akşamı sevinç ezgileriyle çağırırsın.","en":"They also who dwell in faraway places are afraid at your wonders. You call the morning’s dawn and the evening with songs of joy.","es":"Por tanto los habitadores de los fines de la tierra temen de tus maravillas. Tú haces alegrar las salidas de la mañana y de la tarde.","pt":"Os que habitam os confins da terra são tomados de medo à vista dos teus sinais; tu fazes exultar de júbilo as saídas da manhã e da tarde.","fr":"Il apaise le bruit des mers, le bruit de leurs flots et la rumeur des peuples.","de":"der du stillest das Brausen des Meers, das Brausen seiner Wellen und das Toben der Völker,"},"reference":{"tr":"Mezmur 65:8","en":"Psalm 65:8","es":"Salmo 65:8","pt":"Salmo 65:8","fr":"Psaume 65:8","de":"Psalm 65:8"}},{"theme":"love","text":{"tr":"Ey sevgililer, eğer Tanrı bizi böyle sevdiyse, biz de birbirimizi sevmeliyiz.","en":"Beloved, if God loved us in this way, we also ought to love one another.","es":"Amados, si Dios así nos ha amado, debemos también nosotros amarnos unos á otros.","pt":"Amados, se Deus assim nos amou, nós também devemos amar-nos uns aos outros.","fr":"Bien-aimés, si Dieu nous a ainsi aimés, nous devons aussi nous aimer les uns les autres.","de":"Ihr Lieben, hat uns Gott also geliebt, so sollen wir uns auch untereinander lieben."},"reference":{"tr":"1. Yuhanna 4:11","en":"1 John 4:11","es":"1 Juan 4:11","pt":"1 João 4:11","fr":"1 Jean 4:11","de":"1. Johannes 4:11"}},{"theme":"faith","text":{"tr":"İman sayesinde Avraham miras olarak alacağı yere gitmek üzere çağrıldığında, itaat etti. Nereye gittiğini bilmeden yola çıktı.","en":"By faith, Abraham, when he was called, obeyed to go out to the place which he was to receive for an inheritance. He went out, not knowing where he went.","es":"Por la fe Abraham, siendo llamado, obedeció para salir al lugar que había de recibir por heredad; y salió sin saber dónde iba.","pt":"Pela fé Abraão, sendo chamado, obedeceu, saindo para um lugar que havia de receber por herança; e saiu, sem saber para onde ia.","fr":"Par la foi, Abraham, étant appelé, obéit, pour aller au pays qu'il devait recevoir en héritage, et partit, ne sachant où il allait.","de":"Durch den Glauben ward gehorsam Abraham, da er berufen ward, auszugehen in das Land, das er ererben sollte; und ging aus und wußte nicht wo er hinkäme."},"reference":{"tr":"İbraniler 11:8","en":"Hebrews 11:8","es":"Hebreos 11:8","pt":"Hebreus 11:8","fr":"Hébreux 11:8","de":"Hebräer 11:8"}},{"theme":"peace","text":{"tr":"Yattım ve uyudum. Uyandım, çünkü Yahve bana destek oldu.","en":"I laid myself down and slept. I awakened; for Yahweh sustains me.","es":"Yo me acosté, y dormí, y desperté; porque Jehová me sostuvo.","pt":"Eu me deito e durmo; acordo, pois o Senhor me sustenta.","fr":"Je crie de ma voix à l'Éternel, et il me répond de sa montagne sainte. (Sélah.)","de":"Ich rufe an mit meiner Stimme den HERRN; so erhört er mich von seinem heiligen Berge. (Sela.)"},"reference":{"tr":"Mezmur 3:5","en":"Psalm 3:5","es":"Salmo 3:5","pt":"Salmo 3:5","fr":"Psaume 3:5","de":"Psalm 3:5"}},{"theme":"strength","text":{"tr":"Bense gücüne ezgiler söyleyeceğim. Evet, sabahları sevgi dolu iyiliğini yüksek sesle ezgiyle dile getireceğim. Çünkü sen benim yüksek kulem, sıkıntılı günümde sığınağım oldun.","en":"But I will sing of your strength. Yes, I will sing aloud of your loving kindness in the morning. For you have been my high tower, a refuge in the day of my distress.","es":"Yo empero cantaré tu fortaleza, y loaré de mañana tu misericordia: porque has sido mi amparo y refugio en el día de mi angustia.","pt":"Eu, porém, cantarei a tua força; pela manhã louvarei com alegria a tua benignidade, porquanto tens sido para mim uma fortaleza, e refúgio no dia da minha angústia.","fr":"Qu'ils aillent çà et là, cherchant à manger, et qu'ils passent la nuit sans être rassasiés!","de":"Sie laufen hin und her um Speise und murren, wenn sie nicht satt werden."},"reference":{"tr":"Mezmur 59:16","en":"Psalm 59:16","es":"Salmo 59:16","pt":"Salmo 59:16","fr":"Psaume 59:16","de":"Psalm 59:16"}},{"theme":"trust","text":{"tr":"Yahve’ye sığınmak, insana güvenmekten iyidir.","en":"It is better to take refuge in Yahweh, than to put confidence in man.","es":"Mejor es esperar en Jehová que esperar en hombre.","pt":"É melhor refugiar-se no Senhor do que confiar no homem.","fr":"Mieux vaut se retirer vers l'Éternel que de s'assurer en l'homme.","de":"Es ist gut, auf den HERRN zu vertrauen, und nicht sich verlassen auf Menschen."},"reference":{"tr":"Mezmur 118:8","en":"Psalm 118:8","es":"Salmo 118:8","pt":"Salmo 118:8","fr":"Psaume 118:8","de":"Psalm 118:8"}},{"theme":"hope","text":{"tr":"Yahve’yi bekle. Güçlü ol ve yüreğin cesaretli olsun. Evet, Yahve'yi bekle.","en":"Wait for Yahweh. Be strong, and let your heart take courage. Yes, wait for Yahweh.","es":"Aguarda á Jehová; esfuérzate, y aliéntese tu corazón: sí, espera á Jehová.","pt":"Espera tu pelo Senhor; anima-te, e fortalece o teu coração; espera, pois, pelo Senhor.","fr":"Attends-toi à l'Éternel, demeure ferme, que ton cœur se fortifie; oui, attends-toi à l'Éternel!","de":"Harre des HERRN! Sei getrost und unverzagt und harre des HERRN!"},"reference":{"tr":"Mezmur 27:14","en":"Psalm 27:14","es":"Salmo 27:14","pt":"Salmo 27:14","fr":"Psaume 27:14","de":"Psalm 27:14"}},{"theme":"guidance","text":{"tr":"Yahve'den korkan adam kimdir? Yahve ona seçeceği yolu bildirecektir.","en":"What man is he who fears Yahweh? He shall instruct him in the way that he shall choose.","es":"¿Quién es el hombre que teme á Jehová? El le enseñará el camino que ha de escoger.","pt":"Qual é o homem que teme ao Senhor? Este lhe ensinará o caminho que deve escolher.","fr":"Quel est l'homme qui craint l'Éternel? Il lui enseignera le chemin qu'il doit choisir.","de":"Wer ist der, der den HERRN fürchtet? Er wird ihn unterweisen den besten Weg."},"reference":{"tr":"Mezmur 25:12","en":"Psalm 25:12","es":"Salmo 25:12","pt":"Salmo 25:12","fr":"Psaume 25:12","de":"Psalm 25:12"}},{"theme":"joy","text":{"tr":"Bu nedenle kurtuluş kuyularından sevinçle su çekeceksiniz.","en":"Therefore with joy you will draw water out of the wells of salvation.","es":"Sacaréis aguas con gozo de las fuentes de la salud.","pt":"Portanto com alegria tirareis águas das fontes da salvação.","fr":"Et vous puiserez des eaux avec joie aux sources du salut.","de":"Ihr werdet mit Freuden Wasser schöpfen aus den Heilsbrunnen"},"reference":{"tr":"Yeşaya 12:3","en":"Isaiah 12:3","es":"Isaías 12:3","pt":"Isaías 12:3","fr":"Ésaïe 12:3","de":"Jesaja 12:3"}},{"theme":"love","text":{"tr":"Beni seven kişi, buyruklarım kendisinde olup onları tutandır. Beni seven, Babam tarafından sevilecektir. Ben de onu seveceğim ve kendimi ona göstereceğim.”","en":"One who has my commandments, and keeps them, that person is one who loves me. One who loves me will be loved by my Father, and I will love him, and will reveal myself to him.”","es":"El que tiene mis mandamientos, y los guarda, aquél es el que me ama; y el que me ama, será amado de mi Padre, y yo le amaré, y me manifestaré á él.","pt":"Aquele que tem os meus mandamentos e os guarda, esse é o que me ama; e aquele que me ama será amado de meu Pai, e eu o amarei, e me manifestarei a ele.","fr":"Celui qui a mes commandements, et qui les garde, c'est celui-là qui m'aime; et celui qui m'aime sera aimé de mon Père, et je l'aimerai, et je me ferai connaître à lui.","de":"Wer meine Gebote hat und hält sie, der ist es, der mich liebt. Wer mich aber liebt, der wird von meinem Vater geliebt werden, und ich werde ihn lieben und mich ihm offenbaren."},"reference":{"tr":"Yuhanna 14:21","en":"John 14:21","es":"Juan 14:21","pt":"João 14:21","fr":"Jean 14:21","de":"Johannes 14:21"}},{"theme":"faith","text":{"tr":"Biliyorsunuz ki, imanınızın sınanması dayanıklılık üretir.","en":"knowing that the testing of your faith produces endurance.","es":"Sabiendo que la prueba de vuestra fe obra paciencia.","pt":"sabendo que a aprovação da vossa fé produz a perseverança;","fr":"Sachant que l'épreuve de votre foi produit la patience.","de":"und wisset, daß euer Glaube, wenn er rechtschaffen ist, Geduld wirkt."},"reference":{"tr":"Yakup 1:3","en":"James 1:3","es":"Santiago 1:3","pt":"Tiago 1:3","fr":"Jacques 1:3","de":"Jakobus 1:3"}},{"theme":"peace","text":{"tr":"Keşke buyruklarımı dinleseydin! O zaman esenliğin ırmak gibi, doğruluğun da denizin dalgaları gibi olurdu.","en":"Oh that you had listened to my commandments! Then your peace would have been like a river, and your righteousness like the waves of the sea.","es":"¡Ojalá miraras tú á mis mandamientos! fuera entonces tu paz como un río, y tu justicia como las ondas de la mar.","pt":"Ah! se tivesses dado ouvidos aos meus mandamentos! então seria a tua paz como um rio, e a tua justiça como as ondas do mar;","fr":"Oh! si tu étais attentif à mes commandements! Ta paix serait comme un fleuve, et ta justice comme les flots de la mer.","de":"O daß du auf meine Gebote merktest, so würde dein Friede sein wie ein Wasserstrom, und deine Gerechtigkeit wie Meereswellen;"},"reference":{"tr":"Yeşaya 48:18","en":"Isaiah 48:18","es":"Isaías 48:18","pt":"Isaías 48:18","fr":"Ésaïe 48:18","de":"Jesaja 48:18"}},{"theme":"strength","text":{"tr":"Yahve’yi ve O’nun gücünü arayın. Yüzünü daima arayın.","en":"Seek Yahweh and his strength. Seek his face forever more.","es":"Buscad á Jehová, y su fortaleza: buscad siempre su rostro.","pt":"Buscai ao Senhor e a sua força; buscai a sua face continuamente.","fr":"Recherchez l'Éternel et sa force; cherchez continuellement sa face!","de":"Fraget nach dem HERRN und nach seiner Macht, suchet sein Antlitz allewege!"},"reference":{"tr":"Mezmur 105:4","en":"Psalm 105:4","es":"Salmo 105:4","pt":"Salmo 105:4","fr":"Psaume 105:4","de":"Psalm 105:4"}},{"theme":"trust","text":{"tr":"Yahve’ye güven ve iyilik et. Ülkede otur ve güvenli otlakların tadını çıkar.","en":"Trust in Yahweh, and do good. Dwell in the land, and enjoy safe pasture.","es":"Espera en Jehová, y haz bien; vivirás en la tierra, y en verdad serás alimentado.","pt":"Confia no Senhor e faze o bem; assim habitarás na terra, e te alimentarás em segurança.","fr":"Confie-toi en l'Éternel, et fais le bien; habite la terre, et fais de la vérité ta pâture.","de":"Hoffe auf den HERRN und tue Gutes; bleibe im Lande und nähre dich redlich."},"reference":{"tr":"Mezmur 37:3","en":"Psalm 37:3","es":"Salmo 37:3","pt":"Salmo 37:3","fr":"Psaume 37:3","de":"Psalm 37:3"}},{"theme":"hope","text":{"tr":"Avraham, umutsuzluğa karşı, birçok ulusun babası olacağına, “Senin soyun böyle olacak”","en":"Besides hope, Abraham in hope believed, to the end that he might become a father of many nations, according to that which had been spoken, “So will your offspring be.”","es":"El creyó en esperanza contra esperanza, para venir á ser padre de muchas gentes, conforme á lo que le había sido dicho: Así será tu simiente.","pt":"O qual, em esperança, creu contra a esperança, para que se tornasse pai de muitas nações, conforme o que lhe fora dito: Assim será a tua descendência;","fr":"Espérant contre tout sujet d'espérer, il a cru qu'il deviendrait le père de plusieurs nations, selon ce qui avait été dit: Telle sera ta postérité.","de":"Und er hat geglaubt auf Hoffnung, da nichts zu hoffen war, auf daß er würde ein Vater vieler Völker, wie denn zu ihm gesagt ist: \"Also soll dein Same sein.\""},"reference":{"tr":"Romalılar 4:18","en":"Romans 4:18","es":"Romanos 4:18","pt":"Romanos 4:18","fr":"Romains 4:18","de":"Römer 4:18"}},{"theme":"guidance","text":{"tr":"O zaman yolunda güvenlik içinde yürüyeceksin. Ayağın tökezlemeyecek.","en":"Then you shall walk in your way securely. Your foot won’t stumble.","es":"Entonces andarás por tu camino confiadamente, y tu pie no tropezará.","pt":"Então andarás seguro pelo teu caminho, e não tropeçará o teu pé.","fr":"Alors tu marcheras en assurance par ton chemin, et ton pied ne heurtera point.","de":"Dann wirst du sicher wandeln auf deinem Wege, daß dein Fuß sich nicht stoßen wird."},"reference":{"tr":"Süleyman’ın Özdeyişleri 3:23","en":"Proverbs 3:23","es":"Proverbios 3:23","pt":"Provérbios 3:23","fr":"Proverbes 3:23","de":"Sprüche 3:23"}},{"theme":"joy","text":{"tr":"Ama doğrular sevinsin. Tanrı'nın önünde coşsunlar. Evet, neşeyle coşsunlar.","en":"But let the righteous be glad. Let them rejoice before God. Yes, let them rejoice with gladness.","es":"Mas los justos se alegrarán: gozarse han delante de Dios, y saltarán de alegría.","pt":"Mas alegrem-se os justos, e se regozijem na presença de Deus, e se encham de júbilo.","fr":"Tu les dissiperas comme la fumée se dissipe; comme la cire se fond au feu, ainsi périront les méchants devant Dieu.","de":"Vertreibe sie, wie der Rauch vertrieben wird; wie das Wachs zerschmilzt vom Feuer, so müssen umkommen die Gottlosen vor Gott."},"reference":{"tr":"Mezmur 68:3","en":"Psalm 68:3","es":"Salmo 68:3","pt":"Salmo 68:3","fr":"Psaume 68:3","de":"Psalm 68:3"}},{"theme":"love","text":{"tr":"Sevginiz iki yüzlü olmasın. Kötülükten nefret edin, iyiliğe sarılın.","en":"Let love be without hypocrisy. Abhor that which is evil. Cling to that which is good.","es":"El amor sea sin fingimiento: aborreciendo lo malo, llegándoos á lo bueno;","pt":"O amor seja não fingido. Aborrecei o mal e apegai-vos ao bem.","fr":"Que la charité soit sans hypocrisie. Ayez le mal en horreur, attachez-vous fortement au bien.","de":"Die Liebe sei nicht falsch. Hasset das Arge, hanget dem Guten an."},"reference":{"tr":"Romalılar 12:9","en":"Romans 12:9","es":"Romanos 12:9","pt":"Romanos 12:9","fr":"Romains 12:9","de":"Römer 12:9"}},{"theme":"peace","text":{"tr":"Çünkü bize bir çocuk doğdu. Bize bir oğul verildi; yönetim onun omuzlarında olacak. Onun adı Harika Öğütçü, Güçlü Tanrı, Ebedi Baba, Esenlik Hükümdarı olacak.","en":"For to us a child is born. To us a son is given; and the government will be on his shoulders. His name will be called Wonderful, Counselor, Mighty God, Everlasting Father, Prince of Peace.","es":"Porque un niño nos es nacido, hijo nos es dado; y el principado sobre su hombro: y llamaráse su nombre Admirable, Consejero, Dios fuerte, Padre eterno, Príncipe de paz.","pt":"Porque um menino nos nasceu, um filho se nos deu; e o governo estará sobre os seus ombros; e o seu nome será: Maravilhoso Conselheiro, Deus Forte, Pai Eterno, Príncipe da Paz.","fr":"Pour accroître l'empire, pour donner une prospérité sans fin au trône de David et à son royaume; pour l'établir et l'affermir dans l'équité et dans la justice, dès maintenant et à toujours. La jalousie de l'Éternel des armées fera cela.","de":"auf daß seine Herrschaft groß werde und des Friedens kein Ende auf dem Stuhl Davids und in seinem Königreich, daß er's zurichte und stärke mit Gericht und Gerechtigkeit von nun an bis in Ewigkeit. Solches wird tun der Eifer des HERRN Zebaoth."},"reference":{"tr":"Yeşaya 9:6","en":"Isaiah 9:6","es":"Isaías 9:6","pt":"Isaías 9:6","fr":"Ésaïe 9:6","de":"Jesaja 9:6"}},{"theme":"strength","text":{"tr":"Tanrı bir kez konuştu; Ben şunu iki kez işittim: Güç Tanrı’ya aittir.","en":"God has spoken once; twice I have heard this, that power belongs to God.","es":"Una vez habló Dios; dos veces he oído esto: Que de Dios es la fortaleza.","pt":"Uma vez falou Deus, duas vezes tenho ouvido isto: que o poder pertence a Deus.","fr":"Ne vous confiez pas dans la violence, et ne soyez pas séduits par la rapine; si les richesses abondent, n'y mettez pas votre cœur.","de":"Verlasset euch nicht auf Unrecht und Frevel, haltet euch nicht zu solchem, das eitel ist; fällt euch Reichtum zu, so hänget das Herz nicht daran."},"reference":{"tr":"Mezmur 62:11","en":"Psalm 62:11","es":"Salmo 62:11","pt":"Salmo 62:11","fr":"Psaume 62:11","de":"Psalm 62:11"}},{"theme":"trust","text":{"tr":"Bütün yüreğinle Yahve'ye güven, kendi anlayışına dayanma.","en":"Trust in Yahweh with all your heart, and don’t lean on your own understanding.","es":"Fíate de Jehová de todo tu corazón, y no estribes en tu prudencia.","pt":"Confia no Senhor de todo o teu coração, e não te estribes no teu próprio entendimento.","fr":"Confie-toi en l'Éternel de tout ton cœur, et ne t'appuie point sur ta prudence.","de":"Verlaß dich auf den HERRN von ganzem Herzen und verlaß dich nicht auf deinen Verstand;"},"reference":{"tr":"Süleyman’ın Özdeyişleri 3:5","en":"Proverbs 3:5","es":"Proverbios 3:5","pt":"Provérbios 3:5","fr":"Proverbes 3:5","de":"Sprüche 3:5"}},{"theme":"hope","text":{"tr":"Madem umudumuz sende, sevgi dolu iyiliğin üzerimizde olsun, ey Yahve!","en":"Let your loving kindness be on us, Yahweh, since we have hoped in you.","es":"Sea tu misericordia, oh Jehová, sobre nosotros, como esperamos en ti.","pt":"Seja a tua benignidade, Senhor, sobre nós, assim como em ti esperamos.","fr":"Que ta bonté soit sur nous, ô Éternel! comme nous nous attendons à toi.","de":"Deine Güte, HERR, sei über uns, wie wir auf dich hoffen."},"reference":{"tr":"Mezmur 33:22","en":"Psalm 33:22","es":"Salmo 33:22","pt":"Salmo 33:22","fr":"Psaume 33:22","de":"Psalm 33:22"}},{"theme":"guidance","text":{"tr":"orada bile elin bana yol gösterir, sağ elin beni tutar.","en":"Even there your hand will lead me, and your right hand will hold me.","es":"Aun allí me guiará tu mano, y me asirá tu diestra.","pt":"ainda ali a tua mão me guiará e a tua destra me susterá.","fr":"Là même, ta main me conduira, et ta droite me saisira.","de":"so würde mich doch deine Hand daselbst führen und deine Rechte mich halten."},"reference":{"tr":"Mezmur 139:10","en":"Psalm 139:10","es":"Salmo 139:10","pt":"Salmo 139:10","fr":"Psaume 139:10","de":"Psalm 139:10"}},{"theme":"joy","text":{"tr":"Ne mutlu seni alkışlamayı öğrenen halka. Senin varlığının ışığında yürürler, ey Yahve.","en":"Blessed are the people who learn to acclaim you. They walk in the light of your presence, Yahweh.","es":"Bienaventurado el pueblo que sabe aclamarte: andarán, oh Jehová, á la luz de tu rostro.","pt":"Bem-aventurado o povo que conhece o som festivo, que anda, ó Senhor, na luz da tua face,","fr":"La justice et l'équité sont la base de ton trône; la grâce et la vérité marchent devant ta face.","de":"Gerechtigkeit und Gericht ist deines Stuhles Festung; Gnade und Wahrheit sind vor deinem Angesicht."},"reference":{"tr":"Mezmur 89:15","en":"Psalm 89:15","es":"Salmo 89:15","pt":"Salmo 89:15","fr":"Psaume 89:15","de":"Psalm 89:15"}},{"theme":"love","text":{"tr":"Yaptığınız her şeyi sevgiyle yapın.","en":"Let all that you do be done in love.","es":"Todas vuestras cosas sean hechas con caridad.","pt":"Todas as vossas obras sejam feitas em amor.","fr":"Que tout ce que vous faites, se fasse avec charité.","de":"Alle eure Dinge lasset in der Liebe geschehen!"},"reference":{"tr":"1. Korintliler 16:14","en":"1 Corinthians 16:14","es":"1 Corintios 16:14","pt":"1 Coríntios 16:14","fr":"1 Corinthiens 16:14","de":"1. Korinther 16:14"}},{"theme":"peace","text":{"tr":"Öyleyse, esenlik getiren ve birbirimizin gelişmesini sağlayan şeylerin peşinden gidelim.","en":"So then, let us follow after things which make for peace, and things by which we may build one another up.","es":"Así que, sigamos lo que hace á la paz, y á la edificación de los unos á los otros.","pt":"Assim, pois, sigamos as coisas que servem para a paz e as que contribuem para a edificação mútua.","fr":"Recherchons donc les choses qui tendent à la paix, et à l'édification mutuelle.","de":"Darum laßt uns dem nachstreben, was zum Frieden dient und was zur Besserung untereinander dient."},"reference":{"tr":"Romalılar 14:19","en":"Romans 14:19","es":"Romanos 14:19","pt":"Romanos 14:19","fr":"Romains 14:19","de":"Römer 14:19"}},{"theme":"strength","text":{"tr":"Bu nedenle yorulmayız; ama her ne kadar dış varlığımız bozuluyorsa da, iç varlığımız günden güne yenileniyor.","en":"Therefore we don’t faint, but though our outward man is decaying, yet our inward man is renewed day by day.","es":"Por tanto, no desmayamos: antes aunque este nuestro hombre exterior se va desgastando, el interior empero se renueva de día en día.","pt":"Por isso não desfalecemos; mas ainda que o nosso homem exterior se esteja consumindo, o interior, contudo, se renova de dia em dia.","fr":"C'est pourquoi nous ne perdons point courage, et si notre homme extérieur se détruit, l'intérieur se renouvelle de jour en jour;","de":"Darum werden wir nicht müde; sondern, ob unser äußerlicher Mensch verdirbt, so wird doch der innerliche von Tag zu Tag erneuert."},"reference":{"tr":"2. Korintliler 4:16","en":"2 Corinthians 4:16","es":"2 Corintios 4:16","pt":"2 Coríntios 4:16","fr":"2 Corinthiens 4:16","de":"2. Korinther 4:16"}},{"theme":"trust","text":{"tr":"Çünkü benim umudum, gençliğimden beri güvendiğim sensin, ey Efendi Yahve.","en":"For you are my hope, Lord Yahweh; my confidence from my youth.","es":"Porque tú, oh Señor Jehová, eres mi esperanza: seguridad mía desde mi juventud.","pt":"Pois tu és a minha esperança, Senhor Deus; tu és a minha confiança desde a minha mocidade.","fr":"Car tu es mon attente, Seigneur Éternel, ma confiance dès ma jeunesse.","de":"Denn du bist meine Zuversicht, Herr, HERR, meine Hoffnung von meiner Jugend an."},"reference":{"tr":"Mezmur 71:5","en":"Psalm 71:5","es":"Salmo 71:5","pt":"Salmo 71:5","fr":"Psaume 71:5","de":"Psalm 71:5"}},{"theme":"hope","text":{"tr":"Ne mutlu yardımcısı Yakov'un Tanrısı olana, umudu Tanrısı Yahve olana:","en":"Happy is he who has the God of Jacob for his help, whose hope is in Yahweh, his God:","es":"Bienaventurado aquel en cuya ayuda es el Dios de Jacob, cuya esperanza es en Jehová su Dios:","pt":"Bem-aventurado aquele que tem o Deus de Jacó por seu auxílio, e cuja esperança está no Senhor seu Deus","fr":"Heureux celui qui a le Dieu de Jacob pour aide, et dont l'attente est en l'Éternel son Dieu,","de":"Wohl dem, des Hilfe der Gott Jakobs ist; des Hoffnung auf den HERRN, seinem Gott, steht;"},"reference":{"tr":"Mezmur 146:5","en":"Psalm 146:5","es":"Salmo 146:5","pt":"Salmo 146:5","fr":"Psaume 146:5","de":"Psalm 146:5"}},{"theme":"guidance","text":{"tr":"Ey Yahve, düşmanlarıma karşı doğruluğunla bana yol göster. Yolunu önümde düzle.","en":"Lead me, Yahweh, in your righteousness because of my enemies. Make your way straight before my face.","es":"Guíame, Jehová, en tu justicia á causa de mis enemigos; endereza delante de mí tu camino.","pt":"Guia-me, Senhor, na tua justiça, por causa dos meus inimigos; aplana diante de mim o teu caminho.","fr":"Mais moi, dans l'abondance de ta grâce, j'entrerai dans ta maison, je me prosternerai dans ton saint temple, avec crainte.","de":"Ich aber will in dein Haus gehen auf deine große Güte und anbeten gegen deinen heiligen Tempel in deiner Furcht."},"reference":{"tr":"Mezmur 5:8","en":"Psalm 5:8","es":"Salmo 5:8","pt":"Salmo 5:8","fr":"Psaume 5:8","de":"Psalm 5:8"}},{"theme":"joy","text":{"tr":"Sizin için ne zaman dua etsem hepiniz için sevinçle dilekte bulunuyorum.","en":"always in every request of mine on behalf of you all, making my requests with joy,","es":"Siempre en todas mis oraciones haciendo oración por todos vosotros con gozo,","pt":"fazendo sempre, em todas as minhas orações, súplicas por todos vós com alegria","fr":"Priant toujours pour vous tous avec joie, dans toutes mes prières,","de":"(welches ich allezeit tue in allem meinem Gebet für euch alle, und tue das Gebet mit Freuden),"},"reference":{"tr":"Filipililer 1:4","en":"Philippians 1:4","es":"Filipenses 1:4","pt":"Filipenses 1:4","fr":"Philippiens 1:4","de":"Philipper 1:4"}},{"theme":"love","text":{"tr":"Mesih’in de bizi sevdiği ve bizim için kendisini hoş kokulu bir sunu ve kurban olarak Tanrı’ya teslim ettiği gibi, siz de sevgide yürüyün.","en":"Walk in love, even as Christ also loved you, and gave himself up for us, an offering and a sacrifice to God for a sweet-smelling fragrance.","es":"Y andad en amor, como también Cristo nos amó, y se entregó á sí mismo por nosotros, ofrenda y sacrificio á Dios en olor suave.","pt":"e andai em amor, como Cristo também vos amou, e se entregou a si mesmo por nós, como oferta e sacrifício a Deus, em cheiro suave.","fr":"Et marchez dans la charité, comme le Christ qui nous a aimés, et s'est offert lui-même à Dieu pour nous en oblation et en victime d'agréable odeur.","de":"und wandelt in der Liebe, gleichwie Christus uns hat geliebt und sich selbst dargegeben für uns als Gabe und Opfer, Gott zu einem süßen Geruch."},"reference":{"tr":"Efesliler 5:2","en":"Ephesians 5:2","es":"Efesios 5:2","pt":"Efésios 5:2","fr":"Éphésiens 5:2","de":"Epheser 5:2"}},{"theme":"peace","text":{"tr":"Ruh’un birliğini esenlik bağıyla korumaya gayret edin.","en":"being eager to keep the unity of the Spirit in the bond of peace.","es":"Solícitos á guardar la unidad del Espíritu en el vínculo de la paz.","pt":"procurando diligentemente guardar a unidade do Espírito no vínculo da paz.","fr":"Vous appliquant à conserver l'unité de l'esprit, par le lien de la paix.","de":"und seid fleißig, zu halten die Einigkeit im Geist durch das Band des Friedens:"},"reference":{"tr":"Efesliler 4:3","en":"Ephesians 4:3","es":"Efesios 4:3","pt":"Efésios 4:3","fr":"Éphésiens 4:3","de":"Epheser 4:3"}},{"theme":"strength","text":{"tr":"Tanrı onun ortasındadır. Sarsılmaz o. Gün doğarken Tanrı ona yardım eder.","en":"God is within her. She shall not be moved. God will help her at dawn.","es":"Dios está en medio de ella; no será conmovida: Dios la ayudará al clarear la mañana.","pt":"Deus está no meio dela; não será abalada; Deus a ajudará desde o raiar da alva.","fr":"Le fleuve et ses canaux réjouissent la cité de Dieu, le lieu saint des demeures du Très-Haut.","de":"Dennoch soll die Stadt Gottes fein lustig bleiben mit ihren Brünnlein, da die heiligen Wohnungen des Höchsten sind."},"reference":{"tr":"Mezmur 46:5","en":"Psalm 46:5","es":"Salmo 46:5","pt":"Salmo 46:5","fr":"Psaume 46:5","de":"Psalm 46:5"}},{"theme":"trust","text":{"tr":"Aranızda Yahve'den korkan, Hizmetkârının sözünü dinleyen kimdir? Karanlıkta yürüyen ve ışığı olmayan kişi, Yahve'nin adına güvensin ve Tanrısı'na güvensin.","en":"Who among you fears Yahweh, and obeys the voice of his servant? He who walks in darkness, and has no light, let him trust in Yahweh’s name, and rely on his God.","es":"¿Quién hay entre vosotros que teme á Jehová, y oye la voz de su siervo? el que anda en tinieblas y carece de luz, confíe en el nombre de Jehová, y apóyese en su Dios.","pt":"Quem há entre vós que tema ao Senhor? ouça ele a voz do seu servo. Aquele que anda em trevas, e não tem luz, confie no nome do Senhor, e firme-se sobre o seu Deus.","fr":"Qui d'entre vous craint l'Éternel, qui écoute la voix de son serviteur? Que celui qui marche dans les ténèbres, et qui n'a point de lumière, se confie au nom de l'Éternel, et qu'il s'appuie sur son Dieu.","de":"Wer ist unter euch, der den HERRN fürchtet, der seines Knechtes Stimme gehorche? Der im Finstern wandelt und scheint ihm kein Licht, der hoffe auf den HERRN und verlasse sich auf seinen Gott."},"reference":{"tr":"Yeşaya 50:10","en":"Isaiah 50:10","es":"Isaías 50:10","pt":"Isaías 50:10","fr":"Ésaïe 50:10","de":"Jesaja 50:10"}},{"theme":"hope","text":{"tr":"Sonun için umut var.” diyor Yahve. “Çocukların kendi topraklarına geri dönecekler.”","en":"There is hope for your latter end,” says Yahweh. “Your children will come again to their own territory.","es":"Esperanza también hay para tu fin, dice Jehová, y los hijos volverán á su término.","pt":"E há esperança para o teu futuro, diz o Senhor; pois teus filhos voltarão para os seus termos.","fr":"Il y a de l'espérance pour ton avenir, dit l'Éternel; tes enfants reviendront dans leur territoire.","de":"und deine Nachkommen haben viel Gutes zu erwarten, spricht der HERR; denn deine Kinder sollen wieder in ihre Grenze kommen."},"reference":{"tr":"Yeremya 31:17","en":"Jeremiah 31:17","es":"Jeremías 31:17","pt":"Jeremias 31:17","fr":"Jérémie 31:17","de":"Jeremia 31:17"}},{"theme":"guidance","text":{"tr":"İnsanın adımları Yahve'dendir. O zaman insan kendi yollarını nasıl anlayabilir?","en":"A man’s steps are from Yahweh; how then can man understand his way?","es":"De Jehová son los pasos del hombre: ¿cómo pues entenderá el hombre su camino?","pt":"Os passos do homem são dirigidos pelo Senhor; como, pois, poderá o homem entender o seu caminho?","fr":"Cest l'Éternel qui dirige les pas de l'homme; comment donc l'homme comprendrait-il sa voie?","de":"Jedermanns Gänge kommen vom HERRN. Welcher Mensch versteht seinen Weg?"},"reference":{"tr":"Süleyman’ın Özdeyişleri 20:24","en":"Proverbs 20:24","es":"Proverbios 20:24","pt":"Provérbios 20:24","fr":"Proverbes 20:24","de":"Sprüche 20:24"}},{"theme":"joy","text":{"tr":"kâhinleriniz doğrulukla giyinsin. Kutsallarınız sevinçle haykırsın!”","en":"Let your priests be clothed with righteousness. Let your saints shout for joy!”","es":"Tus sacerdotes se vistan de justicia, y regocíjense tus santos.","pt":"Vistam-se os teus sacerdotes de justiça, e exultem de júbilo os teus santos.","fr":"Que tes sacrificateurs soient revêtus de justice, et que tes bien-aimés chantent de joie!","de":"Deine Priester laß sich kleiden mit Gerechtigkeit und deine Heiligen sich freuen."},"reference":{"tr":"Mezmur 132:9","en":"Psalm 132:9","es":"Salmo 132:9","pt":"Salmo 132:9","fr":"Psaume 132:9","de":"Psalm 132:9"}},{"theme":"love","text":{"tr":"Hiç kimse hiçbir zaman Tanrı’yı görmedi. Birbirimizi seversek, Tanrı içimizde kalır ve O’nun sevgisi bizde tamamlanmış olur.","en":"No one has seen God at any time. If we love one another, God remains in us, and his love has been perfected in us.","es":"Ninguno vió jamás á Dios. Si nos amamos unos á otros, Dios está en nosotros, y su amor es perfecto en nosotros:","pt":"Ninguém jamais viu a Deus; e nos amamos uns aos outros, Deus permanece em nós, e o seu amor é em nós aperfeiçoado.","fr":"Personne n'a jamais vu Dieu: si nous nous aimons les uns les autres, Dieu demeure en nous, et son amour est accompli en nous.","de":"Niemand hat Gott jemals gesehen. So wir uns untereinander lieben, so bleibt Gott in uns, und seine Liebe ist völlig in uns."},"reference":{"tr":"1. Yuhanna 4:12","en":"1 John 4:12","es":"1 Juan 4:12","pt":"1 João 4:12","fr":"1 Jean 4:12","de":"1. Johannes 4:12"}},{"theme":"peace","text":{"tr":"Kötülükten sakınıp iyilik etsin. Esenliği arasın, ve onun ardınca gitsin.","en":"Let him turn away from evil, and do good. Let him seek peace, and pursue it.","es":"Apártase del mal, y haga bien; busque la paz, y sígala.","pt":"aparte-se do mal, e faça o bem; busque a paz, e siga-a.","fr":"Qu'il se détourne du mal, et fasse le bien; qu'il cherche la paix, et la poursuive.","de":"Er wende sich vom Bösen und tue Gutes; er suche Frieden und jage ihm nach."},"reference":{"tr":"1. Petrus 3:11","en":"1 Peter 3:11","es":"1 Pedro 3:11","pt":"1 Pedro 3:11","fr":"1 Pierre 3:11","de":"1. Petrus 3:11"}},{"theme":"strength","text":{"tr":"Baba kendi yüceliğinin zenginliğine göre Ruhu’yla iç varlığınızı kudretle güçlendirmesini, iman aracılığıyla Mesih’in yüreklerinizde bulunmasını dilerim. Bütün kutsallarla birlikte sonuna dek sevgide köklenip temellenmiş olarak, Mesih’in sevgisinin ne kadar geniş ve uzun, yüksek ve derin olduğunu anlamaya, bilgiyi aşan bu sevgiyi bilmeye gücünüz yetsin. Öyle ki, Tanrı’nın bütün doluluğuyla dolasınız.","en":"that he would grant you, according to the riches of his glory, that you may be strengthened with power through his Spirit in the inward man;","es":"Que os dé, conforme á las riquezas de su gloria, el ser corroborados con potencia en el hombre interior por su Espíritu.","pt":"para que, segundo as riquezas da sua glória, vos conceda que sejais robustecidos com poder pelo seu Espírito no homem interior;","fr":"Afin que, selon les richesses de sa gloire, il vous donne d'être puissamment fortifiés par son Esprit, dans l'homme intérieur,","de":"daß er euch Kraft gebe nach dem Reichtum seiner Herrlichkeit, stark zu werden durch seinen Geist an dem inwendigen Menschen,"},"reference":{"tr":"Efesliler 3:16","en":"Ephesians 3:16","es":"Efesios 3:16","pt":"Efésios 3:16","fr":"Éphésiens 3:16","de":"Epheser 3:16"}},{"theme":"trust","text":{"tr":"Canımız Yahve’yi bekler. O bizim yardımımız ve kalkanımızdır.","en":"Our soul has waited for Yahweh. He is our help and our shield.","es":"Nuestra alma esperó á Jehová; nuestra ayuda y nuestro escudo es él.","pt":"A nossa alma espera no Senhor; ele é o nosso auxílio e o nosso escudo.","fr":"Notre âme s'attend à l'Éternel; il est notre aide et notre bouclier.","de":"Unsre Seele harrt auf den HERRN; er ist unsre Hilfe und Schild."},"reference":{"tr":"Mezmur 33:20","en":"Psalm 33:20","es":"Salmo 33:20","pt":"Salmo 33:20","fr":"Psaume 33:20","de":"Psalm 33:20"}},{"theme":"hope","text":{"tr":"Neden umutsuzluk içindesin, ey canım? Neden içim huzursuz? Tanrı’ya umut bağla! Çünkü yine O’nu öveceğim. Kurtarıcım, yardımcım, Tanrım benim.","en":"Why are you in despair, my soul? Why are you disturbed within me? Hope in God! For I shall still praise him: my Savior, my helper, and my God.","es":"¿Por qué te abates, oh alma mía, y por qué te conturbas en mí? Espera á Dios; porque aun le tengo de alabar; es él salvamento delante de mí, y el Dios mío.","pt":"Por que estás abatida, ó minha alma? e por que te perturbas dentro de mim? Espera em Deus, pois ainda o louvarei, a ele que é o meu socorro, e o meu Deus.","fr":"Pourquoi t'abats-tu, mon âme, et pourquoi frémis-tu en moi? Attends-toi à Dieu, car je le louerai encore; il est mon salut et mon Dieu!","de":"Was betrübst du dich, meine Seele, und bist so unruhig in mir? Harre auf Gott! denn ich werde ihm noch danken, daß er meines Angesichts Hilfe und mein Gott ist."},"reference":{"tr":"Mezmur 43:5","en":"Psalm 43:5","es":"Salmo 43:5","pt":"Salmo 43:5","fr":"Psaume 43:5","de":"Psalm 43:5"}},{"theme":"love","text":{"tr":"Doğruluğu ve adaleti sever. Dünya Yahve’nin sevgi dolu iyiliğiyle doludur.","en":"He loves righteousness and justice. The earth is full of the loving kindness of Yahweh.","es":"El ama justicia y juicio: de la misericordia de Jehová está llena la tierra.","pt":"Ele ama a retidão e a justiça; a terra está cheia da benignidade do Senhor.","fr":"Il aime la justice et l'équité; la terre est pleine de la bonté de l'Éternel.","de":"Er liebt die Gerechtigkeit und Gericht; die Erde ist voll der Güte des HERRN."},"reference":{"tr":"Mezmur 33:5","en":"Psalm 33:5","es":"Salmo 33:5","pt":"Salmo 33:5","fr":"Psaume 33:5","de":"Psalm 33:5"}},{"theme":"peace","text":{"tr":"Ey Yahve, bize esenliği sen sağlayacaksın, çünkü bizim için bütün işlerimizi de sen yaptın.","en":"Yahweh, you will ordain peace for us, for you have also done all our work for us.","es":"Jehová, tú nos depararás paz; porque también obraste en nosotros todas nuestras obras.","pt":"Senhor, tu hás de estabelecer para nós a paz; pois tu fizeste para nós todas as nossas obras.","fr":"Éternel, tu nous donneras la paix; car tout ce que nous faisons, c'est toi qui l'accomplis pour nous.","de":"Aber uns, HERR, wirst du Frieden schaffen; denn alles, was wir ausrichten, das hast du uns gegeben."},"reference":{"tr":"Yeşaya 26:12","en":"Isaiah 26:12","es":"Isaías 26:12","pt":"Isaías 26:12","fr":"Ésaïe 26:12","de":"Jesaja 26:12"}},{"theme":"strength","text":{"tr":"Ne mutlu, gücü sende olanlara, yüreklerini Siyon’u ziyaret etmeye koyanlara.","en":"Blessed are those whose strength is in you; who have set their hearts on a pilgrimage.","es":"Bienaventurado el hombre que tiene su fortaleza en ti; en cuyo corazón están tus caminos.","pt":"Bem-aventurados os homens cuja força está em ti, em cujo coração os caminhos altos.","fr":"Heureux ceux qui habitent ta maison, qui te louent incessamment! Sélah (pause).","de":"Wohl denen, die in deinem Hause wohnen; die loben dich immerdar. (Sela.)"},"reference":{"tr":"Mezmur 84:5","en":"Psalm 84:5","es":"Salmo 84:5","pt":"Salmo 84:5","fr":"Psaume 84:5","de":"Psalm 84:5"}},{"theme":"trust","text":{"tr":"Çünkü o, suların yanına dikilmiş, köklerini ırmak kenarına yayan, sıcak gelince korkmayan, ama yaprağı yeşil olan, ve kuraklık yılında kaygılanmayan ağaca benzer. Meyve vermekten geri kalmaz.","en":"For he will be as a tree planted by the waters, who spreads out its roots by the river, and will not fear when heat comes, but its leaf will be green; and will not be concerned in the year of drought. It won’t cease from yielding fruit.","es":"Porque él será como el árbol plantado junto á las aguas, que junto á la corriente echará sus raices, y no verá cuando viniere el calor, sino que su hoja estará verde; y en el año de sequía no se fatigará, ni dejará de hacer fruto.","pt":"Porque é como a árvore plantada junto às águas, que estende as suas raízes para o ribeiro, e não receia quando vem o calor, mas a sua folha fica verde; e no ano de sequidão não se afadiga, nem deixa de dar fruto.","fr":"Il sera comme un arbre planté près des eaux, qui étend ses racines le long d'une eau courante; qui, lorsque vient la chaleur, ne la craint point, mais dont la feuille est verte; il n'est point en peine dans l'année de sécheresse, et ne cesse pas de porter du fruit.","de":"Der ist wie ein Baum, am Wasser gepflanzt und am Bach gewurzelt. Denn obgleich eine Hitze kommt, fürchtet er sich doch nicht, sondern seine Blätter bleiben grün, und sorgt nicht, wenn ein dürres Jahr kommt sondern er bringt ohne Aufhören Früchte."},"reference":{"tr":"Yeremya 17:8","en":"Jeremiah 17:8","es":"Jeremías 17:8","pt":"Jeremias 17:8","fr":"Jérémie 17:8","de":"Jeremia 17:8"}},{"theme":"hope","text":{"tr":"Yardımım yeri ve göğü yaratan Yahve'den gelecek.","en":"My help comes from Yahweh, who made heaven and earth.","es":"Mi socorro viene de Jehová, que hizo los cielos y la tierra.","pt":"O meu socorro vem do Senhor, que fez os céus e a terra.","fr":"Mon secours vient de l'Éternel, qui a fait les cieux et la terre.","de":"Meine Hilfe kommt von dem HERRN, der Himmel und Erde gemacht hat."},"reference":{"tr":"Mezmur 121:2","en":"Psalm 121:2","es":"Salmo 121:2","pt":"Salmo 121:2","fr":"Psaume 121:2","de":"Psalm 121:2"}},{"theme":"love","text":{"tr":"Sonsuz yaşam için Efendimiz Yeşua Mesih’in merhametini beklerken kendinizi Tanrı’nın sevgisinde tutun.","en":"Keep yourselves in God’s love, looking for the mercy of our Lord Jesus Christ to eternal life.","es":"Conservaos en el amor de Dios, esperando la misericordia de nuestro Señor Jesucristo, para vida eterna.","pt":"conservai-vos no amor de Deus, esperando a misericórdia de nosso Senhor Jesus Cristo para a vida eterna.","fr":"Conservez-vous dans l'amour de Dieu, en attendant la miséricorde de notre Seigneur Jésus-Christ pour la vie éternelle.","de":"und erhaltet euch in der Liebe Gottes, und wartet auf die Barmherzigkeit unsers HERRN Jesu Christi zum ewigen Leben."},"reference":{"tr":"Yahuda 1:21","en":"Jude 1:21","es":"Judas 1:21","pt":"Judas 1:21","fr":"Jude 1:21","de":"Judas 1:21"}},{"theme":"strength","text":{"tr":"Yahve, bize lütfet. Seni bekledik. Her sabah gücümüz ol, sıkıntı anında da kurtuluşumuz ol.","en":"Yahweh, be gracious to us. We have waited for you. Be our strength every morning, our salvation also in the time of trouble.","es":"Oh Jehová, ten misericordia de nosotros, á ti hemos esperado: tú, brazo de ellos en la mañana, sé también nuestra salud en tiempo de la tribulación.","pt":"ç Senhor, tem misericórdia de nós; por ti temos esperado. Sê tu o nosso braço cada manhã, como também a nossa salvação no tempo da tribulação.","fr":"Éternel, aie pitié de nous! Nous nous attendons à toi. Sois le bras de ceux-ci dès le matin, et notre délivrance au temps de la détresse!","de":"HERR, sei uns gnädig, denn auf dich harren wir; sei ihr Arm alle Morgen, dazu unser Heil zur Zeit der Trübsal!"},"reference":{"tr":"Yeşaya 33:2","en":"Isaiah 33:2","es":"Isaías 33:2","pt":"Isaías 33:2","fr":"Ésaïe 33:2","de":"Jesaja 33:2"}},{"theme":"trust","text":{"tr":"Seni kanatlarıyla örter. O’nun kanatları altına sığınırsın. O’nun sadakati senin kalkanın ve siperindir.","en":"He will cover you with his feathers. Under his wings you will take refuge. His faithfulness is your shield and rampart.","es":"Con sus plumas te cubrirá, y debajo de sus alas estarás seguro: escudo y adarga es su verdad.","pt":"Ele te cobre com as suas penas, e debaixo das suas asas encontras refúgio; a sua verdade é escudo e broquel.","fr":"Il te couvrira de ses plumes, et tu auras retraite sous ses ailes; sa vérité sera ton bouclier et ton écu.","de":"Er wird dich mit seinen Fittichen decken, und deine Zuversicht wird sein unter seinen Flügeln. Seine Wahrheit ist Schirm und Schild,"},"reference":{"tr":"Mezmur 91:4","en":"Psalm 91:4","es":"Salmo 91:4","pt":"Salmo 91:4","fr":"Psaume 91:4","de":"Psalm 91:4"}},{"theme":"hope","text":{"tr":"Bilgeliği bilmek de canın için öyledir. Eğer onu bulduysan, ödülü de vardır, umudun kesilmez.","en":"so you shall know wisdom to be to your soul; if you have found it, then there will be a reward, your hope will not be cut off.","es":"Tal será el conocimiento de la sabiduría á tu alma: si la hallares tendrá recompensa, y al fin tu esperanza no será cortada.","pt":"Sabe que é assim a sabedoria para a tua alma: se a achares, haverá para ti recompensa, e não será malograda a tua esperança.","fr":"Telle sera la connaissance de la sagesse à ton âme; quand tu l'auras trouvée, il y aura une bonne issue, et ton attente ne sera point trompée.","de":"Also lerne die Weisheit für deine Seele. Wo du sie findest, so wird's hernach wohl gehen, und deine Hoffnung wird nicht umsonst sein."},"reference":{"tr":"Süleyman’ın Özdeyişleri 24:14","en":"Proverbs 24:14","es":"Proverbios 24:14","pt":"Provérbios 24:14","fr":"Proverbes 24:14","de":"Sprüche 24:14"}},{"theme":"strength","text":{"tr":"Efendi Yahve’nin büyük işleriyle geleceğim. Senin doğruluğundan, yalnızca senin doğruluğundan söz edeceğim.","en":"I will come with the mighty acts of the Lord Yahweh. I will make mention of your righteousness, even of yours alone.","es":"Vendré á las valentías del Señor Jehová: haré memoria de sola tu justicia.","pt":"Virei na força do Senhor Deus; farei menção da tua justiça, da tua tão somente.","fr":"J'irai louant tes grandes œuvres, Seigneur Éternel; je célébrerai ta seule justice.","de":"Ich gehe einher in der Kraft des Herrn HERRN; ich preise deine Gerechtigkeit allein."},"reference":{"tr":"Mezmur 71:16","en":"Psalm 71:16","es":"Salmo 71:16","pt":"Salmo 71:16","fr":"Psaume 71:16","de":"Psalm 71:16"}},{"theme":"strength","text":{"tr":"Tanrım, her ihtiyacınızı kendi zenginliğine göre görkemle Mesih Yeşua’da karşılayacaktır.","en":"My God will supply every need of yours according to his riches in glory in Christ Jesus.","es":"Mi Dios, pues, suplirá todo lo que os falta conforme á sus riquezas en gloria en Cristo Jesús.","pt":"Meu Deus suprirá todas as vossas necessidades segundo as suas riquezas na glória em Cristo Jesus.","fr":"Et mon Dieu pourvoira aussi à tous vos besoins, selon ses richesses, avec gloire, en Jésus-Christ.","de":"Mein Gott aber fülle aus alle eure Notdurft nach seinem Reichtum in der Herrlichkeit in Christo Jesu."},"reference":{"tr":"Filipililer 4:19","en":"Philippians 4:19","es":"Filipenses 4:19","pt":"Filipenses 4:19","fr":"Philippiens 4:19","de":"Philipper 4:19"}},{"theme":"strength","text":{"tr":"elimi onunla pekiştireceğim. Kolum da onu güçlendirecektir.","en":"with whom my hand shall be established. My arm will also strengthen him.","es":"Mi mano será firme con él, mi brazo también lo fortificará.","pt":"A minha mão será sempre com ele, e o meu braço o fortalecerá.","fr":"J'ai trouvé David mon serviteur, je l'ai oint de mon huile sainte;","de":"Ich habe gefunden meinen Knecht David; ich habe ihn gesalbt mit meinem heiligen Öl."},"reference":{"tr":"Mezmur 89:21","en":"Psalm 89:21","es":"Salmo 89:21","pt":"Salmo 89:21","fr":"Psaume 89:21","de":"Psalm 89:21"}},{"theme":"strength","text":{"tr":"Ama siz güçlü olun! Elleriniz gevşek olmasın, çünkü emeğiniz ödüllendirilecektir.”","en":"But you be strong, and don’t let your hands be slack; for your work will be rewarded.”","es":"Esforzaos empero vosotros, y no desfallezcan vuestras manos; que salario hay para vuestra obra.","pt":"Vós, porém, esforçai-vos, e não desfaleçam as vossas mãos; porque a vossa obra terá uma recompensa.","fr":"Mais vous, fortifiez-vous, et que vos mains ne soient point lâches; car il y a un salaire pour ce que vous ferez.","de":"Ihr aber seid getrost und tut eure Hände nicht ab; denn euer Werk hat seinen Lohn."},"reference":{"tr":"2. Tarihler 15:7","en":"2 Chronicles 15:7","es":"2 Crónicas 15:7","pt":"2 Crônicas 15:7","fr":"2 Chroniques 15:7","de":"2. Chronik 15:7"}}];

/** Size of the rotation pool (locale-independent). */
export const verseCount = versePool.length;

const cache: Partial<Record<Locale, DailyVerse[]>> = {};

/** The daily-verse pool with text + reference in the given locale (cached). */
export function getVerses(locale: Locale): DailyVerse[] {
  return (cache[locale] ??= versePool.map((e) => ({
    text: e.text[locale] ?? e.text.en,
    reference: e.reference[locale] ?? e.reference.en,
    theme: e.theme,
  })));
}
